[10000] = {id = 10000, name = "統一戰線", story = "露露啦的AVG裝甲，型號和款式上相對來說比較落後，但是露露啦本人對其卻愛不釋手。或許是因為穿上它可以顯得個子更高吧。", attackname = "呼~試試新戰錘吧！", painter = "/", voiceexcellence = "小倉唯", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10000", coordinate = "10000", generalattack = "0", midposition = "0.1,3.8", topposition = "0.1,7.65", bottomposition = "0,0", buffplacer = "68002_0;60000_20", zjeffect = "68188_0", debut = "68000_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "19_0.6_16_60_3_1_4", delay = "19_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10000001] = {id = 10000001, name = "蛋黃醬戰線", story = "“防曬霜在哪？……怎麼盡是些吃的東西……”\n“這是……蛋黃醬？滑滑的，黏黏的……”\n“嗚嗚嗚，要變成蛋黃醬烤肉套餐了。”", attackname = "呼~試試新戰錘吧！", painter = "/", voiceexcellence = "小倉唯", backgroundpic = "ABOriginal/Role/10000001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10000001/WatchSpine/Watch_3D_front.prefab", interaction = "10000001", coordinate = "10000001", generalattack = "0", midposition = "0.1,3.8", topposition = "0.1,7.65", bottomposition = "0,0", buffplacer = "68002_0;60000_20", zjeffect = "68188_0", debut = "68000_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "19_0.6_16_60_3_1_4", delay = "19_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4000000108", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10000001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10001] = {id = 10001, name = "榮光的旗幟", story = "朱利烏斯·馮·尼采的AVG裝甲，由家族上一任使用者傳承，多年戰爭的炮火洗禮下浩氣未減，依然如新。", attackname = "人類……終將獲勝！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10001", coordinate = "10001", generalattack = "0", midposition = "0.42,3.9", topposition = "0.3,7.58", bottomposition = "0,0", buffplacer = "68025_0", zjeffect = "68181_0", debut = "68024_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.5_8_60_2_0.5_3,20_0.6_16_60_3_0.5_4,15_0.6_12_60_0.5_2.6_2.2", delay = "7_0.3,20_0.5,15_0.2", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10001001] = {id = 10001001, name = "少女的夜宴", story = "一襲私人訂制的華貴禮服，為朱利烏斯所有。\n燈盞輝映，觥籌交錯，黑雪紡與多瑙緞相織而成的禮裙。一場獨屬於駕駛員們的盛宴，正在朱利烏斯的家族支持下隆重開幕。", attackname = "原罪，污穢的血……", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/10001001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10001001", coordinate = "10001001", generalattack = "0", midposition = "0.42,3.9", topposition = "0.3,7.58", bottomposition = "0,0", buffplacer = "68025_0", zjeffect = "68181_0", debut = "68024_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.5_8_60_2_0.5_3,20_0.6_16_60_3_0.5_4,15_0.6_12_60_0.5_2.6_2.2", delay = "7_0.3,20_0.5,15_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4000100108", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10001001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10001002] = {id = 10001002, name = "衝刺的起點", story = "賽車不是一個人的遊戲，向勝利衝刺的必要條件是在起點時就高昂的比賽狀態。引擎，輪胎，油箱……甚至車手本人的狀態都需要確認。而朱利烏斯的工作正是確保這一切都萬無一失。", attackname = "向着终点冲刺吧！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/10001002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10001002/WatchSpine/Watch_3D_front.prefab", interaction = "10001002", coordinate = "10001002", generalattack = "0", midposition = "0.42,3.9", topposition = "0.3,7.58", bottomposition = "0,0", buffplacer = "68025_0", zjeffect = "68181_0", debut = "68024_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.5_8_60_2_0.5_3,20_0.6_16_60_3_0.5_4,15_0.6_12_60_0.5_2.6_2.2", delay = "7_0.3,20_0.5,15_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4000100206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10001002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10001003] = {id = 10001003, name = "無法拒絕的吻", story = "熱鬧散去，屋裡只剩下妳和朱利烏斯做聖誕布置的收尾工作。“掛上槲寄生就結束了……”朱利烏斯忽然停了下來，“領航……在我的家鄉……有一個傳說……說是槲寄生下的親吻是不能拒絕的……嗯……沒什麼。”", attackname = "這是給你的禮物！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/10001003/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10001003", coordinate = "10001003", generalattack = "0", midposition = "0.42,3.9", topposition = "0.3,7.58", bottomposition = "0,0", buffplacer = "68025_0", zjeffect = "68181_0", debut = "68024_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.5_8_60_2_0.5_3,20_0.6_16_60_3_0.5_4,15_0.6_12_60_0.5_2.6_2.2", delay = "7_0.3,20_0.5,15_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4000100306", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10002] = {id = 10002, name = "獨眼傭兵", story = "漢克的專屬AVG裝甲。雖然蒂娜再三抗議，但漢克還是在這身護甲上使用了大量和以前傭兵時期類似的設計。比起冷冰冰的測試數據，她還是更信任那些陪自己出生入死的老夥計。", attackname = "就這點程度？", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10002", coordinate = "10002", generalattack = "0", midposition = "0,3.42", topposition = "0,7.2", bottomposition = "0,0", buffplacer = "68032_0", zjeffect = "0", debut = "68031_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "35_1_20_100_3_0.5_4", delay = "35_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10002001] = {id = 10002001, name = "校內體能訓練（？）", story = "作為特聘體育老師的漢克給自己的課程安排了意外完整的訓練清單，包括但不限於徒手訓練，自由重量訓練，固定器械訓練等等……差不多該有人去告訴她體育課和健身不是一回事了。", attackname = "就這點程度？", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "ABOriginal/Role/10002001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10002001", coordinate = "10002001", generalattack = "0", midposition = "0,3.42", topposition = "0,7.2", bottomposition = "0,0", buffplacer = "68032_0", zjeffect = "0", debut = "68031_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "35_1_20_100_3_0.5_4", delay = "35_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,10002001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10003] = {id = 10003, name = "其徐如林", story = "森村鬼之介專屬的AVG裝甲。由九州總部硏制而成。被賦予“鬼”之名的裝甲，雖然性能卓越，卻全然不顧使用者的感受，或許只有鬼之介這般的“惡鬼”才能完全駕馭。", attackname = "成為……惡鬼。", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10003", coordinate = "10003", generalattack = "0", midposition = "0.15,3.5", topposition = "0.15,6.98", bottomposition = "0,0", buffplacer = "68034_0;60000_14;60000_21;60000_54", zjeffect = "68035_0", debut = "68033_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "12_0.2_8_60_1.5_2_0.5,8_0.2_8_60_-1.5_-2_-0.5,12_0.1_12_60_0.8_2.8_0,19_0.4_18_60_1.5_3.5_1", delay = "12_0.2,8_0.2,12_0.2,19_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10003001] = {id = 10003001, name = "筆繪山水", story = "山水之美，難以用筆墨全然描摹，即便親身遊歷其間，也只能窺見其壯麗的一隅。\n“如果是巨大的我，或許能看到更多……”面對鬼之介的請求，你不忍心拒絶。另外，山水間佇立的巨大少女，也不失爲另一番別樣的美景。", attackname = "成為……惡鬼。", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/10003001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10003001", coordinate = "10003001", generalattack = "0", midposition = "0.15,3.5", topposition = "0.15,6.98", bottomposition = "0,0", buffplacer = "68034_0;60000_14;60000_21;60000_54", zjeffect = "68035_0", debut = "68033_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "12_0.2_8_60_1.5_2_0.5,8_0.2_8_60_-1.5_-2_-0.5,12_0.1_12_60_0.8_2.8_0,19_0.4_18_60_1.5_3.5_1", delay = "12_0.2,8_0.2,12_0.2,19_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4000300106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,10003001,tz_qd_0_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
