[10005] = {id = 10005, name = "百般隨心", story = "華戀專屬的AVG裝甲，由九州總部特研製。裝甲外形參考了大量九州主流的傳統服裝。為了突出其攻擊性能，而犧牲了其防禦性能，所幸通過防衛機器人得以彌補。", attackname = "保持氣感——", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10005", coordinate = "10005", generalattack = "0", midposition = "0.09,4.01", topposition = "-0.1,7.14", bottomposition = "0,0", buffplacer = "68094_0;68095_0;68096_0;68097_0", zjeffect = "68098_0", debut = "68093_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "23_0.4_13_60_1.8_2.6_0.8", delay = "23_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10005001] = {id = 10005001, name = "禁止通行", story = "距離第一堂課的鈴聲響起還有不到300秒，卻遲遲不見華戀的身影。“禁止通行”似乎是一句詛咒，破洞處的鐵絲不僅勾住了華戀的褲角還勾住了她的時間。", attackname = "保持氣感——", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "ABOriginal/Role/10005001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10005001/WatchSpine/Watch_3D_front.prefab", interaction = "10005001", coordinate = "10005001", generalattack = "0", midposition = "0.09,4.01", topposition = "-0.1,7.14", bottomposition = "0,0", buffplacer = "68094_0;68095_0;68096_0;68097_0", zjeffect = "68098_0", debut = "68093_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "23_0.4_13_60_1.8_2.6_0.8", delay = "23_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4000500109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10005001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
