[10007] = {id = 10007, name = "海色的新娘", story = "海姬專屬的AVG裝甲。極端依賴水環境的AVG裝甲，在陸地上能夠提供的幫助極為有限。作為隊伍中最年長的人，海姬擁有最為嫻熟的水下作戰技巧，加上這身裝備，這些使得她成了鯨落最不可或缺的支柱。", attackname = "不准碰我的領航！", painter = "/", voiceexcellence = "福山あさき", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10007", coordinate = "10007", generalattack = "0", midposition = "0.3,4.39", topposition = "0,8.06", bottomposition = "0,0", buffplacer = "68147_0;68148_25", zjeffect = "0", debut = "68146_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "22_0.3_15_60_1.8_2.8_0.6", delay = "22_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10007001] = {id = 10007001, name = "入夜前的绝味料理", story = "精心准备中的晚宴，毫无防备的后背，圣诞节的厨房是海姬的战场。将汤勺握在手中，繁杂的食材们前赴后继，在海姬的指挥下冲向那沸腾着爱的咖喱海洋。圣诞节的新娘或是平安夜的美味料理，哪一个领航想先行品尝？", attackname = "不准碰我的領航！", painter = "/", voiceexcellence = "福山あさき", backgroundpic = "ABOriginal/Role/10007001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10007001", coordinate = "10007001", generalattack = "0", midposition = "0.3,4.39", topposition = "0,8.06", bottomposition = "0,0", buffplacer = "68147_0;68148_25", zjeffect = "0", debut = "68146_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "22_0.3_15_60_1.8_2.8_0.6", delay = "22_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4000700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10007001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
