[10009] = {id = 10009, name = "戲言系魔法少女", story = "摩根勒菲的專屬AVG裝甲，由一名沉迷魔法少女幻想的科學家研製。用虛構的物質編織而成的裝備。能否發揮出預計的效能憑藉的是使用者的想像力。", attackname = "魔术开幕！", painter = "/", voiceexcellence = "石原夏織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10009", coordinate = "10009", generalattack = "0", midposition = "0.05,5", topposition = "0,8.68", bottomposition = "0,0", buffplacer = "68229_0;68230_10;68230_25;68230_52;68231_52", zjeffect = "68232_0;68233_18", debut = "68228_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 21, bulletvelocity = "0", strike = "11_0.3_15_60_1.8_2.4_1,15_0.35_18_60_2.8_3.4_1.5,26_0.55_24_60_2.5_3.6_2", delay = "11_0.3,15_0.2,26_0.5", admission = "200,10,1.3,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10009001] = {id = 10009001, name = "世界末日的大魔術", story = "末日鐘聲響起，九顆恒星的光芒聚焦在舞臺中央。天空和星辰齊碎，海浪與高山同醉。世紀初的大魔術！世紀末的大魔術！世界最後的大魔術！", attackname = "魔术开幕！", painter = "/", voiceexcellence = "石原夏織", backgroundpic = "ABOriginal/Role/10009001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10009001/WatchSpine/Watch_3D_front.prefab", interaction = "10009001", coordinate = "10009001", generalattack = "0", midposition = "0.05,5", topposition = "0,8.68", bottomposition = "0,0", buffplacer = "68229_0;68230_10;68230_25;68230_52;68231_52", zjeffect = "68232_0;68233_18", debut = "68228_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 21, bulletvelocity = "0", strike = "11_0.3_15_60_1.8_2.4_1,15_0.35_18_60_2.8_3.4_1.5,26_0.55_24_60_2.5_3.6_2", delay = "11_0.3,15_0.2,26_0.5", admission = "200,10,1.3,9", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch2,idle,4000900107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_hd_0_998", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10010] = {id = 10010, name = "海妖", story = "阿萊塔的AVG裝甲，第三研究室防衛班制式裝備，輕薄貼身而又不失強度，適合海域作戰。", attackname = "請注視著我吧！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10010", coordinate = "10010", generalattack = "0", midposition = "0.85,3.15", topposition = "1.06,6.71", bottomposition = "0,0", buffplacer = "68235_0", zjeffect = "68236_0", debut = "68234_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.4_14_60_1.2_3_0.5,25_0.2_10_60_2.1_1.2_0.4", delay = "7_0.6,25_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10010001] = {id = 10010001, name = "偶像的秘密", story = "阿萊塔的一件珍藏服裝。\n你應邀而來，參加了阿萊塔只為你一人準備的演出，然而在你面前展露的，是緋紅的偶像從未向人展示的秘密的一面——", attackname = "請注視著我吧！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "ABOriginal/Role/10010001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10010001/WatchSpine/Watch_3D_front.prefab", interaction = "10010001", coordinate = "10010001", generalattack = "0", midposition = "0.85,3.15", topposition = "1.06,6.71", bottomposition = "0,0", buffplacer = "68235_0", zjeffect = "68236_0", debut = "68234_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.4_14_60_1.2_3_0.5,25_0.2_10_60_2.1_1.2_0.4", delay = "7_0.6,25_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4001000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10010001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10010002] = {id = 10010002, name = "飾演女僕的偶像", story = "實不相瞞，做這件事之前，阿萊塔還顯得有些勉強，她知道自己在侍奉環節無法做到完美，但她不會氣餒，一想到面對的人是領航，就不得不打起勇氣。", attackname = "請注視著我吧！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "ABOriginal/Role/10010002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10010002/WatchSpine/Watch_3D_front.prefab", interaction = "10010002", coordinate = "10010002", generalattack = "0", midposition = "0.85,3.15", topposition = "1.06,6.71", bottomposition = "0,0", buffplacer = "68235_0", zjeffect = "68236_0", debut = "68234_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "7_0.4_14_60_1.2_3_0.5,25_0.2_10_60_2.1_1.2_0.4", delay = "7_0.6,25_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4001000209;switch2,idle,4001000210", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10010002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10011] = {id = 10011, name = "無曉之水", story = "弱水的AVG裝甲。以潛行衣為原型所設計的緊身戰鬥服，擁有令人一眼就能看出是個“忍者”的額外功能。除此之外，這套裝甲各個方面都可以稱得上完美。", attackname = "沉沒吧，在弱水中。", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10011", coordinate = "10011", generalattack = "0", midposition = "0.47,3.69", topposition = "0.74,6.92", bottomposition = "0,0", buffplacer = "68226_0;68227_63", zjeffect = "0", debut = "68225_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "22_0.3_10_60_1_1.5_0.5,41_0.2_8_60_1_1_0.5", delay = "22_0.6,41_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10011001] = {id = 10011001, name = "病棟潛行", story = "哥哥生病了，哥哥住院了，哥哥一個人在病房裏痛苦地呻吟……“我要去保護哥哥！我要在暗中解決想要傷害哥哥的人。”於是弱水潛入醫院，換上護士的服裝，悄悄地守護在領航的身邊。", attackname = "沉沒吧，在弱水中。", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "ABOriginal/Role/10011001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10011001/WatchSpine/Watch_3D_front.prefab", interaction = "10011001", coordinate = "10011001", generalattack = "0", midposition = "0.47,3.69", topposition = "0.74,6.92", bottomposition = "0,0", buffplacer = "68226_0;68227_63", zjeffect = "0", debut = "68225_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "22_0.3_10_60_1_1.5_0.5,41_0.2_8_60_1_1_0.5", delay = "22_0.6,41_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4001100110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10011001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10011002] = {id = 10011002, name = "不寐春夜", story = "輾轉難眠的夜晚，弱水穿著一身新衣尋到了同樣輾轉難眠的你。在臨近春天的夜裏，或許只有像這樣靠近彼此，傾聽著對方的呼吸聲，心跳聲。才能在漫長的春夜中，安然入眠。", attackname = "沉沒吧，在弱水中。", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "ABOriginal/Role/10011002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10011002/WatchSpine/Watch_3D_front.prefab", interaction = "10011002", coordinate = "10011002", generalattack = "0", midposition = "0.47,3.69", topposition = "0.74,6.92", bottomposition = "0,0", buffplacer = "68226_0;68227_63", zjeffect = "0", debut = "68225_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "22_0.3_10_60_1_1.5_0.5,41_0.2_8_60_1_1_0.5", delay = "22_0.6,41_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4001100206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10011002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10012] = {id = 10012, name = "籠中鳥", story = "格洛麗亞的AVG裝甲，由多瑙支部研製。使用多種金屬原料製成。一改第三防衛班偏向防守的風格，這套裝甲更加注重對重型原罪單位的破壞力。", attackname = "擊破準備。", painter = "/", voiceexcellence = "稲垣好", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10012", coordinate = "10012", generalattack = "0", midposition = "-0.3,3.69", topposition = "0,7.09", bottomposition = "0,0", buffplacer = "68265_0;60000_17;60000_33", zjeffect = "68266_0", debut = "68264_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "16_0.3_10_60_1.2_1.8_1.5,16_0.4_12_60_2_2.8_1,27_0.5_16_60_1.2_2.6_2.2", delay = "16_0.3,16_0.3,27_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10012001] = {id = 10012001, name = "不勝杯杓", story = "穿上叛逆的衣裝，飲下苦澀的美酒。格洛麗亞從未感到如此的輕鬆，一切考慮和想法都從大腦中逃跑。而她只需舉杯暢飲，將身體交予乙醇，將靈魂交予眼前之人。", attackname = "擊破準備。", painter = "/", voiceexcellence = "稲垣好", backgroundpic = "ABOriginal/Role/10012001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10012001", coordinate = "10012001", generalattack = "0", midposition = "-0.3,3.69", topposition = "0,7.09", bottomposition = "0,0", buffplacer = "68265_0;60000_17;60000_33", zjeffect = "68266_0", debut = "68264_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "16_0.3_10_60_1.2_1.8_1.5,16_0.4_12_60_2_2.8_1,27_0.5_16_60_1.2_2.6_2.2", delay = "16_0.3,16_0.3,27_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_zz_hsjt", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10013] = {id = 10013, name = "絕對系魔法少女", story = "莉莉絲的專屬AVG裝甲，由一名沉迷魔法少女幻想的科學家研製。羽片狀的部件與紫色帷幔所含之義就連設計者本人也難以言明。", attackname = "你在恐懼什麼……", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10013", coordinate = "10013", generalattack = "0", midposition = "-0.2,3.42", topposition = "0,6.78", bottomposition = "0,0", buffplacer = "68258_0;60000_8;60000_15;60000_31", zjeffect = "0", debut = "68259_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.2_8_60_1_2.2_0.5,8_0.2_8_60_1.8_2.8_1,18_0.4_14_60_1_3.5_0.8", delay = "7_0.2,8_0.3,18_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10013001] = {id = 10013001, name = "罪之聖女", story = "遙遠時空的某個世界中，莉莉絲的另一种可能性。\n作為聖女，她卻能洞見“真實”，目視潛藏於世的詭秘存在。為抵禦罪的侵蝕，她隱去雙眸，身披祭服，在藍燭掩映的滌罪儀式中獻上人性。", attackname = "你在恐懼什麼……", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/10013001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10013001/WatchSpine/Watch_3D_front.prefab", interaction = "10013001", coordinate = "10013001", generalattack = "0", midposition = "-0.2,3.42", topposition = "0,6.78", bottomposition = "0,0", buffplacer = "68258_0;60000_8;60000_15;60000_31", zjeffect = "0", debut = "68259_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.2_8_60_1_2.2_0.5,8_0.2_8_60_1.8_2.8_1,18_0.4_14_60_1_3.5_0.8", delay = "7_0.2,8_0.3,18_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4001300106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10013002] = {id = 10013002, name = "寒梅窗前著", story = "落雪的日子，百花凋零，唯有梅花綻放，成爲無窮的白中的點點粉紅。而此時應做之事，便是點起暖爐，温一壺好酒，坐臥在窗前。與所念之人邊飲酒邊欣賞這銀裝的畫卷，及窗前那兩朵不羈的寒梅。", attackname = "你在恐懼什麼……", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/10013002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10013002", coordinate = "10013002", generalattack = "0", midposition = "-0.2,3.42", topposition = "0,6.78", bottomposition = "0,0", buffplacer = "68258_0;60000_8;60000_15;60000_31", zjeffect = "0", debut = "68259_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.2_8_60_1_2.2_0.5,8_0.2_8_60_1.8_2.8_1,18_0.4_14_60_1_3.5_0.8", delay = "7_0.2,8_0.3,18_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4001300206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10013002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10014] = {id = 10014, name = "遊世千金", story = "科羅溫的專屬AVG裝甲，由塞倫公司負責設計和生產。得益於家族對塞倫的資金支持，塞倫設計師在這件裝甲的用料上也是不留餘力，使用了當時最先進的材料。略顯樸素的外觀是有意為之，為了讓科羅溫在戰場上不會那麼顯眼。", attackname = "敵人...原來在對面啊。", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10014", coordinate = "10014", generalattack = "0", midposition = "0.15,3.9", topposition = "0.58,7.46", bottomposition = "0,0", buffplacer = "68285_0;60000_17;68286_30", zjeffect = "68283_0", debut = "68282_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "16_0.4_16_60_2.1_3.2_0.7,30_0.6_32_60_2.2_1.4_0.3", delay = "16_0.4,30_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10014001] = {id = 10014001, name = "孤独圣诞夜", story = "月亮倚靠着云的肩膀，风和雪在窗外嬉戏打闹，壁炉中的劈啪作响是木柴唱给火苗的安眠歌谣。如此喧闹的夜晚，如此孤独的夜晚。孤独一人的少女，孤独地蜷缩在闺房内，孤独地等待着领航推开那扇，闭合的沉重的孤独的门扉。", attackname = "敵人...原來在對面啊。", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10014001", coordinate = "10014001", generalattack = "0", midposition = "0.15,3.9", topposition = "0.58,7.46", bottomposition = "0,0", buffplacer = "68285_0;60000_17;68286_30", zjeffect = "68283_0", debut = "68282_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "16_0.4_16_60_2.1_3.2_0.7,30_0.6_32_60_2.2_1.4_0.3", delay = "16_0.4,30_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4001400106", dragrange = "1920,1080;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10015] = {id = 10015, name = "破壞狂", story = "漢克", attackname = "我要捏碎它們的外殼。", painter = "/", voiceexcellence = "邑上鈴歌", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10015", coordinate = "10015", generalattack = "0", midposition = "0.25,5.4", topposition = "0.25,8.97", bottomposition = "0,0", buffplacer = "68293_0", zjeffect = "68294_0", debut = "68292_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 23, bulletvelocity = "0", strike = "30_0.35_22_60_1.9_2.8_0.5", delay = "30_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10016] = {id = 10016, name = "曆難之鷹", story = "安安的AVG裝甲。由撒哈拉學院制式的裝備改造而來。為了彌補安安自身體能不足的缺陷而使用雙足代步機關來增加其機動力。", attackname = "我不會後退半步！", painter = "/", voiceexcellence = "上原あかり", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10016", coordinate = "10016", generalattack = "0", midposition = "1.01,4.39", topposition = "0.74,8.2", bottomposition = "0,0", buffplacer = "68297_0", zjeffect = "68295_0", debut = "68296_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "18_0.6_24_60_1.8_2.8_0.2,40_0.4_14_60_2.8_1.4_1,30_0.4_14_60_2.8_1.4_1", delay = "18_0.4,40_0.3,30_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10016001] = {id = 10016001, name = "鬱香雨跡", story = "淅淅瀝瀝，細雨漸息。驾驶员學院內的清吧營業已經結束，安安卻穿著彆扭的“工作服”還在努力地擦淨杯子。就在此時，清吧外出現了一名學生之外的新客，這位客人正是恰巧路過此地的領航老師。", attackname = "我不會後退半步！", painter = "/", voiceexcellence = "上原あかり", backgroundpic = "ABOriginal/Role/10016001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10016001/WatchSpine/Watch_3D_front.prefab", interaction = "10016001", coordinate = "10016001", generalattack = "0", midposition = "1.01,4.39", topposition = "0.74,8.2", bottomposition = "0,0", buffplacer = "68297_0", zjeffect = "68295_0", debut = "68296_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "18_0.6_24_60_1.8_2.8_0.2,40_0.4_14_60_2.8_1.4_1,30_0.4_14_60_2.8_1.4_1", delay = "18_0.4,40_0.3,30_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4001600110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10016001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10017] = {id = 10017, name = "自稱的貴族小姐", story = "羅莎琳德的AVG裝甲。與輕便、簡約的隊友不同，羅莎琳德將自己的幻化核心物盡其用，盡可能地武裝自己幻化後的身軀——可謂是全副武裝的裝甲。", attackname = "退後，我要使用絕招了！", painter = "/", voiceexcellence = "邑上鈴歌", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10017", coordinate = "10017", generalattack = "18,25", midposition = "0.23,4.29", topposition = "0.23,8.33", bottomposition = "0,0", buffplacer = "68312_0;60000_11;60000_36", zjeffect = "68313_0;60000_47", debut = "68311_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "5_0.2_7_60_0.7_1.2_0.2,26_0.35_28_60_1.6_1.4_1", delay = "5_0.6,26_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10017001] = {id = 10017001, name = "逆轉兔女郎", story = "這是一場豪賭，亦是一場戰爭。在這只有你們兩人的密室中，你們各自為了自己的目標壓上所有的籌碼。羅莎琳德為了爭取一日約會的時間而來，面對敢於向你發出挑戰並意圖奪走你休息日的羅莎琳德，你決定對她降下懲罰。", attackname = "退後，我要使用絕招了！", painter = "/", voiceexcellence = "邑上鈴歌", backgroundpic = "ABOriginal/Role/10017001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10017001", coordinate = "10017001", generalattack = "18,25", midposition = "0.23,4.29", topposition = "0.23,8.33", bottomposition = "0,0", buffplacer = "68312_0;60000_11;60000_36", zjeffect = "68313_0;60000_47", debut = "68311_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "5_0.2_7_60_0.7_1.2_0.2,26_0.35_28_60_1.6_1.4_1", delay = "5_0.6,26_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4001700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10017001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10018] = {id = 10018, name = "女僕愛好者", story = "莉法的AVG裝甲，由卡佳的第一研究室所研發製作。在裝甲設計上最突出的特點是融合了女僕裝的元素。還有種說法是這是瓦爾基裏隊長直接從多瑙支部手中購買的設計圖。", attackname = "不會再让你前进半步！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10018", coordinate = "10018", generalattack = "0", midposition = "0.14,4.21", topposition = "0.14,7.98", bottomposition = "0,0", buffplacer = "68315_0", zjeffect = "68316_0", debut = "68314_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 27, bulletvelocity = "0", strike = "15_0.25_16_60_1.8_2.4_1,43_0.6_32_60_2.1_3.2_1.7", delay = "15_0.3,43_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10018001] = {id = 10018001, name = "薄冰上的舞者", story = "夜空滑過銀河，留下光的痕跡。莉法在冰面上跳躍如在河面上彈起的白色卵石。巨大的虛影在這自然堆砌的滑冰場上穿梭來回。這便是莉法的女僕修行。", attackname = "不會再让你前进半步！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/10018001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10018001/WatchSpine/Watch_3D_front.prefab", interaction = "10018001", coordinate = "10018001", generalattack = "0", midposition = "0.14,4.21", topposition = "0.14,7.98", bottomposition = "0,0", buffplacer = "68315_0", zjeffect = "68316_0", debut = "68314_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 27, bulletvelocity = "0", strike = "15_0.25_16_60_1.8_2.4_1,43_0.6_32_60_2.1_3.2_1.7", delay = "15_0.3,43_0.7", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4001800106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10019] = {id = 10019, name = "希望共鳴體", story = "結束小姐的夏裝。\n嗯嗯，這就是自由哦！聽到那展翅高飛翱翔的旋律了嗎？我已經迫不及待地等待著明天了！我要被海島的氣息俘獲了！", attackname = "奏響希望！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/10019/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10019", coordinate = "10019", generalattack = "0", midposition = "0,4.52", topposition = "0,7.99", bottomposition = "0,0", buffplacer = "68186_0", zjeffect = "68187_0", debut = "68185_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "76_0.55_34_60_2.3_2.7_1.6", delay = "76_1", admission = "0", scale = "0.5,1.5", bgm = "34-Open_Summer_violin_loop", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10019001] = {id = 10019001, name = "希望協奏曲", story = "結束小姐的泳裝。\n我決定明天就向改變的嶄新命運邁步，但是今天就饒了我吧，讓我好好享受這勝利的餘韻。領航，你可不許偷跑哦？答應好了今天要陪我的吧？", attackname = "奏響希望！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/10019001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10019001/WatchSpine/Watch_3D_front.prefab", interaction = "10019001", coordinate = "10019001", generalattack = "0", midposition = "0,4.52", topposition = "0,7.99", bottomposition = "0,0", buffplacer = "68186_0", zjeffect = "68187_0", debut = "68185_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "76_0.55_34_60_2.3_2.7_1.6", delay = "76_1", admission = "0", scale = "1,2", bgm = "34-Open_Summer_violin_loop", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10019001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10020] = {id = 10020, name = "未確認未來時", story = "未來專屬的AVG裝甲，裝甲的形象是泳衣。因為這既是自己與領航邂逅時穿的衣服，也是自己第一次決定對某件事堅持下去，所以對她而言具有極大的紀念意義。", attackname = "已經膩了……", painter = "/", voiceexcellence = "本田乃愛", backgroundpic = "ABOriginal/Role/10020/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10020", coordinate = "10020", generalattack = "0", midposition = "0,4.61", topposition = "0,8.56", bottomposition = "0,0", buffplacer = "68525_0", zjeffect = "68526_0", debut = "68524_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "6_0.15_7_60_1.6_2.2_0.9,8_0.25_11_60_2_2.8_1.4,23_0.35_21_60_2.6_3.5_1.4", delay = "6_0.2,8_0.3,23_0.5", admission = "0", scale = "0.5,1.5", bgm = "73-Mirai", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10020001] = {id = 10020001, name = "迷糊糊夏眠時", story = "在平時的時候就是一個任性的小鬼，只有在睡著的時候，才深切地感受到“原來未來安靜下來還挺可愛的”，甚至會因為做了噩夢而緊緊握住你的手，等她醒了必須用這件事嘲笑她。", attackname = "當駕駛員一點都不有趣……", painter = "/", voiceexcellence = "本田乃愛", backgroundpic = "ABOriginal/Role/10020001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10020001", coordinate = "10020001", generalattack = "0", midposition = "0,4.61", topposition = "0,8.56", bottomposition = "0,0", buffplacer = "68525_0", zjeffect = "68526_0", debut = "68524_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "6_0.15_7_60_1.6_2.2_0.9,8_0.25_11_60_2_2.8_1.4,23_0.35_21_60_2.6_3.5_1.4", delay = "6_0.2,8_0.3,23_0.5", admission = "0", scale = "1,2", bgm = "73-Mirai", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10020001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10021] = {id = 10021, name = "影隙微光", story = "辛西婭和辛米亞專屬的AVG裝甲。你在了解了辛西婭的特殊之處後，為其定制了兩套戰鬥服。唯一遺憾的是辛米亞只有在巨大化的時候才會出現，也許想要見到常態的辛米亞需要一個契機——", attackname = "真煩人。", painter = "/", voiceexcellence = "古賀葵", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10021", coordinate = "10021", generalattack = "0", midposition = "0,4.58", topposition = "0,7.62", bottomposition = "0,0", buffplacer = "68190_0", zjeffect = "68191_0", debut = "68189_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "6_0.25_12_60_1.4_2.2_0.9,28_0.4_32_60_2.2_3.4_1.4,22_0.4_32_60_2.4_3_2.2", delay = "6_0.2,28_0.4,22_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10021001] = {id = 10021001, name = "海灘雙層漢堡", story = "如果您不想被海灘上奪人眼眶的兩位巨大美少女波及的話，那麼就請快點逃離吧——抑或者，等她們發現你之後，你將會被迫加入這場因你而起的戰爭，成為她們（雙層漢堡）的玩物（佐料）。", attackname = "真煩人。", painter = "/", voiceexcellence = "古賀葵", backgroundpic = "ABOriginal/Role/10021001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10021001", coordinate = "10021001", generalattack = "0", midposition = "0,4.58", topposition = "0,7.62", bottomposition = "0,0", buffplacer = "68190_0", zjeffect = "68191_0", debut = "68189_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "6_0.25_12_60_1.4_2.2_0.9,28_0.4_32_60_2.2_3.4_1.4,22_0.4_32_60_2.4_3_2.2", delay = "6_0.2,28_0.4,22_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4002100110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10021001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
