[10023] = {id = 10023, name = "臨世牧歌", story = "暫無", attackname = "睡吧，睡吧……", painter = "/", voiceexcellence = "中山 まなか", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10023", coordinate = "10023", generalattack = "0", midposition = "0,4.65", topposition = "0,8.2", bottomposition = "0,0", buffplacer = "68550_0;68551_50", zjeffect = "68552_0;68553_40", debut = "68549_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "55_0.5_46_60_2.3_3_1.5", delay = "55_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10025] = {id = 10025, name = "奔流騎士", story = "梅爾專屬的avg裝甲，藍白色的金屬裝甲，如海浪一般自由。經過多瑙支部專門研究的力學結構，足以支撐起梅爾誇張的武器重量，讓她可以毫無顧忌地在戰場上廝殺。", attackname = "為了自由！", painter = "/", voiceexcellence = "邑上鈴歌", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10025", coordinate = "10025", generalattack = "0", midposition = "0,4.73", topposition = "0,9.34", bottomposition = "0,0", buffplacer = "68499_0", zjeffect = "68500_0", debut = "68498_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 25, bulletvelocity = "0", strike = "28_0.4_32_60_2.5_3.1_1.7", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10025001] = {id = 10025001, name = "靜水之上的龍姬", story = "靜水之上，寒風陣陣，鎖鏈的碰撞在空中回蕩。被囚禁千年的“魔龍”，不再試圖掙扎，對自由的渴望被她藏在心裏，小心翼翼。她在等待，那位約定中的“勇者”，斬斷鎖鏈，簽下契約。再一同飛上天空，向世界宣洩，這持續了千年的冤屈和憤怒。", attackname = "為了自由！", painter = "/", voiceexcellence = "邑上鈴歌", backgroundpic = "ABOriginal/Role/10025001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10025001/WatchSpine/Watch_3D_front.prefab", interaction = "10025001", coordinate = "10025001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.34", bottomposition = "0,0", buffplacer = "68499_0", zjeffect = "68500_0", debut = "68498_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 25, bulletvelocity = "0", strike = "28_0.4_32_60_2.5_3.1_1.7", delay = "33_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4002500106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10025001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10026] = {id = 10026, name = "惡戲的女王", story = "娜斯佳專屬的AVG裝甲，經過無數次修改後才由娜斯佳本人親自敲定的設計，據說成品和最初的設計非常相似。另外塞倫公司聲明，並沒有任何一名設計師受到迫害。", attackname = "雜魚~真是没用呢~", painter = "/", voiceexcellence = "梨本ひおり", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10026", coordinate = "10026", generalattack = "0", midposition = "0,4.67", topposition = "0,8.12", bottomposition = "0,0", buffplacer = "68355_0", zjeffect = "68356_0", debut = "68354_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "16_0.4_29_60_1.7_2.4_1,31_0.5_32_60_2.7_3.1_1.9", delay = "16_0.4,31_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10026001] = {id = 10026001, name = "非禁止踩踏區域", story = "身體被黑暗包裹，柔軟的重物緊貼著皮膚，空氣……逐漸被另一種氣味代替。身後是冰冷的地面，身前是溫暖的腳底……意識非常清醒地感受著這種感覺，被巨大的少女踩在腳下的感覺……非常的……異常的……平靜。", attackname = "雜魚~真是没用呢~", painter = "/", voiceexcellence = "梨本ひおり", backgroundpic = "ABOriginal/Role/10026001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10026001", coordinate = "10026001", generalattack = "0", midposition = "0,4.67", topposition = "0,8.12", bottomposition = "0,0", buffplacer = "68355_0", zjeffect = "68356_0", debut = "68354_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "16_0.4_29_60_1.7_2.4_1,31_0.5_32_60_2.7_3.1_1.9", delay = "16_0.4,31_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4002600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10026001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10027] = {id = 10027, name = "先行者", story = "亞爾薇特的AVG裝甲，你很難看見亞爾薇特博士以其它樣子出現——她的工作服幾乎和幻化裝甲一模一樣，在危险性上也同樣如此。", attackname = "無趣。", painter = "/", voiceexcellence = "下地紫野", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10027", coordinate = "10027", generalattack = "0", midposition = "0,4.71", topposition = "0,8.64", bottomposition = "0,0", buffplacer = "68413_0", zjeffect = "68414_0", debut = "68412_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 31, bulletvelocity = "0", strike = "9_0.35_19_60_1.9_2.9_1,17_0.7_46_60_2.4_3.4_1.7,54_0.4_28_60_2.6_3.4_2.2", delay = "9_0.3,17_0.3,54_0.4", admission = "0", scale = "0.5,1.5", bgm = "51-underthesnow", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10027001] = {id = 10027001, name = "寂滅的雪", story = "亞爾薇特博士討厭被打擾——就比如在她實驗的過程中有原罪入侵，作為被打擾的代價，原罪們充當了她解悶的對象。亞爾薇特博士有時不討厭被打擾——就比如在她解悶的時候有你同行。", attackname = "無趣。", painter = "/", voiceexcellence = "下地紫野", backgroundpic = "ABOriginal/Role/10027001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10027001", coordinate = "10027001", generalattack = "0", midposition = "0,4.71", topposition = "0,8.64", bottomposition = "0,0", buffplacer = "68413_0", zjeffect = "68414_0", debut = "68412_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 31, bulletvelocity = "0", strike = "9_0.35_19_60_1.9_2.9_1,17_0.7_46_60_2.4_3.4_1.7,54_0.4_28_60_2.6_3.4_2.2", delay = "9_0.3,17_0.3,54_0.4", admission = "0", scale = "1,2", bgm = "51-underthesnow", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10027001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10028] = {id = 10028, name = "神機非攻", story = "漢克", attackname = "攻守易形。", painter = "/", voiceexcellence = "鳴瀬麻美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10028", coordinate = "10028", generalattack = "0", midposition = "0,4.72", topposition = "0,8.54", bottomposition = "0,0", buffplacer = "68217_0;60000_45", zjeffect = "68218_0", debut = "68216_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "19_0.35_17_60_2.6_1.8_1,23_0.4_26_60_2.7_3.5_2", delay = "19_0.4,23_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10029] = {id = 10029, name = "異誕喵", story = "黎貝卡的原罪化身軀，那顆巨蛋是她的能量來源，同時也能孵化出分身。這些分身理論上也是黎貝卡人格的一部分，但是她們行為卻與黎貝卡大相徑庭。", attackname = "喵！", painter = "/", voiceexcellence = "上永紗也華", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10029", coordinate = "10029", generalattack = "0", midposition = "0,4.26", topposition = "0,8.41", bottomposition = "0,0", buffplacer = "68375_0", zjeffect = "68376_0", debut = "68374_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 20, bulletvelocity = "0", strike = "39_0.45_24_60_2.4_3_1.7", delay = "39_1", admission = "0", scale = "0.5,1.5", bgm = "33-Empty_but_not_real", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10029001] = {id = 10029001, name = "亂喵一團", story = "莉莉很不喜歡訓練之後的例行檢查，但是“黎貝卡”們不這麼想。她們上下騰飛，東躲西藏，趁著莉莉不能動彈的時機，肆意地觸摸周圍的新鮮事物，以滿足她們旺盛的好奇心。", attackname = "喵！", painter = "/", voiceexcellence = "上永紗也華", backgroundpic = "ABOriginal/Role/10029001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10029001/WatchSpine/Watch_3D_front.prefab", interaction = "10029001", coordinate = "10029001", generalattack = "0", midposition = "0,4.26", topposition = "0,8.41", bottomposition = "0,0", buffplacer = "68375_0", zjeffect = "68376_0", debut = "68374_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 20, bulletvelocity = "0", strike = "39_0.45_24_60_2.4_3_1.7", delay = "39_1", admission = "0", scale = "1,2", bgm = "33-Empty_but_not_real", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10029001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10030] = {id = 10030, name = "致命芳調", story = "法爾奈斯·蘭特的AVG裝甲，由於作為家族千金的她早已習慣了時刻做好應戰準備，這身日常所穿的衣物最能讓她行動起來得心應手。", attackname = "種下一粒子彈。", painter = "/", voiceexcellence = "盛恵里花/長月あおい", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10030", coordinate = "10030", generalattack = "0", midposition = "0,4.32", topposition = "0,8.6", bottomposition = "0,0", buffplacer = "68403_0", zjeffect = "68404_0;68405_60", debut = "68402_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "10_0.15_7_60_1.7_2_0.7,16_0.3_16_60_1.4_2.7_0.9,52_1.7_62_60_1.5_2.3_0.8,68_0.35_19_60_2.4_3.1_1.5", delay = "10_0.1,16_0.2,52_0.4,68_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10030001] = {id = 10030001, name = "危險遊戲", story = "在法爾奈斯的宅邸，你與她開始了一場私人賭局，雙方複雜的命運軌跡，將僅由Blackjack的簡單規則決定。今天該輪到誰當家做主？瀰漫牌桌的芬芳與法爾奈斯的笑容使你愈發心緒不定。", attackname = "來玩露西亞輪盤吧。", painter = "/", voiceexcellence = "盛恵里花/長月あおい", backgroundpic = "ABOriginal/Role/10030001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10030001/WatchSpine/Watch_3D_front.prefab", interaction = "10030001", coordinate = "10030001", generalattack = "0", midposition = "0,4.32", topposition = "0,8.6", bottomposition = "0,0", buffplacer = "68403_0", zjeffect = "68404_0;68405_60", debut = "68402_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "10_0.15_7_60_1.7_2_0.7,16_0.3_16_60_1.4_2.7_0.9,52_1.7_62_60_1.5_2.3_0.8,68_0.35_19_60_2.4_3.1_1.5", delay = "10_0.1,16_0.2,52_0.4,68_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch4,idle,4003000110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10030001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10031] = {id = 10031, name = "水車村的希望", story = "暫無", attackname = "看、看招！", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10031", coordinate = "10031", generalattack = "0", midposition = "0,4.43", topposition = "0,8.67", bottomposition = "0,0", buffplacer = "68458_0", zjeffect = "68459_0", debut = "68457_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "11_0.25_13_60_1.6_2.4_1.1,15_0.3_17_60_2_2.9_1.7,41_0.5_29_60_2.4_3.7_1.8", delay = "65_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10032] = {id = 10032, name = "和平得奖者", story = "漢克", attackname = "別浪費我的時間。", painter = "/", voiceexcellence = "倉持愛衣子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10032", coordinate = "10032", generalattack = "0", midposition = "0,4.41", topposition = "0,8.37", bottomposition = "0,0", buffplacer = "68416_0", zjeffect = "68417_0", debut = "68415_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "35_0.6_37_60_2.2_3.2_1.4", delay = "36_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10033] = {id = 10033, name = "“小丑”", story = "柯朗專屬的AVG裝甲。柯朗的裝備除了提供應有的作戰性能外，還起到了對她的精神狀態及其行蹤的監視作用。煽動人心的小丑始終被監視。", attackname = "当心你的身后。", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10033", coordinate = "10033", generalattack = "0", midposition = "0,4.56", topposition = "0,8.93", bottomposition = "0,0", buffplacer = "68422_0", zjeffect = "68423_0;68424_15", debut = "68421_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.39", attackdistance = 15, bulletvelocity = "0", strike = "17_0.15_7_60_1.4_2.1_0.5,7_0.2_11_60_1.9_2.8_1,23_0.35_19_60_2_3.1_1.4", delay = "17_0.2,7_0.3,23_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10033001] = {id = 10033001, name = "荒宅驚魂", story = "這是一個陷阱，是一個陽謀，她為了甄別人心而設下陷阱，邀你而來。你不得不去，因為你知道她不會善罷甘休。偽善與希望，她想從你的內心中找到真正的答案。", attackname = "当心你的身后。", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "ABOriginal/Role/10033001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10033001/WatchSpine/Watch_3D_front.prefab", interaction = "10033001", coordinate = "10033001", generalattack = "0", midposition = "0,4.56", topposition = "0,8.93", bottomposition = "0,0", buffplacer = "68422_0", zjeffect = "68423_0;68424_15", debut = "68421_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.39", attackdistance = 15, bulletvelocity = "0", strike = "17_0.15_7_60_1.4_2.1_0.5,7_0.2_11_60_1.9_2.8_1,23_0.35_19_60_2_3.1_1.4", delay = "17_0.2,7_0.3,23_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch12,idle,4003300108;touch11,idle,4003300107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10033001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10033002] = {id = 10033002, name = "拾級而上的禮讚歌", story = "縈繞愛慾氣息的花束，被柯朗小心翼翼地捧在懷中。她每邁出一步，都會在心中默唸着一段誓言。臺階很長，走完臺階也意味着她終於與抵達了夢中的禮堂——那座真正屬於柯朗的安心之所——領航的懷抱。", attackname = "当心你的身后。", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "ABOriginal/Role/10033002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10033002/WatchSpine/Watch_3D_front.prefab", interaction = "10033002", coordinate = "10033002", generalattack = "0", midposition = "0,4.56", topposition = "0,8.93", bottomposition = "0,0", buffplacer = "68422_0", zjeffect = "68423_0;68424_15", debut = "68421_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.39", attackdistance = 15, bulletvelocity = "0", strike = "17_0.15_7_60_1.4_2.1_0.5,7_0.2_11_60_1.9_2.8_1,23_0.35_19_60_2_3.1_1.4", delay = "17_0.2,7_0.3,23_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4003300210;switch2,idle3,4003300211;switch3,idle,4003300212", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10033002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10034] = {id = 10034, name = "無趣之夢", story = "洛基的AVG裝甲，是非常極端的獨立行動特化型裝甲，沒有朋友，甚至連隊友都沒有，心底認為自己並不是交不到朋友，只是不需要朋友。幾乎不與人合作完成任務。", attackname = "真煩。", painter = "/", voiceexcellence = "鈴木みのり", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10034", coordinate = "10034", generalattack = "0", midposition = "0,4.61", topposition = "0,9.32", bottomposition = "0,0", buffplacer = "68441_0", zjeffect = "68442_0", debut = "68440_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 23, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "0.5,1.5", bgm = "63-suffocate", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10034001] = {id = 10034001, name = "私人保鏢", story = "在深夜中尋訪。將感覺淪落為信任，對朋友的信任淪落為擊碎冷酷臉龐的互相傾訴。她對你傾訴的憤怒，懊惱，不甘心令人著迷，最終沉溺為歎息。", attackname = "死去吧。", painter = "/", voiceexcellence = "鈴木みのり", backgroundpic = "ABOriginal/Role/10034001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10034001/WatchSpine/Watch_3D_front.prefab", interaction = "10034001", coordinate = "10034001", generalattack = "0", midposition = "0,4.61", topposition = "0,9.32", bottomposition = "0,0", buffplacer = "68441_0", zjeffect = "68442_0", debut = "68440_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 23, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "1,1", bgm = "63-suffocate", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4003400107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10034001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10035] = {id = 10035, name = "不傳統負債者", story = "赫莉的AVG裝甲。雖然名義上是赫莉的專屬AVG裝甲，但實際上和駕駛員學員時期的基礎裝備只有配色上的區別。\n想成為一名強大的駕駛員，任重而道遠。", attackname = "能快點結束嗎？", painter = "/", voiceexcellence = "黒沢ともよ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10035", coordinate = "10035", generalattack = "0", midposition = "0,4.81", topposition = "0,9.73", bottomposition = "0,0", buffplacer = "68438_0", zjeffect = "68439_0", debut = "68437_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "15_0.4_21_60_1.7_2.9_1,55_0.55_39_60_2.6_3.4_1.9", delay = "15_0.4,55_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10035001] = {id = 10035001, name = "巧克力宅急送", story = "“飛速食品”為了盛大的情人節活動特別準備的節日制服，從設計到制作都由老闆耶德娜本人負責。\n順帶一提，赫莉本人覺得快餐店辦什麽情人節特別活動簡直不可理喩。", attackname = "能快點結束嗎？", painter = "/", voiceexcellence = "黒沢ともよ", backgroundpic = "ABOriginal/Role/10035001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10035001/WatchSpine/Watch_3D_front.prefab", interaction = "10035001", coordinate = "10035001", generalattack = "0", midposition = "0,4.81", topposition = "0,9.73", bottomposition = "0,0", buffplacer = "68438_0", zjeffect = "68439_0", debut = "68437_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "15_0.4_21_60_1.7_2.9_1,55_0.55_39_60_2.6_3.4_1.9", delay = "15_0.4,55_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4003500106", dragrange = "1920,1080;1920,1080", isdrag = 0, jumpto = "5,10035001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10036] = {id = 10036, name = "不可思議的決心", story = "查麗莎與你一同購買的情趣內衣。優柔寡斷可不是查麗莎的風格——她早已決定把自己交給你，只是這件事情太難以啟齒。而你只需要靜靜等待時機的來臨。", attackname = "本小姐和領航兩個人就夠了！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10036", coordinate = "10036", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68455_0", zjeffect = "68456_0", debut = "68454_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "20_1_56_60_1.9_2.7_1.1", delay = "30_1", admission = "0", scale = "0.5,1.5", bgm = "65-V_for_Valentine", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10036001] = {id = 10036001, name = "不許拉那條緞帶！", story = "查麗莎與你一同購買的情趣內衣。她在決定穿上這件衣服以前做了大概三天的白日夢，包括但不限於——暢想了你被她誘惑以後會發生的各種各樣的事情，第十一個女兒的名字……等等。", attackname = "本小姐和領航兩個人就夠了！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/10036001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10036001", coordinate = "10036001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68455_0", zjeffect = "68456_0", debut = "68454_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "20_1_56_60_1.9_2.7_1.1", delay = "30_1", admission = "0", scale = "1,2", bgm = "65-V_for_Valentine", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10036001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10037] = {id = 10037, name = "偽裝者", story = "軫宿四的專屬AVG裝甲。軫宿四為自己挑選的裝備嚴格來說並不適合正面作戰，只有那面盾牌能勉強為她提供一定的防禦能力。用她的話來說，駕駛員只是一份通往美好生活的工作，她並不打算為此付出多少心血。", attackname = "都說了不要打我！", painter = "/", voiceexcellence = "西薗雪乃", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10037", coordinate = "10037", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68555_0,68557_20", zjeffect = "68556_0", debut = "68554_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "28_0.65_38_60_1.7_2.8_0.9", delay = "30_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10037001] = {id = 10037001, name = "完美的告白作戰", story = "軫宿四的復仇計劃正在執行中，她要讓這個炙手可熱的領航成為自己的愛情俘虜……而情人節就是她執行復仇作戰的最好時機，那麼第一步，就是將自己燒死了無數腦細胞寫下的情書以完美的形式遞給他……", attackname = "都說了不要打我！", painter = "/", voiceexcellence = "西薗雪乃", backgroundpic = "ABOriginal/Role/10037001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10037001/WatchSpine/Watch_3D_front.prefab", interaction = "10037001", coordinate = "10037001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68555_0,68557_20", zjeffect = "68556_0", debut = "68554_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "28_0.65_38_60_1.7_2.8_0.9", delay = "30_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "sw12,idle2,4003700106,100;sw23,idle3,4003700112,100;sw31,idle,4003700118,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10037001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10038] = {id = 10038, name = "悠然釣手", story = "赫洛卡專屬的AVG裝甲，由赫洛卡親自設計製造。很明顯赫洛卡在這套裝甲中傾注了太多“個人愛好”。雖然駕駛員的武器千奇百怪，但是大多還是保留著“武器”的外形。而赫洛卡的這根魚竿……不知道能否釣到她想要的“大魚”。", attackname = "上鉤了——", painter = "/", voiceexcellence = "宮内萌李", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10038", coordinate = "10038", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68569_0", zjeffect = "68570_0", debut = "68568_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "20_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "82-Fishing", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10038001] = {id = 10038001, name = "無處可逃的暖意", story = "風來得突然，雪也落得著急。被風雪驅趕至帳篷中，汽燈照亮了臉頰的紅潤，不到5平米的空氣中回蕩著的實急促而拘謹的呼吸。任憑外邊風雪交匯，任憑地面雪深沒膝，二人身邊始終包裹著一股無處可逃，浹淪肌髓的暖意。", attackname = "上鉤了——", painter = "/", voiceexcellence = "宮内萌李", backgroundpic = "ABOriginal/Role/10038001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10038001", coordinate = "10038001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68569_0", zjeffect = "68570_0", debut = "68568_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "20_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "82-Fishing", shoptag = "0", ismorestate = 1, shopanim = "swtich1,idle1,4003800103,100;swtich2,idle,4003800109,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10038001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10038002] = {id = 10038002, name = "翦切遊戲", story = "只要達成某个條件，衣服就會憑空消失一部分。這是近期網絡上的流行趨勢，像是都市怪談一樣的翦切遊戲。當赫洛卡衣服的一部分開始消失的時候，我已經忍耐不住好奇，迫不及待地尋找起下一个關鍵道具。", attackname = "上鉤了——", painter = "/", voiceexcellence = "宮内萌李", backgroundpic = "ABOriginal/Role/10038002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10038002/WatchSpine/Watch_3D_front.prefab", interaction = "10038002", coordinate = "10038002", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68569_0", zjeffect = "68570_0", debut = "68568_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "20_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "82-Fishing", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4003800206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10038002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10039] = {id = 10039, name = "暗戰之拳", story = "哈莉特專屬的AVG裝甲。由奧德賽重工研發製作而成。這套裝甲的作用更多是避免哈莉特豪放的戰鬥風格對自己的身體造成傷害。沉迷戰鬥中的她常常會無視肉體的痛楚。", attackname = "呵——", painter = "/", voiceexcellence = "鵜殿麻由", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10039", coordinate = "10039", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68580_0", zjeffect = "68581_0", debut = "68579_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10039001] = {id = 10039001, name = "烈日耀斑", story = "海灘上，太陽平等地炙烤著每一個人，但並不是所有人都在躲避似火的陽光。哈莉特將皮膚裸露在陽光下，吸收著太陽光的能量，於肉體上凝聚出健康的暗色。只是略微靠近就能感覺到那如同耀斑般融化一切的熱情。", attackname = "呵——", painter = "/", voiceexcellence = "鵜殿麻由", backgroundpic = "ABOriginal/Role/10039001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10039001/WatchSpine/Watch_3D_front.prefab", interaction = "10039001", coordinate = "10039001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68580_0", zjeffect = "68581_0", debut = "68579_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4003900103", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10039001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10040] = {id = 10040, name = "人造之“罪”", story = "暫無", attackname = "任務——執行——", painter = "/", voiceexcellence = "邑上鈴歌/青戸浩香", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10040", coordinate = "10040", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68597_0", zjeffect = "68598_0", debut = "68599_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "19_0.6_16_60_3_1_4", delay = "19_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10041] = {id = 10041, name = "浴血之妖", story = "阿萊塔專屬的AVG裝甲。裝甲本身無法為阿萊塔提供多少幫助，僅依靠兼具斬擊與防禦性能的武器就能讓她在戰場上所向披靡。\n浴血二十年，其作戰經驗無人能比。", attackname = "最後一曲了！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10041", coordinate = "10041", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68617_0", zjeffect = "68618_0", debut = "68616_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10041001] = {id = 10041001, name = "半日閒暇", story = "來不及解開纏身的衣物，來不及平息內心的躁動。在狹窄的浴缸中打開冰冷的雨。將身體和心一同藏進這兩平方的空間，享受難得的半日空閒。\n這不是休息，這只是在輕撫生活的累累傷痕。", attackname = "稍微休息一會吧。", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "ABOriginal/Role/10041001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10041001/WatchSpine/Watch_3D_front.prefab", interaction = "10041001", coordinate = "10041001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68617_0", zjeffect = "68618_0", debut = "68616_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "17_0.2_6_60_1.3_2.2_0.7,13_0.35_11_60_1.8_2.9_1.3,21_0.55_42_60_1.7_2.4_1.5", delay = "17_0.3,13_0.5,21_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch12,idle2,4004100106,100;switch21,idle,4004100108,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,10041001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10042] = {id = 10042, name = "玉體革命", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "壓扁你！", painter = "/", voiceexcellence = "日野まり", backgroundpic = "ABOriginal/Role/10042/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "10042", coordinate = "10042", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68638_0", zjeffect = "68639_0", debut = "68637_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10042001] = {id = 10042001, name = "異世界探險！", story = "“來都來了，順其自然吧。異世界，可不要讓我失望啊！”抱著這樣的想法，朱朱向著未知的領域進發。", attackname = "我是不會放棄的！", painter = "/", voiceexcellence = "日野まり", backgroundpic = "ABOriginal/Role/10042001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10042001/WatchSpine/Watch_3D_front.prefab", interaction = "10042001", coordinate = "10042001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68638_0", zjeffect = "68639_0", debut = "68637_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4004200103,100;switch2,idle,4004200109,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10042001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10043] = {id = 10043, name = "黑暗御座", story = "【宇宙大災-黑暗御座】的人類形態，作為曾經全宇宙的皇帝（二十分鐘），以親民的姿態出現在了宇宙。實際上對整個宇宙造成了很多的麻煩，她本人被教育過之後，可能認識到了自己的錯誤（存疑）。", attackname = "爸爸！我來幫忙了！", painter = "/", voiceexcellence = "逢来りん", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10043", coordinate = "10043", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68660_0,68661_0", zjeffect = "68662_0", debut = "68659_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10043001] = {id = 10043001, name = "魔王大人不會游泳！", story = "一但接觸海水就會沉到水裡的魔王……但是沒有關係，只要爸爸在身邊牽住我的手就好了嘛！而且還有游泳圈，我是不會放棄和爸爸留下這段回憶的機會的——為此正在努力學習的光正陷入苦戰。", attackname = "為了回去練習游泳——", painter = "/", voiceexcellence = "逢来りん", backgroundpic = "ABOriginal/Role/10043001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10043001/WatchSpine/Watch_3D_front.prefab", interaction = "10043001", coordinate = "10043001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68660_0,68661_0", zjeffect = "68662_0", debut = "68659_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "8_0.5_16_60_2.2_2.8_0.6", delay = "8_1", admission = "0", scale = "1,2", bgm = "57-jaw", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4004300109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10043001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10044] = {id = 10044, name = "多臂的幽靈", story = "D型b2的新型機體。是紅博士的機器人技術結合幻化技術而製造的新機體，需要依靠D型b2本體進行控制。經過改良後D型b2-H機體也獲得了巨大化的功能，可以更靈活地應對可能發生的情況。", attackname = "攻擊指令，執行……", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10044", coordinate = "10044", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68676_0", zjeffect = "68677_0", debut = "68675_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "103-Blue_Mountains", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10044001] = {id = 10044001, name = "非例行檢修", story = "機器需要定期進行保養，正如人需要定期進行體檢。作為擁有人類外在的機器，D型b2-H需要進行與本體截然不同的檢測方式。這是無法用設備排查，無關肉體和金屬本質屬性，只有通感者可以進行的旨在擬態人格或者說精神回路上的深度保養。", attackname = "指令，殲滅!", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/10044001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10044001/WatchSpine/Watch_3D_front.prefab", interaction = "10044001", coordinate = "10044001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68676_0", zjeffect = "68677_0", debut = "68675_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "103-Blue_Mountains", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4004400111", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10044001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[10045] = {id = 10045, name = "干練的兩面派", story = "作爲葉芙根尼婭那套裝備的附屬品，由艾吉斯工程部爲特薇爾達開發的輕量化裝甲。從外觀上看，幾乎就只是爲她的日常裝束配上了一把夸張的巨錘。當事人堅持表示這樣就好。", attackname = "總而言之——全給我滾。", painter = "/", voiceexcellence = "舩木詩子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "10045", coordinate = "10045", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68697_0", zjeffect = "68698_0", debut = "68696_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "24_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "106_Everwitner", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[10045001] = {id = 10045001, name = "全力放鬆模式", story = "對單純把駕駛員當成一份工作的特薇爾達來説，工作就只是工作。將一切處理妥當後，不管是擺弄機器，喫著垃圾食品看電影，還是毫不雅觀地在沙發上打个盹，都只是她理當享受的放鬆。", attackname = "我·討·厭·加·班。", painter = "/", voiceexcellence = "舩木詩子", backgroundpic = "ABOriginal/Role/10045001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10045001/WatchSpine/Watch_3D_front.prefab", interaction = "10045001", coordinate = "10045001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68697_0", zjeffect = "68698_0", debut = "68696_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "24_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "106_Everwitner", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4004500109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10045001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
