[10046001] = {id = 10046001, name = "帶來勝利的微笑", story = "即使換上了強調性感與服務精神的兔女郎裝扮，東家當主的威嚴也絲毫沒有減弱半分。", attackname = "貫穿吧。", painter = "/", voiceexcellence = "ゆかな", backgroundpic = "ABOriginal/Role/10046001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/10046001/WatchSpine/Watch_3D_front.prefab", interaction = "10046001", coordinate = "10046001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68710_0", zjeffect = "68711_0", debut = "68709_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4004600113;switch2,idle,4004600114", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,10046001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11000] = {id = 11000, name = "行路的序曲", story = "查麗莎·德·羅蘭畢業時領取的AVG裝甲，陪伴著她輾轉多支小隊，見證她的成長與進步。", attackname = "本小姐一個人就夠了！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11000", coordinate = "11000", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68016_0;60000_14;68015_30", zjeffect = "68017_0", debut = "68260_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "15_0.2_15_60_2_1.5_1,15_0.6_25_60_1.8_3_0.5", delay = "15_0.3,15_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11000001] = {id = 11000001, name = "青澀時光", story = "一套經過改制的春夏季水手服，為查麗莎所有。\n純白衣衫洋溢出活力，群青色短裙隨櫻花飄揚。儘管此裝大膽前衛的剪裁源於一場懲罰遊戲，但穿戴者本人似乎也樂在其中。", attackname = "別來礙事啦！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11000001", coordinate = "11000001", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68016_0;60000_14;68015_30", zjeffect = "68017_0", debut = "68260_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "15_0.2_15_60_2_1.5_1,15_0.6_25_60_1.8_3_0.5", delay = "15_0.3,15_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_hd_0_997", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11000002] = {id = 11000002, name = "觥籌交錯", story = "虹光閃爍，燈影交錯。舞臺中央，查麗莎動作僵硬地圍繞鋼管扭動，石榴色的酒液隨著手臂的擺動在杯中搖晃。高傲的公主脫去了繁瑣的長裙，只是為了回應領航你的期待、為了你的一句玩笑。", attackname = "本小姐一個人就夠了！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/11000002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11000002/WatchSpine/Watch_3D_front.prefab", interaction = "11000002", coordinate = "11000002", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68016_0;60000_14;68015_30", zjeffect = "68017_0", debut = "68260_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "15_0.2_15_60_2_1.5_1,15_0.6_25_60_1.8_3_0.5", delay = "15_0.3,15_0.7", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch2,idle,4100000207", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11000002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11000003] = {id = 11000003, name = "給好孩子的禮物", story = "傳說聖誕節前夜，聖誕老人會給好孩子們派發他們最想要的東西作為聖誕禮物。“誰想要這樣的笨蛋當禮物。”領航偷瞄了一眼被用禮物絲帶緊緊捆紮著的查麗莎後，側過頭歎了一口氣。", attackname = "我可不是聖誕禮物！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/11000003/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11000003", coordinate = "11000003", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68016_0;60000_14;68015_30", zjeffect = "68017_0", debut = "68260_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "15_0.2_15_60_2_1.5_1,15_0.6_25_60_1.8_3_0.5", delay = "15_0.3,15_0.7", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100000310", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11000003,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11001] = {id = 11001, name = "完美的淑女", story = "愛麗絲的AVG裝甲，由克雷蒂婭家設計製造而成，非常契合克雷蒂婭家的劍術。擁有如此裝甲的愛麗絲卻還是達不到她所追尋的“完美”。", attackname = "利刃出鞘！", painter = "/", voiceexcellence = "悠木碧", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11001", coordinate = "11001", generalattack = "18,25,29,35,46", midposition = "0.36,4.17", topposition = "0,8.1", bottomposition = "0,0", buffplacer = "68022_0;60000_19;60000_26;60000_34;60000_49", zjeffect = "68023_0", debut = "68021_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "18_0.1_3_60_1.2_2.6_0.5,7_0.1_5_60_2.5_1_1.5,4_0.1_5_60_1.5_1.5_1.5,6_0.1_6_60_2_3_0.5,11_0.3_22_60_1.5_3.5_1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11001001] = {id = 11001001, name = "夢遊仙境", story = "……愛麗絲發現一個瓶子，上面沒有任何標記。但她扒開瓶塞就放到嘴邊……她還沒喝掉一半，頭已經碰到了天花板……她繼續長啊，長啊……愛麗絲從床上坐起，剛才的噩夢逐漸在記憶中消散。", attackname = "利刃出鞘！", painter = "/", voiceexcellence = "悠木碧", backgroundpic = "ABOriginal/Role/11001001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11001001/WatchSpine/Watch_3D_front.prefab", interaction = "11001001", coordinate = "11001001", generalattack = "18,25,29,35,46", midposition = "0.36,4.17", topposition = "0,8.1", bottomposition = "0,0", buffplacer = "68022_0;60000_19;60000_26;60000_34;60000_49", zjeffect = "68023_0", debut = "68021_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "18_0.1_3_60_1.2_2.6_0.5,7_0.1_5_60_2.5_1_1.5,4_0.1_5_60_1.5_1.5_1.5,6_0.1_6_60_2_3_0.5,11_0.3_22_60_1.5_3.5_1", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100100106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11001001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11001002] = {id = 11001002, name = "聖誕樹的守護仙子", story = "只有聖誕節前夕才會出現的仙子愛麗絲，她會一直守護在一顆完美的聖誕樹旁。直到某位忘記準備聖誕樹的領航找到這裏。但除了聖誕樹外，仙子愛麗絲還準備了一個出乎意料的驚喜。", attackname = "成為聖誕樹的養分吧。", painter = "/", voiceexcellence = "悠木碧", backgroundpic = "ABOriginal/Role/11001002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11001002/WatchSpine/Watch_3D_front.prefab", interaction = "11001002", coordinate = "11001002", generalattack = "18,25,29,35,46", midposition = "0.36,4.17", topposition = "0,8.1", bottomposition = "0,0", buffplacer = "68022_0;60000_19;60000_26;60000_34;60000_49", zjeffect = "68023_0", debut = "68021_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "18_0.1_3_60_1.2_2.6_0.5,7_0.1_5_60_2.5_1_1.5,4_0.1_5_60_1.5_1.5_1.5,6_0.1_6_60_2_3_0.5,11_0.3_22_60_1.5_3.5_1", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100100206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11001002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11002] = {id = 11002, name = "存世之偽神", story = "心紙的AVG裝甲，結合了心經屋的巫女服，以及戰機機翼式的噴射動力裝置，補足信仰的馬力。", attackname = "老身乃神的代行者。", painter = "/", voiceexcellence = "悠木碧", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11002", coordinate = "11002", generalattack = "0", midposition = "0.2,3.85", topposition = "0.15,7.63", bottomposition = "0,0", buffplacer = "68027_0;68020_17;68020_34", zjeffect = "68028_0", debut = "68026_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0.1,0.2,0.2", strike = "15_0.7_13_5_0.4_0.4_1.5,15_0.8_13_6_0.8_0.8_1.2", delay = "15_0.5,15_0.5", admission = "200,200,1.1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11002001] = {id = 11002001, name = "淨水濡夜", story = "心紙擁有的一件樸素衣物。\n沐浴淨身時，心紙便會身著此裝，讓山間澄澈的湖水浸透薄衣，濡濕己身，藉以洗淨雜念與私慾。只是在你的目光下，她那顆心似乎不再如紙般易洗。", attackname = "老身乃神的代行者。", painter = "/", voiceexcellence = "悠木碧", backgroundpic = "ABOriginal/Role/11002001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11002001/WatchSpine/Watch_3D_front.prefab", interaction = "11002001", coordinate = "11002001", generalattack = "0", midposition = "0.2,3.85", topposition = "0.15,7.63", bottomposition = "0,0", buffplacer = "68027_0;68020_17;68020_34", zjeffect = "68028_0", debut = "68026_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0.1,0.2,0.2", strike = "15_0.7_13_5_0.4_0.4_1.5,15_0.8_13_6_0.8_0.8_1.2", delay = "15_0.5,15_0.5", admission = "200,200,1.1,9", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100200106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11002001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11003] = {id = 11003, name = "其疾如風", story = "鈴木清風的AVG裝甲，巨腕裝置與本人側重迅敏的作戰風格相得益彰，彌補了出力不足的問題。", attackname = "忍法·嵐切！", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11003", coordinate = "11003", generalattack = "0", midposition = "0.3,3.58", topposition = "0,6.88", bottomposition = "0,0", buffplacer = "68183_0;60000_13", zjeffect = "68184_0", debut = "68182_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "14_0.3_14_60_2.4_1.9_0.8,16_0.4_19_60_2.9_2.2_0.8", delay = "14_0.4,16_0.6", admission = "200,10,1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11003001] = {id = 11003001, name = "夜櫻初咲染衣濃", story = "一套精緻典雅的戲服，為鈴木清風所有。\n抽中話劇《棲野哀歌》女主角身份的鈴木清風，興高采烈地決定親手縫製戲服。為尋找這套衣裝的靈感，她還動身前往棲野賞了春末最後一期晚櫻。", attackname = "一路順風。", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "ABOriginal/Role/11003001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11003001", coordinate = "11003001", generalattack = "0", midposition = "0.3,3.58", topposition = "0,6.88", bottomposition = "0,0", buffplacer = "68183_0;60000_13", zjeffect = "68184_0", debut = "68182_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "14_0.3_14_60_2.4_1.9_0.8,16_0.4_19_60_2.9_2.2_0.8", delay = "14_0.4,16_0.6", admission = "200,10,1,9", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100300106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11003001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11003002] = {id = 11003002, name = "清風忍法帖", story = "“忍者之道，神秘莫測，需謹記九字箴言——临、兵、斗、者、皆、阵、列、在、前。”……\n“看來這卷軸的確是忍道真傳，有一試的必要。“\n”忍者……真令人期待呢。”鈴木清風如是說。", attackname = "忍法·嵐切！", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "ABOriginal/Role/11003002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11003002/WatchSpine/Watch_3D_front.prefab", interaction = "11003002", coordinate = "11003002", generalattack = "0", midposition = "0.3,3.58", topposition = "0,6.88", bottomposition = "0,0", buffplacer = "68183_0;60000_13", zjeffect = "68184_0", debut = "68182_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "14_0.3_14_60_2.4_1.9_0.8,16_0.4_19_60_2.9_2.2_0.8", delay = "14_0.4,16_0.6", admission = "200,10,1,9", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100300206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11003002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11004] = {id = 11004, name = "不動如山", story = "栗山青鸞的AVG裝甲，彌補了她身體上的缺陷，而輔助的機器人提供了她作為狙擊手最為需要的廣闊視野。", attackname = "目標，拿下！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11004", coordinate = "11004", generalattack = "0", midposition = "0,3.74", topposition = "0,7.25", bottomposition = "0,0", buffplacer = "68069_0;68070_27,68071_0", zjeffect = "0", debut = "68068_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.7,0.15,0.15", strike = "30_0.4_22_60_1.2_2.5_0.8", delay = "30_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11004001] = {id = 11004001, name = "寒椿漫野隱狐蹤", story = "一套彰顯妍華細膩的戲服，上面繁複翩遷的繡花是鈴木清風為栗山青鸞特意設計。性格怯懦的栗山青鸞在《棲野哀歌》扮演的是一名蒙受狐妖眷顧的花魁。穿上這身戲服，她仿佛成為了另一個人。", attackname = "妖異消散！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/11004001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11004001/WatchSpine/Watch_3D_front.prefab", interaction = "11004001", coordinate = "11004001", generalattack = "0", midposition = "0,3.74", topposition = "0,7.25", bottomposition = "0,0", buffplacer = "68069_0;68070_27,68071_0", zjeffect = "0", debut = "68068_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.7,0.15,0.15", strike = "30_0.4_22_60_1.2_2.5_0.8", delay = "30_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100400106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11004001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11006] = {id = 11006, name = "新聞發現者", story = "燕妮的avg裝甲。四足的裝甲設計，讓燕妮能比一般的多瑙駕駛員跑得更快。裝甲各部位都隱藏著高速攝像頭，不僅可以捕捉原罪的身影，還能隨時記錄新聞素材。但是要小心別搞錯快門和扳機的位置。", attackname = "燕妮·羅斯！開炮！", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11006", coordinate = "11006", generalattack = "0", midposition = "1.17,4.15", topposition = "1.6,7.5", bottomposition = "0,0", buffplacer = "68106_0;68109_17,68107_0;68110_32,68107_0", zjeffect = "68108_0", debut = "68105_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.5,0.25,0.25", strike = "27_0.1_12_60_1.6_2_0.4,14_0.2_15_60_1.8_2.4_0.6", delay = "27_0.5,14_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11006001] = {id = 11006001, name = "聖誕老人去哪了？", story = "她身穿紅色棉襖，騎乘金色巨鹿，哼著聖誕頌歌，在黑夜與白雪的掩護下悄悄來到屋旁，將“禮物”拋進煙囪。可她並不是聖誕老人，扔進煙囪的也不止是聖誕禮物。你一定在好奇“她是誰？”，卻忽略了一個重要問題“聖誕老人去哪了？”", attackname = "聖誕頭條！", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/11006001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11006001/WatchSpine/Watch_3D_front.prefab", interaction = "11006001", coordinate = "11006001", generalattack = "0", midposition = "1.17,4.15", topposition = "1.6,7.5", bottomposition = "0,0", buffplacer = "68106_0;68109_17,68107_0;68110_32,68107_0", zjeffect = "68108_0", debut = "68105_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.5,0.25,0.25", strike = "27_0.1_12_60_1.6_2_0.4,14_0.2_15_60_1.8_2.4_0.6", delay = "27_0.5,14_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4100600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11006001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11007] = {id = 11007, name = "雪掠之槍", story = "莉迪婭專屬的AVG裝甲，使用冷造工藝製作而成，能夠在極度嚴寒的環境中戰鬥。與之相對的在熱帶地區，裝甲的性能就會有所損失。但一般情況下莉迪婭也不會離開卡佳去別處戰鬥吧。", attackname = "瞄準！蓄能！射擊!", painter = "/", voiceexcellence = "田中理恵", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11007", coordinate = "11007", generalattack = "0", midposition = "0.15,3.85", topposition = "0.36,7.46", bottomposition = "0,0", buffplacer = "68170_0;68171_16,68172_0;68171_40,68172_0;68171_64,68172_0", zjeffect = "68178_0", debut = "68262_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.1,0.05,0.05", strike = "21_0.1_10_60_1_1.5_0,24_0.1_10_60_1_1.5_0,24_0.2_10_60_1_1.5_0.5", delay = "21_0.3,24_0.3,24_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11007001] = {id = 11007001, name = "慵散度夏", story = "炎熱的海灘，冰涼的水床，已經喝幹的椰子水。莉迪婭從未來過海邊，也從未感受過海邊的慵散。時間仿佛都在陽光的烘烤下融化……此刻莉迪婭只想躺在水床上，懶散地度過這個夏天……", attackname = "瞄準！蓄能！射擊!", painter = "/", voiceexcellence = "田中理恵", backgroundpic = "ABOriginal/Role/11007001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11007001", coordinate = "11007001", generalattack = "0", midposition = "0.15,3.85", topposition = "0.36,7.46", bottomposition = "0,0", buffplacer = "68170_0;68171_16,68172_0;68171_40,68172_0;68171_64,68172_0", zjeffect = "68178_0", debut = "68262_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.1,0.05,0.05", strike = "21_0.1_10_60_1_1.5_0,24_0.1_10_60_1_1.5_0,24_0.2_10_60_1_1.5_0.5", delay = "21_0.3,24_0.3,24_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4100700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11007001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11008] = {id = 11008, name = "煉獄音障", story = "艾希麗卡的AVG……裝甲？比起裝甲，更像是巨大化後的演出設備。看到它們，任何人都會為接下來的聲音煉獄而膽寒。", attackname = "進入我的節奏吧！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11008", coordinate = "11008", generalattack = "0", midposition = "0,4.6", topposition = "0,8.38", bottomposition = "0,0", buffplacer = "68166_0;68167_30,68168_0", zjeffect = "68169_0", debut = "68165_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.8,0.6,0.6", strike = "47_0.2_18_60_1_1.8_0.4", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11008001] = {id = 11008001, name = "恣意沙灘", story = "任何人都需要假期，駕駛員也不例外。艾希利卡在度假的選擇上是明智的， 沙灘、陽光、還有你……以及一個湊熱鬧的金髮姑娘，這就是她恣意妄為的假期。", attackname = "進入我的節奏吧！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/11008001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11008001/WatchSpine/Watch_3D_front.prefab", interaction = "11008001", coordinate = "11008001", generalattack = "0", midposition = "0,4.6", topposition = "0,8.38", bottomposition = "0,0", buffplacer = "68166_0;68167_30,68168_0", zjeffect = "68169_0", debut = "68165_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.8,0.6,0.6", strike = "47_0.2_18_60_1_1.8_0.4", delay = "47_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4100800106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11008001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
