[11011] = {id = 11011, name = "無憫之雷", story = "轟雷專屬的AVG裝甲，由艾吉斯總部設計並製造。設計初衷是為了讓使用者能夠在行動中保證隱秘並提高殺傷性。雖然隱秘和駕駛員的巨大是相悖的，但對於原罪來說，轟雷就是戰場上的一個巨大幽靈。", attackname = "雷電！招徠！", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11011", coordinate = "11011", generalattack = "0", midposition = "-0.1,3.58", topposition = "0,7.36", bottomposition = "0,0", buffplacer = "68195_0", zjeffect = "68196_0,68197_0", debut = "68194_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "8_0.5_16_60_2.2_2.8_0.6", delay = "8_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11011001] = {id = 11011001, name = "靜寂的祈願", story = "寂靜的夜晚，無人的神社，涼爽的夜風吹不散衣襟處淌下的汗水。這裡是神的領域，行走於暗之面的忍者小姐，獨自來此，悄悄地向神明許下自己的心願。", attackname = "夏天……真好啊……", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "ABOriginal/Role/11011001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11011001/WatchSpine/Watch_3D_front.prefab", interaction = "11011001", coordinate = "11011001", generalattack = "0", midposition = "-0.1,3.58", topposition = "0,7.36", bottomposition = "0,0", buffplacer = "68195_0", zjeffect = "68196_0,68197_0", debut = "68194_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "8_0.5_16_60_2.2_2.8_0.6", delay = "8_1", admission = "0", scale = "1,2", bgm = "57-jaw", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4101100109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11011001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
