[11014] = {id = 11014, name = "世界系魔法少女", story = "斯卡蒂的藍色系魔法少女幻想AVG裝甲，這是斯卡蒂的原點，她為其取名為“世界”。", attackname = "斯卡蒂式迅猛劍X！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11014", coordinate = "11014", generalattack = "17,27,51", midposition = "-0.4,3.42", topposition = "-0.1,6.8", bottomposition = "0,0", buffplacer = "68244_0;60000_17;60000_27;60000_51", zjeffect = "0", debut = "68243_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "17_0.1_5_60_1.2_1.5_0,10_0.1_8_60_1.8_1_0.5,24_0.1_14_60_1_3_1.5", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11014001] = {id = 11014001, name = "王之形態其二", story = "斯卡蒂的私服之一，少有的看起來正常的洋裝。\n在你與斯卡蒂約定的早上，輕撚裙角，面泛微紅地走到你面前的是，你從未見過的她。\n是忐忑地等待著你的她，安靜的她。", attackname = "影之國女王登場！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/11014001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11014001/WatchSpine/Watch_3D_front.prefab", interaction = "11014001", coordinate = "11014001", generalattack = "17,27,51", midposition = "-0.4,3.42", topposition = "-0.1,6.8", bottomposition = "0,0", buffplacer = "68244_0;60000_17;60000_27;60000_51", zjeffect = "0", debut = "68243_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "17_0.1_5_60_1.2_1.5_0,10_0.1_8_60_1.8_1_0.5,24_0.1_14_60_1_3_1.5", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4101400106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "3,11014001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
