[11016] = {id = 11016, name = "無想之羽", story = "黑羽專屬的AVG裝甲。背負著“黑羽”名號的忍者少女，她潛身在黑暗中，在沒有任務的時候，時時刻刻為你的事情奔走著。這既是出於忠誠也有少女的情義。只有在極少數的時候你才能察覺到她的存在。", attackname = "我會保護您的。", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11016", coordinate = "11016", generalattack = "0", midposition = "0.36,4.23", topposition = "0.25,7.42", bottomposition = "0,0", buffplacer = "68255_0;68256_34,68257_0", zjeffect = "68252_0", debut = "68254_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "68253_0", pd_2 = "0", hc_1 = "0", hc_2 = "68254_0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0.2,0.1,0.1", strike = "42_0.4_12_60_1.8_2.6_0.4", delay = "42_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11016001] = {id = 11016001, name = "新年最初的“驚喜”", story = "在新的一年準備偷偷潛入你的家中給你驚喜的忍者少女，但讓她玩玩沒想到的是你身邊的守護者數不勝數，她們為你設下了多重的保護手段，即使是身為“黑羽”的少女也因為大意在連續而繁雜的陷阱中敗下陣來。最終把自己變成了“驚喜”。", attackname = "我會保護您的。", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "ABOriginal/Role/11016001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11016001", coordinate = "11016001", generalattack = "0", midposition = "0.36,4.23", topposition = "0.25,7.42", bottomposition = "0,0", buffplacer = "68255_0;68256_34,68257_0", zjeffect = "68252_0", debut = "68254_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "68253_0", pd_2 = "0", hc_1 = "0", hc_2 = "68254_0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0.2,0.1,0.1", strike = "42_0.4_12_60_1.8_2.6_0.4", delay = "42_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4101600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11016001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11017] = {id = 11017, name = "首席親衛", story = "芙蘿拉專屬的AVG裝甲。類似女僕裝的樣式，實則是用大量合金製作，抗擊打能力優秀。至於這怪異的樣式到底是誰的設計，恐怕連芙蘿拉自己都不清楚。", attackname = "接管戰場！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11017", coordinate = "11017", generalattack = "0", midposition = "0,3.31", topposition = "0.15,6.87", bottomposition = "0,0", buffplacer = "68275_0;60000_16;60000_50", zjeffect = "68277_0", debut = "68276_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "16_0.3_15_60_2_2.6_0.8,34_0.3_16_60_2.2_3.4_0.6,12_0.4_24_60_2.8_3.8_1.6", delay = "16_0.3,34_0.3,12_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11017001] = {id = 11017001, name = "戀愛親衛隊", story = "高傲的親衛脫去鎧甲，堅貞的女僕放下矜持。在這互剖心跡‌的甜蜜節日裏，愛情是唯一需要守衛的高嶺。戀愛親衛芙蘿拉，在此立誓，她將不惜一切，傾盡全部，融化自我，只為守住領航心中，那塊屬於自己的小小領地。", attackname = "接管戰場！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/11017001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11017001/WatchSpine/Watch_3D_front.prefab", interaction = "11017001", coordinate = "11017001", generalattack = "0", midposition = "0,3.31", topposition = "0.15,6.87", bottomposition = "0,0", buffplacer = "68275_0;60000_16;60000_50", zjeffect = "68277_0", debut = "68276_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "16_0.3_15_60_2_2.6_0.8,34_0.3_16_60_2.2_3.4_0.6,12_0.4_24_60_2.8_3.8_1.6", delay = "16_0.3,34_0.3,12_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11017001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11018] = {id = 11018, name = "斬月之爪", story = "漢克", attackname = "給予……死亡！", painter = "/", voiceexcellence = "篠原夢", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11018", coordinate = "11018", generalattack = "0", midposition = "0,2.66", topposition = "0,5.79", bottomposition = "0,0", buffplacer = "68268_1", zjeffect = "68269_0", debut = "68267_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "68267_0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "8_0.3_15_60_1.8_2.5_0.6,21_0.2_13_60_2.2_1.4_0.6,7_0.2_13_60_1.2_2.9_1,7_0.2_14_60_1.5_3_1.5", delay = "8_0.3,21_0.2,7_0.2,7_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11019] = {id = 11019, name = "百萬噸級料理大師", story = "天天的AVG裝備，是薩哈拉支部所屬學院的硏發部根據她的个人喜好量身打造的裝備，著重強化了武器命中敵人時的衝擊力。\n她臉上的笑容，應該和被她砸扁的敵人毫無關繫吧？", attackname = "咚！咚！咚！", painter = "/", voiceexcellence = "阿保まりあ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11019", coordinate = "11019", generalattack = "0", midposition = "0.36,3.8", topposition = "0.2,7.41", bottomposition = "0,0", buffplacer = "68299_0", zjeffect = "68300_0", debut = "68298_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "28_0.3_22_60_2.2_3.2_0.4,25_0.3_20_60_1.8_3.6_1", delay = "28_0.4,25_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11019001] = {id = 11019001, name = "仲冬夜的獻禮", story = "爲了將笑容送給聖誕夜的朋友們，換上聖誕老人的服裝，將親手製作的禮物裝進袋子裏，開始巡迴的一晚。\n雪橇跑起來吧，就像風兒一樣~", attackname = "肉餅也能當禮物！", painter = "/", voiceexcellence = "阿保まりあ", backgroundpic = "ABOriginal/Role/11019001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11019001/WatchSpine/Watch_3D_front.prefab", interaction = "11019001", coordinate = "11019001", generalattack = "0", midposition = "0.36,3.8", topposition = "0.2,7.41", bottomposition = "0,0", buffplacer = "68299_0", zjeffect = "68300_0", debut = "68298_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "28_0.3_22_60_2.2_3.2_0.4,25_0.3_20_60_1.8_3.6_1", delay = "28_0.4,25_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4101900106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11019001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11020] = {id = 11020, name = "雙劍的雙馬尾", story = "卡洛琳專屬的AVG裝甲。雖然按照某位隊長的要求增加了很多花哨的設計，但是整體看下來好像又沒什麽特別的。總之是很紥實的一套AVG裝甲。", attackname = "看見了嗎？", painter = "/", voiceexcellence = "阿保まりあ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11020", coordinate = "11020", generalattack = "21,41", midposition = "0.28,3.46", topposition = "0.28,7.68", bottomposition = "0,0", buffplacer = "68302_0", zjeffect = "68303_0", debut = "68301_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "21_0.9_52_60_1.2_1.6_0.8,41_0.28_14_60_2.1_2.7_0.9", delay = "21_0.6,41_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11020001] = {id = 11020001, name = "不過是例行清潔", story = "似乎是知道領航會在這個時間點光臨，卡洛琳特地在此時做清潔，但對領航說的卻只是例行工作。連同事都被提前請走，只剩下兩個人的咖啡廳內，不知道卡洛琳究竟有什麼特別的打算……", attackname = "看見了嗎？", painter = "/", voiceexcellence = "阿保まりあ", backgroundpic = "ABOriginal/Role/11020001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11020001/WatchSpine/Watch_3D_front.prefab", interaction = "11020001", coordinate = "11020001", generalattack = "21,41", midposition = "0.28,3.46", topposition = "0.28,7.68", bottomposition = "0,0", buffplacer = "68302_0", zjeffect = "68303_0", debut = "68301_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "21_0.9_52_60_1.2_1.6_0.8,41_0.28_14_60_2.1_2.7_0.9", delay = "21_0.6,41_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4102000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11020001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
