[11022] = {id = 11022, name = "王之形態其四", story = "王女的專屬服裝。一年四季都都是這一身，夏天的時候透氣而清涼，冬天的時候能抵禦嚴寒，擁有自動清潔的功能，除了讓人覺得你是一個不換洗衣服的髒小孩之外沒有任何缺陷的衣服。", attackname = "這就是我和我的合擊技！", painter = "/", voiceexcellence = "平塚紗依", backgroundpic = "ABOriginal/Role/11022/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11022", coordinate = "11022", generalattack = "57,91", midposition = "0,4.27", topposition = "0,8.47", bottomposition = "0,0", buffplacer = "68502_0", zjeffect = "68503_0", debut = "68501_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.446", attackdistance = 12, bulletvelocity = "0", strike = "56_0.3_17_60_1.7_2.9_1,35_0.35_21_60_2.2_3.1_1.5", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11022001] = {id = 11022001, name = "夏之王女魅力時刻", story = "覲見吧，祝賀吧。這是陽光燦爛的夏之影之國王女的無懈可擊的肉體，你將見到的是足以載入曆史的散發著大人魅力的王女。為了照顧立下了豐功偉績的你而特意穿著的服飾。", attackname = "這就是我和我的合擊技！", painter = "/", voiceexcellence = "平塚紗依", backgroundpic = "ABOriginal/Role/11022001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11022001/WatchSpine/Watch_3D_front.prefab", interaction = "11022001", coordinate = "11022001", generalattack = "57,91", midposition = "0,4.27", topposition = "0,8.47", bottomposition = "0,0", buffplacer = "68502_0", zjeffect = "68503_0", debut = "68501_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.446", attackdistance = 12, bulletvelocity = "0", strike = "56_0.3_17_60_1.7_2.9_1,35_0.35_21_60_2.2_3.1_1.5", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4102200106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11022001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11022002] = {id = 11022002, name = "受冕之日", story = "王女靠在她的王座上，心裡只等著某人的出現。 不管是叫那個人騎士、王子還是伴侶，反正她認定的人，就只有你——從領航走向她的這一刻起，她這個人，她的內心，還有她肩負的整個未來，都將與領航共亯。", attackname = "這就是我和我的合擊技！", painter = "/", voiceexcellence = "平冢纱依", backgroundpic = "ABOriginal/Role/11022002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11022002/WatchSpine/Watch_3D_front.prefab", interaction = "11022002", coordinate = "11022002", generalattack = "57,91", midposition = "0,4.27", topposition = "0,8.47", bottomposition = "0,0", buffplacer = "68502_0", zjeffect = "68503_0", debut = "68501_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.446", attackdistance = 12, bulletvelocity = "0", strike = "56_0.3_17_60_1.7_2.9_1,35_0.35_21_60_2.2_3.1_1.5", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4102200206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11022002,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11023] = {id = 11023, name = "曉夢", story = "曉夢的AVG裝甲。用九州傳統技藝打造，堅固耐用，注重穩定。這套裝備貫徹了曉夢的拳術，然而曉夢並不在乎穿什麼去戰鬥。她只要按照命令向前揮拳就行了。", attackname = "我打！", painter = "/", voiceexcellence = "空賀花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11023", coordinate = "11023", generalattack = "0", midposition = "0.05,5", topposition = "0,8.5", bottomposition = "0,0", buffplacer = "68136_0", zjeffect = "68137_0", debut = "68135_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "44_0.35_17_60_1.3_2.5_1,20_0.35_15_60_2_2.9_1.4,13_0.3_18_60_1.6_2_0.7", delay = "44_0.4,20_0.3,13_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11023001] = {id = 11023001, name = "陷入“僵”局", story = "月明星稀，煙雲繚繞。一妙齡少女亭亭僵立於門牌之前。她身著古衣，腳穿白履，額上貼一朱砂黃紙。指尖呈現如血般的暗紅。這是僵屍嗎？不，曉夢不過是在等待領航，一同前往萬聖宴席。", attackname = "我打！", painter = "/", voiceexcellence = "空賀花", backgroundpic = "ABOriginal/Role/11023001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11023001/WatchSpine/Watch_3D_front.prefab", interaction = "11023001", coordinate = "11023001", generalattack = "0", midposition = "0.05,5", topposition = "0,8.5", bottomposition = "0,0", buffplacer = "68136_0", zjeffect = "68137_0", debut = "68135_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "44_0.35_17_60_1.3_2.5_1,20_0.35_15_60_2_2.9_1.4,13_0.3_18_60_1.6_2_0.7", delay = "44_0.4,20_0.3,13_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4102300110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11023001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11023002] = {id = 11023002, name = "情人節？是七夕嗎？", story = "“有情人之間互相贈送禮物表情心意，彰顯愛情的節日？嗯嗯，曉夢完全懂了！就是那個節日吧！”這麼回應著的曉夢，穿著據說是為七夕節準備的服裝登場了，看來她完全理解錯了節日。不過你已經對此見怪不怪了，至少她本人因為難得的新衣服而開心著。", attackname = "我打！", painter = "/", voiceexcellence = "空賀花", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "0", interaction = "11023002", coordinate = "11023002", generalattack = "0", midposition = "0.05,5", topposition = "0,8.5", bottomposition = "0,0", buffplacer = "68136_0", zjeffect = "68137_0", debut = "68135_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "44_0.35_17_60_1.3_2.5_1,20_0.35_15_60_2_2.9_1.4,13_0.3_18_60_1.6_2_0.7", delay = "44_0.4,20_0.3,13_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level,idle,4102300206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,11023002,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11024] = {id = 11024, name = "潛鮫", story = "漢克", attackname = "海豚俠出擊！", painter = "/", voiceexcellence = "中山まなか", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11024", coordinate = "11024", generalattack = "0", midposition = "0,4.1", topposition = "0,8.28", bottomposition = "0,0", buffplacer = "68397_0", zjeffect = "68398_0", debut = "68396_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.36", attackdistance = 14, bulletvelocity = "0", strike = "40_0.4_21_60_2.3_3_1.4", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11027] = {id = 11027, name = "灰玫惑亂", story = "因為是受刑人，所以今七實並沒有自己專屬的AVG裝甲，即使巨大化，服裝也只是自己平常所穿的衣物。危險，不安，毛骨悚然，這就是她給人的觀感。", attackname = "我還是更喜歡躲在大家身後。", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11027", coordinate = "11027", generalattack = "0", midposition = "0,4.5", topposition = "0,8.9", bottomposition = "0,0", buffplacer = "68534_0", zjeffect = "68535_0", debut = "68533_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "18_0.3_15_60_1.7_2.6_1,12_0.35_19_60_2.1_2.8_1.1,45_0.3_18_60_2.1_3_1.4", delay = "18_0.3,12_0.4,46_0.3", admission = "0", scale = "0.5,1.5", bgm = "78-Romance", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11027001] = {id = 11027001, name = "窒息的審問", story = "心靈扭曲的人無法依靠尋常的言語來矯正，不用動真格的手段是無法讓她切身感受到痛苦的——史蒂芬妮的說法讓你感到懷疑，但不管如何，你也意識到自己的確需要一場和今七實深入心靈的對談，不然你永遠也無法了解這個女人。", attackname = "我還是更喜歡躲在大家身後。", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "ABOriginal/Role/11027001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11027001", coordinate = "11027001", generalattack = "0", midposition = "0,4.5", topposition = "0,8.9", bottomposition = "0,0", buffplacer = "68534_0", zjeffect = "68535_0", debut = "68533_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "18_0.3_15_60_1.7_2.6_1,12_0.35_19_60_2.1_2.8_1.1,45_0.3_18_60_2.1_3_1.4", delay = "18_0.3,12_0.4,46_0.3", admission = "0", scale = "1,2", bgm = "78-Romance", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11027001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11027002] = {id = 11027002, name = "甜蜜之罪", story = "“為慶祝這个甜蜜的日子，為最愛的領航小弟你準備了專門的裝束和手工巧克力”——你收到的邀請函上是這麽寫的，如果眞是這麽老土又甜蜜的展開才有鬼了。", attackname = "我還是更喜歡躲在大家身後。", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "ABOriginal/Role/11027002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11027002", coordinate = "11027002", generalattack = "0", midposition = "0,4.5", topposition = "0,8.9", bottomposition = "0,0", buffplacer = "68534_0", zjeffect = "68535_0", debut = "68533_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "18_0.3_15_60_1.7_2.6_1,12_0.35_19_60_2.1_2.8_1.1,45_0.3_18_60_2.1_3_1.4", delay = "18_0.3,12_0.4,46_0.3", admission = "0", scale = "1,2", bgm = "78-Romance", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4102700206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11027002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11028] = {id = 11028, name = "複誕者", story = "潔蘿專屬的AVG裝甲，由第一研究室研製。死而復生永遠是最吸引人的話題之一，自然也引起了第一研究室的注意。第一研究室的負責人，瓦爾基裡的隊長亞爾薇特甚至親自設計研製了這款複生者專用的裝甲。", attackname = "咚！咚！咚！", painter = "/", voiceexcellence = "下地紫野", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11028", coordinate = "11028", generalattack = "0", midposition = "0,3.97", topposition = "0,8.14", bottomposition = "0,0", buffplacer = "68271_0;60000_16", zjeffect = "68272_0", debut = "68270_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "16_0.3_14_60_1.4_2.6_0.7,14_0.25_14_60_0.7_0.9_0.4,20_0.5_32_60_2.5_3.2_1.9", delay = "16_0.3,14_0.2,20_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11028001] = {id = 11028001, name = "花咲的神名", story = "傳說神明花費七天創造世界，自身卻被世界排斥。只因世界無力承載神明的軀體。於是祂將肉身捨棄，以精神操控物質，寄神魂於花種，灌溉百川交匯之水，塑造凡軀。此後世間再無神明，而是多了位風姿綽約的人。", attackname = "咚！咚！咚！", painter = "/", voiceexcellence = "下地紫野", backgroundpic = "ABOriginal/Role/11028001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11028001/WatchSpine/Watch_3D_front.prefab", interaction = "11028001", coordinate = "11028001", generalattack = "0", midposition = "0,3.97", topposition = "0,8.14", bottomposition = "0,0", buffplacer = "68271_0;60000_16", zjeffect = "68272_0", debut = "68270_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 12, bulletvelocity = "0", strike = "16_0.3_14_60_1.4_2.6_0.7,14_0.25_14_60_0.7_0.9_0.4,20_0.5_32_60_2.5_3.2_1.9", delay = "16_0.3,14_0.2,20_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level3_a,idle3,4102800111;level3_b,idle,4102800115;level1_a,idle2,4102800109;level1_b,idle,4102800113", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11028001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11029] = {id = 11029, name = "雛鷹之矩", story = "千陌的AVG裝甲。由撒哈拉學院制式的裝備改造而來。相對於原本的裝備，在性能上有進一步的加強，是一套綜合偵察和正面對抗的一體化裝甲。", attackname = "以暴制暴，法隨勢易。", painter = "/", voiceexcellence = "空賀花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11029", coordinate = "11029", generalattack = "0", midposition = "0,4.06", topposition = "0,8.02", bottomposition = "0,0", buffplacer = "68337_0", zjeffect = "68338_0;68339_25", debut = "68336_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "17_0.35_24_60_2.6_1.8_1.4,28_0.4_22_60_2.2_3_1.8", delay = "17_0.4,28_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11029001] = {id = 11029001, name = "學生會長的秘密", story = "一向嚴肅正經的學生會長，在誤將收繳的酒液當作汽水喝下後，表露出她自由不羈的一面。要不是有領航老師陪伴在身邊，恐怕明天“醉酒的學生會長在學院狂走”的標題將成為學院報的頭版頭條。", attackname = "以暴制暴，法隨勢易。", painter = "/", voiceexcellence = "空賀花", backgroundpic = "ABOriginal/Role/11029001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11029001/WatchSpine/Watch_3D_front.prefab", interaction = "11029001", coordinate = "11029001", generalattack = "0", midposition = "0,4.06", topposition = "0,8.02", bottomposition = "0,0", buffplacer = "68337_0", zjeffect = "68338_0;68339_25", debut = "68336_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "17_0.35_24_60_2.6_1.8_1.4,28_0.4_22_60_2.2_3_1.8", delay = "17_0.4,28_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4102900106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11029001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11029002] = {id = 11029002, name = "風搖靑玉枝", story = "微風劃過林間，竹葉隨風而舞。錯綜而有序的翠竹，爲風和竹葉框定了嬉戲的舞臺。此間的靜謐，獨畱風葉相交的歡語。對千陌而言，這裏正是修養身心的最佳場所。", attackname = "以暴制暴，法隨勢易。", painter = "/", voiceexcellence = "空賀花", backgroundpic = "ABOriginal/Role/11029002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11029002/WatchSpine/Watch_3D_front.prefab", interaction = "11029002", coordinate = "11029002", generalattack = "0", midposition = "0,4.06", topposition = "0,8.02", bottomposition = "0,0", buffplacer = "68337_0", zjeffect = "68338_0;68339_25", debut = "68336_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "17_0.35_24_60_2.6_1.8_1.4,28_0.4_22_60_2.2_3_1.8", delay = "17_0.4,28_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4102900206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11029002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11030] = {id = 11030, name = "澄練", story = "澄練的AVG裝甲。用九州傳統技藝打造，堅固耐用，注重穩定。這套裝甲在未来将標誌著她的身份——她將用這身裝甲以平心社這一重要身份（至少她是這麼認為的）出現在人類的歷史上。", attackname = "筆落。", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11030", coordinate = "11030", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68139_0", zjeffect = "68140_0", debut = "68138_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "17_0.45_27_60_2.6_3.4_1.9,35_0.35_17_60_2.4_3_1.8", delay = "17_0.6,35_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11030001] = {id = 11030001, name = "書畫盡晝", story = "“這是我們家鄉的傳統服飾……慶賀佳節，寓意吉祥 ……但是……但是……領航不覺得這身衣服有點奇怪嗎……”“總覺得……涼颼颼的……”", attackname = "退下吧。", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "ABOriginal/Role/11030001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11030001/WatchSpine/Watch_3D_front.prefab", interaction = "11030001", coordinate = "11030001", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68139_0", zjeffect = "68140_0", debut = "68138_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "17_0.45_27_60_2.6_3.4_1.9,35_0.35_17_60_2.4_3_1.8", delay = "17_0.6,35_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4103000106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "5,11030001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11031] = {id = 11031, name = "怒火刃牙", story = "漢克", attackname = "嗷——", painter = "/", voiceexcellence = "中臣真菜", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11031", coordinate = "11031", generalattack = "0", midposition = "0.1,4.06", topposition = "0.1,8.16", bottomposition = "0,0", buffplacer = "68370_0", zjeffect = "68371_0;68372_25", debut = "68369_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "68373_0", "0", "0", qzoom = "0.45", attackdistance = 14, bulletvelocity = "0", strike = "16_0.65_30_60_2.4_3.1_2", delay = "16_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11032] = {id = 11032, name = "殺人志願", story = "千秋專屬的AVG裝甲，其實只是將千秋平時的習慣的衣服變大而已。極少的用料註定了該裝甲不會提供太多的防護性，但也不會在千秋殺人時造成妨礙。", attackname = "去死！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11032", coordinate = "11032", generalattack = "0", midposition = "0,4.11", topposition = "0,8.3", bottomposition = "0,0", buffplacer = "68381_0", zjeffect = "68382_0", debut = "68380_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 15, bulletvelocity = "0", strike = "10_0.8_42_60_1.6_2.8_1,38_0.35_20_60_2.4_3.2_1.8", delay = "10_0.4,38_0.6", admission = "0", scale = "0.5,1.5", bgm = "25-Lowtea_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11032001] = {id = 11032001, name = "漢堡連環消失事件", story = "哦？名偵探千秋發現了被分屍的狗狗冰激淩漢堡。是誰犯下這麼殘忍的罪行？名偵探千秋將偵破真相。首先是屍體檢查，嗚姆嗚姆，如此甜膩……我想起來了，原來分屍漢堡的犯人……就是我啊。", attackname = "去死！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "ABOriginal/Role/11032001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11032001/WatchSpine/Watch_3D_front.prefab", interaction = "11032001", coordinate = "11032001", generalattack = "0", midposition = "0,4.11", topposition = "0,8.3", bottomposition = "0,0", buffplacer = "68381_0", zjeffect = "68382_0", debut = "68380_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 13, bulletvelocity = "0", strike = "10_0.8_42_60_1.6_2.8_1,38_0.35_20_60_2.4_3.2_1.8", delay = "10_0.4,38_0.6", admission = "0", scale = "1,2", bgm = "25-Lowtea_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11032001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11033] = {id = 11033, name = "天青色的幸運", story = "星爍專屬的AVG裝甲。由於星爍特殊的巨大化方式，與巨大化同時出現的衣服僅僅只是起到遮羞的作用。因為星爍的運氣很好，所以不必擔心她會在戰鬥中受傷。", attackname = "要小心哟。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11033", coordinate = "11033", generalattack = "0", midposition = "0.1,4.36", topposition = "0.1,8.9", bottomposition = "0,0", buffplacer = "68378_0", zjeffect = "68379_0", debut = "68377_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 13, bulletvelocity = "0", strike = "12_0.2_8_60_1.5_2_0.5,15_0.85_46_60_1.7_2.9_1,27_0.45_27_60_2.1_3.4_1.7", delay = "12_0.2,15_0.3,27_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11033001] = {id = 11033001, name = "天空為誰而晴", story = "星爍小姐的私密泳裝。\n明明早上天氣還狂風巨浪，可是我們一到這裏就變得風平浪靜。奇怪，難道這裏的天空會因為我們的到來而放晴嗎？又不是100%晴女……", attackname = "要小心哟。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "ABOriginal/Role/11033001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11033001/WatchSpine/Watch_3D_front.prefab", interaction = "11033001", coordinate = "11033001", generalattack = "0", midposition = "0.1,4.36", topposition = "0.1,8.9", bottomposition = "0,0", buffplacer = "68378_0", zjeffect = "68379_0", debut = "68377_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.45", attackdistance = 13, bulletvelocity = "0", strike = "12_0.2_8_60_1.5_2_0.5,15_0.85_46_60_1.7_2.9_1,27_0.45_27_60_2.1_3.4_1.7", delay = "12_0.2,15_0.3,27_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4103300108", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11033001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11034] = {id = 11034, name = "天生領袖", story = "羅德尼亞的AVG裝甲，完全不同於第三防衛班偏向防守的制式裝备。為了契合羅德尼亞高超的槍鬥術，研發部特地定制了一整套的裝甲。", attackname = "吃我超痛的一擊！", painter = "/", voiceexcellence = "和氣あず未", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11034", coordinate = "11034", generalattack = "0", midposition = "0.16,4.34", topposition = "0.16,8.27", bottomposition = "0,0", buffplacer = "68008_0", zjeffect = "68009_0", debut = "68001_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "35_0.85_48_60_2.7_3.8_2.1", delay = "35_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11034001] = {id = 11034001, name = "超鯊魚剋星", story = "夏日炎炎，此海域禁止游泳，有鯊魚出沒。\n“你怎麼知道我釣上了条大鯊魚！”\n“哈哈，我就是超厲害的釣魚大師！”", attackname = "吃我超痛的一擊！", painter = "/", voiceexcellence = "和氣あず未", backgroundpic = "ABOriginal/Role/11034001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11034001/WatchSpine/Watch_3D_front.prefab", interaction = "11034001", coordinate = "11034001", generalattack = "0", midposition = "0.16,4.34", topposition = "0.16,8.27", bottomposition = "0,0", buffplacer = "68008_0", zjeffect = "68009_0", debut = "68001_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "35_0.85_48_60_2.7_3.8_2.1", delay = "35_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level2,idle,4103400107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11034001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11035] = {id = 11035, name = "所羅門的惡魔", story = "桀派專屬的AVG裝甲，是用桀派以前的裝甲改良而成。裝甲內安裝了很多特殊的功能模組，主要用於減少戰鬥時的身體負擔。", attackname = "怎麼就輪到我了呢……", painter = "/", voiceexcellence = "長縄まりあ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11035", coordinate = "11035", generalattack = "0", midposition = "0.1,4.59", topposition = "0.1,8.93", bottomposition = "0,0", buffplacer = "68358_0", zjeffect = "68359_0;68360_30", debut = "68357_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 44, bulletvelocity = "0", strike = "41_0.65_42_60_2.5_3.6_2", delay = "41_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11035001] = {id = 11035001, name = "香甜的派", story = "香甜軟糯，秀色可餐的派。竟然如此大方地袒露在面前，毫無防備。令人食指大動，好想嘬上一口，用舌頭細細品嘗派的美味。", attackname = "怎麼就輪到我了呢……", painter = "/", voiceexcellence = "長縄まりあ", backgroundpic = "ABOriginal/Role/11035001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11035001/WatchSpine/Watch_3D_front.prefab", interaction = "11035001", coordinate = "11035001", generalattack = "0", midposition = "0.1,4.59", topposition = "0.1,8.93", bottomposition = "0,0", buffplacer = "68358_0", zjeffect = "68359_0;68360_30", debut = "68357_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 44, bulletvelocity = "0", strike = "41_0.65_42_60_2.5_3.6_2", delay = "41_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4103500107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11035001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11036] = {id = 11036, name = "原罪學者", story = "普瑞席歐專屬的AVG裝甲，大部分由普瑞席歐自行研發並委託薩哈拉蒼穹學院研製。作為學院最頂尖的一批原罪學者，她在設計中運用了最前沿的原罪學知識，甚至將原罪本身也融合進了裝備中。", attackname = "小的們，給我上~", painter = "/", voiceexcellence = "盛 恵里花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11036", coordinate = "11036", generalattack = "25,30", midposition = "0,4.17", topposition = "0,8.09", bottomposition = "0,0", buffplacer = "68389_0", zjeffect = "68390_0", debut = "68388_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.25_13_60_1.6_2_1,9_0.35_15_60_1.9_2.5_1.4,22_0.5_27_60_2.4_3.5_1.9", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11036001] = {id = 11036001, name = "靛藍之禮", story = "在蒼穹學院獨有的周年慶典中，普瑞席歐極其反常地穿上了一件深藍色的禮裙，孤身一人在花園間漫步。蝴蝶、蜜蜂都被普瑞席歐所吸引圍繞在其左右，殊不知她的真正目標正是受邀前來參加慶典的你。", attackname = "小的們，給我上~", painter = "/", voiceexcellence = "盛 恵里花", backgroundpic = "ABOriginal/Role/11036001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11036001/WatchSpine/Watch_3D_front.prefab", interaction = "11036001", coordinate = "11036001", generalattack = "25,30", midposition = "0,4.17", topposition = "0,8.09", bottomposition = "0,0", buffplacer = "68389_0", zjeffect = "68390_0", debut = "68388_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.25_13_60_1.6_2_1,9_0.35_15_60_1.9_2.5_1.4,22_0.5_27_60_2.4_3.5_1.9", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4103600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11036001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11036002] = {id = 11036002, name = "頭腦派的夏日準備", story = "普瑞席歐興沖沖地把你加入了她的夏日計劃，做好心理准備赴約的你卻只看到了一身意料之外的普通泳裝。只剩下學者小姐壞笑的表情和從不離手的終端暗示著其背後的玄機。", attackname = "小的們，給我上~", painter = "/", voiceexcellence = "盛 恵裡花", backgroundpic = "ABOriginal/Role/11036002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11036002/WatchSpine/Watch_3D_front.prefab", interaction = "11036002", coordinate = "11036002", generalattack = "25,30", midposition = "0,4.17", topposition = "0,8.09", bottomposition = "0,0", buffplacer = "68389_0", zjeffect = "68390_0", debut = "68388_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.25_13_60_1.6_2_1,9_0.35_15_60_1.9_2.5_1.4,22_0.5_27_60_2.4_3.5_1.9", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "聯動限定", ismorestate = 1, shopanim = "level1,idle,4103600206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11036002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11037] = {id = 11037, name = "聖潔修女", story = "塞蕾希婭專屬的AVG裝甲。原型皆源於聖濯教會內的聖物，但打造它們所使用的卻是來自艾吉斯科學部的尖端科技。\n順帶一提，記錄AVG藍圖的裝置已送去教會接受洗禮。", attackname = "請由我清除不潔之物……", painter = "/", voiceexcellence = "桐村まり", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11037", coordinate = "11037", generalattack = "0", midposition = "0,4.37", topposition = "0,8.57", bottomposition = "0,0", buffplacer = "68392_0;68393_20", zjeffect = "68394_0;68395_25", debut = "68391_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.45,0.2,0.2", strike = "75_0.4_27_60_2.7_3.9_1.8", delay = "75_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11037001] = {id = 11037001, name = "球上運動", story = "不僅僅是爲了凈化身體的污穢，更是爲了追求精神的純凈，塞蕾希婭決定將瑜伽練習納入每日日程。看著汗水浸濕身下的健身球，仿佛身體裏的污穢也隨之被一同排出。然而不知爲何，塞蕾希婭感覺自己的精神正變得愈發混沌。", attackname = "請由我清除不潔之物……", painter = "/", voiceexcellence = "桐村まり", backgroundpic = "ABOriginal/Role/11037001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11037001", coordinate = "11037001", generalattack = "0", midposition = "0,4.37", topposition = "0,8.57", bottomposition = "0,0", buffplacer = "68392_0;68393_20", zjeffect = "68394_0;68395_25", debut = "68391_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.45,0.2,0.2", strike = "75_0.4_27_60_2.7_3.9_1.8", delay = "75_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4103700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11037001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11038] = {id = 11038, name = "叛逆之棘", story = "卡芙卡的AVG裝甲，與她平時所穿的張揚服裝風格一致，佈滿了尖銳物、鉚釘與鎖鏈，完全符合卡芙卡從熱血漫畫中了解到的“不良少女”印象。", attackname = "夜露死苦！", painter = "/", voiceexcellence = "中山まなか", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11038", coordinate = "11038", generalattack = "0", midposition = "0,4.41", topposition = "0,9.78", bottomposition = "0,0", buffplacer = "68400_0", zjeffect = "68401_0", debut = "68399_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "26_0.35_20_60_2.1_2.9_1.9,50_0.4_24_60_2.6_3.7_1.5", delay = "26_0.4,50_0.6", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11038001] = {id = 11038001, name = "前有“餓”鬼", story = "月光清冷孤寂，枯林猙獰扭曲，幽幽燭火下，被重重束帶封印多年的惡鬼，正在陰魂不散地向你發出呼喚，訴說她對糖果的所有渴望與怨念。", attackname = "交出你的糖果！", painter = "/", voiceexcellence = "中山まなか", backgroundpic = "ABOriginal/Role/11038001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11038001/WatchSpine/Watch_3D_front.prefab", interaction = "11038001", coordinate = "11038001", generalattack = "0", midposition = "0,4.41", topposition = "0,9.78", bottomposition = "0,0", buffplacer = "68400_0", zjeffect = "68401_0", debut = "68399_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "26_0.35_20_60_2.1_2.9_1.9,50_0.4_24_60_2.6_3.7_1.5", delay = "26_0.4,50_0.6", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "leve1,idle,4103800106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11038001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11039] = {id = 11039, name = "王之形態其三", story = "影之國女王鐘愛的第三件衣服，延續了第二形態的審美。“在寂滅的月之下，為你的過錯贖罪吧。”“吾乃血之真祖！”“現在把汝的時間交出來，吾要吃飯了！”", attackname = "臣服于吾", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11039", coordinate = "11039", generalattack = "0", midposition = "0,4.61", topposition = "0,9.13", bottomposition = "0,0", buffplacer = "68452_0", zjeffect = "68453_0", debut = "68451_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "13_0.25_13_60_1.9_2.4_0.6,13_0.35_17_60_2.1_3_1.1", delay = "27_1", admission = "0", scale = "0.5,1.5", bgm = "64-memorize", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11039001] = {id = 11039001, name = "中二魅魔是吸血鬼！", story = "斯卡蒂稱其為王之形態其三。“哈—哈—哈—這正是影之國女王的第三形態——吸血鬼魅魔混血王女。”，“看不出魅魔的特徵？哼哼……看看吾的腹部吧，那裡可是有魅魔獨有的魔法紋路。”", attackname = "臣服于吾", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/11039001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11039001/WatchSpine/Watch_3D_front.prefab", interaction = "11039001", coordinate = "11039001", generalattack = "0", midposition = "0,4.61", topposition = "0,9.13", bottomposition = "0,0", buffplacer = "68452_0", zjeffect = "68453_0", debut = "68451_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "13_0.25_13_60_1.9_2.4_0.6,13_0.35_17_60_2.1_3_1.1", delay = "27_1", admission = "0", scale = "1,2", bgm = "64-memorize", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11039001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11040] = {id = 11040, name = "奇跡的輝光", story = "多洛莉絲的AVG裝甲，不可複製的奇跡，三位博士在裝甲上添加了諸多功能，她並未完全熟悉，但可以預見，完全適應這件AVG的多洛莉絲想必會成為人類的又一張“王牌”", attackname = "演出開幕了？", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11040", coordinate = "11040", generalattack = "0", midposition = "0,4.57", topposition = "0,8.89", bottomposition = "0,0", buffplacer = "68419_0", zjeffect = "68420_0", debut = "68418_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 31, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "57-jaw", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11040001] = {id = 11040001, name = "請在舞台上微笑", story = "僅一張幕布，把前來觀看表演的駕駛員隔絕在外，嘈雜朦朧的聲音在等待著多洛莉絲的演出，而她只想牽著你的手，再一次，再一次，在這只有你們的世界，直到世界的盡頭。", attackname = "演出開幕了？", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/11040001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11040001/WatchSpine/Watch_3D_front.prefab", interaction = "11040001", coordinate = "11040001", generalattack = "0", midposition = "0,4.57", topposition = "0,8.89", bottomposition = "0,0", buffplacer = "68419_0", zjeffect = "68420_0", debut = "68418_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 31, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "0", admission = "0", scale = "1,2", bgm = "57-jaw", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11040001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11040002] = {id = 11040002, name = "偶像，然後是兔女郎", story = "因爲博士的喜好而換上偶像服，如今又因爲領航的愛好而穿上兔女郎服裝，多洛莉絲對於自己接下來還可能穿上什麽古怪衣服這件事感到忐忑不安。", attackname = "演出開幕了？", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/11040002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11040002", coordinate = "11040002", generalattack = "0", midposition = "0,4.57", topposition = "0,8.89", bottomposition = "0,0", buffplacer = "68419_0", zjeffect = "68420_0", debut = "68418_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 31, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "0", admission = "0", scale = "1,2", bgm = "57-jaw", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4104000217;switch2,idle,4104000218", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11040002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11041] = {id = 11041, name = "憤恨的織女星", story = "織女星的專屬AVG裝甲，看着又野又颯，但是本質上還是一套爲劈砍與突進量身打造的實戰鬥士套裝。無論是誰看到這套裝甲，都會驚呼一句“感覺是很能打的一套裝備呢”。", attackname = "倒下吧！", painter = "/", voiceexcellence = "永木 さくら", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11041", coordinate = "11041", generalattack = "0", midposition = "0,4.67", topposition = "0,8.91", bottomposition = "0,0", buffplacer = "68426_0", zjeffect = "68427_0", debut = "68425_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "14_0.15_9_60_1.4_2.1_0.7,7_0.2_13_60_2.2_3_1.3,30_0.3_17_60_2.4_3.2_1.3,10_0.35_23_60_2_3.7_1.6", delay = "14_0.2,7_0.2,30_0.3,10_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11041001] = {id = 11041001, name = "指定區域注射師", story = "沒有多餘的客套，織女星就這麼直勾勾地看着領航，一雙腳掌牢牢夾着那支注射器，眼神彷彿不容置疑，而她準備的注射液，究竟會給領航帶來怎樣的後果，也沒人知道。", attackname = "倒下吧！", painter = "/", voiceexcellence = "永木 さくら", backgroundpic = "ABOriginal/Role/11041001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11041001/WatchSpine/Watch_3D_front.prefab", interaction = "11041001", coordinate = "11041001", generalattack = "0", midposition = "0,4.67", topposition = "0,8.91", bottomposition = "0,0", buffplacer = "68426_0", zjeffect = "68427_0", debut = "68425_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 19, bulletvelocity = "0", strike = "14_0.15_9_60_1.4_2.1_0.7,7_0.2_13_60_2.2_3_1.3,30_0.3_17_60_2.4_3.2_1.3,10_0.35_23_60_2_3.7_1.6", delay = "14_0.2,7_0.2,30_0.3,10_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4104100110;switch2,idle3,4104100111;switch3,idle,4104100112", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11041001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11042] = {id = 11042, name = "無畏前線！", story = "海蘿的AVG裝甲。輕便、靈活的裝甲詮釋著海蘿的簡約美學——至少她自己是這麼認為的。實際上是因為她在定制裝甲的時候，把所有可以分配的資源都投入到了拳套上。", attackname = "接招吧。", painter = "/", voiceexcellence = "渡辺千絢", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11042", coordinate = "11042", generalattack = "0", midposition = "0,4.59", topposition = "0,9.03", bottomposition = "0,0", buffplacer = "68435_0", zjeffect = "68436_0", debut = "68434_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "12_0.25_11_60_1.9_2.7_1,15_0.3_13_60_2.3_3.2_1.1,26_0.45_27_60_2.6_3.5_1.9", delay = "12_0.2,15_0.3,26_0.5", admission = "0", scale = "0.5,1.5", bgm = "summerdaily", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11042001] = {id = 11042001, name = "貓貓細雨", story = "在你為路邊的小貓咪擔心的時候，海蘿在擔心著你，她總是這樣，一直如此——腦中思考的事情永遠只有一項，也只能是一項。在迎來了你之後，海蘿的世界便圍繞著你開始轉起來了。", attackname = "吃我一拳。", painter = "/", voiceexcellence = "渡辺千絢", backgroundpic = "ABOriginal/Role/11042001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11042001/WatchSpine/Watch_3D_front.prefab", interaction = "11042001", coordinate = "11042001", generalattack = "0", midposition = "0,4.59", topposition = "0,9.03", bottomposition = "0,0", buffplacer = "68435_0", zjeffect = "68436_0", debut = "68434_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "12_0.25_11_60_1.9_2.7_1,15_0.3_13_60_2.3_3.2_1.1,26_0.45_27_60_2.6_3.5_1.9", delay = "12_0.2,15_0.3,26_0.5", admission = "0", scale = "1,2", bgm = "summerdaily", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11042001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11042002] = {id = 11042002, name = "烟囱裏的聖誕老人？", story = "海蘿似乎並不知道聖誕老人要從烟囱裏進屋的傳統。那麽爲什麽你會在烟囱裏發現她呢？\n“誒——原來那个不是門嗎？！”", attackname = "聖誕拳！", painter = "/", voiceexcellence = "渡辺千絢", backgroundpic = "ABOriginal/Role/11042002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11042002/WatchSpine/Watch_3D_front.prefab", interaction = "11042002", coordinate = "11042002", generalattack = "0", midposition = "0,4.59", topposition = "0,9.03", bottomposition = "0,0", buffplacer = "68435_0", zjeffect = "68436_0", debut = "68434_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 14, bulletvelocity = "0", strike = "12_0.25_11_60_1.9_2.7_1,15_0.3_13_60_2.3_3.2_1.1,26_0.45_27_60_2.6_3.5_1.9", delay = "12_0.2,15_0.3,26_0.5", admission = "0", scale = "1,2", bgm = "summerdaily", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4104200206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11042002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11043] = {id = 11043, name = "啟泉聖音", story = "米菈專屬的AVG裝甲，由多瑙支部和聖濯教會聯合開發。這套裝甲在外觀上的設計極盡繁雜，但無疑體現了聖濯教會主教的聖潔與優雅。", attackname = "且聽水吟", painter = "/", voiceexcellence = "桐村まり", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11043", coordinate = "11043", generalattack = "0", midposition = "0,4.73", topposition = "0,9.34", bottomposition = "0,0", buffplacer = "68444_0", zjeffect = "68445_0", debut = "68443_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "8_0.2_7_60_1.4_2_0.8,9_0.35_14_60_2.1_3_1.4,33_0.45_25_60_2.6_3.5_1.9", delay = "8_0.2,9_0.3,33_0.5", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11043001] = {id = 11043001, name = "熱意難耐", story = "在炎熱的季節穿上如此悶熱的服裝，米菈已在心中將聖濯教會的教義誦念了十幾遍，可還是散不去心頭的燥熱。但是在領航看到之前，她還不想換下這身服裝。實在難忍的話，只能寬解衣帶。悶蒸的熱氣，快些散去，快些散去……", attackname = "且聽水吟", painter = "/", voiceexcellence = "桐村まり", backgroundpic = "ABOriginal/Role/11043001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11043001", coordinate = "11043001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.34", bottomposition = "0,0", buffplacer = "68444_0", zjeffect = "68445_0", debut = "68443_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "8_0.2_7_60_1.4_2_0.8,9_0.35_14_60_2.1_3_1.4,33_0.45_25_60_2.6_3.5_1.9", delay = "8_0.2,9_0.3,33_0.5", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4143000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11044] = {id = 11044, name = "宵色綺想", story = "暫無", attackname = "以傷取色。", painter = "/", voiceexcellence = "里美こはる", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11044", coordinate = "11044", generalattack = "0", midposition = "0,4.81", topposition = "0,9.51", bottomposition = "0,0", buffplacer = "68461_0", zjeffect = "68462_0", debut = "68460_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 38, bulletvelocity = "0", strike = "25_0.6_49_60_2.3_3_1.7", delay = "25_1", admission = "0", scale = "0.5,1.5", bgm = "68-Puenred_EastEnd", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11045] = {id = 11045, name = "不穩定化合物", story = "吠黎爾的專屬AVG裝甲。不穩定的精神狀態使得她不被信任，只有用備受信賴的人類科技來約束她的行為，她才能被重用——能改變這一現狀的只有你，通感者。", attackname = "撕碎你！", painter = "/", voiceexcellence = "長島光那", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11045", coordinate = "11045", generalattack = "0", midposition = "0,4.53", topposition = "0,9.01", bottomposition = "0,0", buffplacer = "68490_0", zjeffect = "68491_0", debut = "68489_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "13_0.3_19_60_1.6_2.4_1,12_0.4_27_60_2.2_3_1.5", delay = "25_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11045001] = {id = 11045001, name = "亞特蘭蒂斯之獸", story = "在這危險的深海中，你遇見的究竟是一位等待著你救援的孤獨少女，抑或者——是一位覺得“與你溺死殉情也不錯”的怪獸。你無法分辨其中的危險，少女面無表情地望著你，靜靜地等待著你的抉擇。", attackname = "撕碎你！", painter = "/", voiceexcellence = "長島光那", backgroundpic = "ABOriginal/Role/11045001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11045001/WatchSpine/Watch_3D_front.prefab", interaction = "11045001", coordinate = "11045001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.01", bottomposition = "0,0", buffplacer = "68490_0", zjeffect = "68491_0", debut = "68489_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "13_0.3_19_60_1.6_2.4_1,12_0.4_27_60_2.2_3_1.5", delay = "25_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4145000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11046] = {id = 11046, name = "戀愛戰車", story = "佩佩塔專屬的AVG裝甲。由薩哈拉的教師們為其量身打造。在速度和重量上的表現非常優秀，很適合駕駛員新手使用。", attackname = "衝衝衝！", painter = "/", voiceexcellence = "長島光那", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11046", coordinate = "11046", generalattack = "0", midposition = "0,4.69", topposition = "0,9.2", bottomposition = "0,0", buffplacer = "68528_0", zjeffect = "68529_0", debut = "68527_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.1_5_60_1.5_2_0.7,5_0.15_8_60_1.9_2.4_1,18_0.35_17_60_2_3_1.4", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11046001] = {id = 11046001, name = "戀愛發生地其一", story = "根據《校園戀愛攻略》一書“第三章·約會地點”第四節所寫——泳池乃是戀愛高發地排名第三的地點。雖不及校門口的自然偶遇也不如天臺的飄蕩背影，但卻是展示自我最好的舞臺。合身的學校泳裝與濺起的晶瑩水滴，一定能助你牢牢俘獲領航的心。", attackname = "衝衝衝！", painter = "/", voiceexcellence = "長島光那", backgroundpic = "ABOriginal/Role/11046001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11046001/WatchSpine/Watch_3D_front.prefab", interaction = "11046001", coordinate = "11046001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.2", bottomposition = "0,0", buffplacer = "68528_0", zjeffect = "68529_0", debut = "68527_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.1_5_60_1.5_2_0.7,5_0.15_8_60_1.9_2.4_1,18_0.35_17_60_2_3_1.4", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4104600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11046001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11047] = {id = 11047, name = "電海幻漪", story = "蕩漾兔專屬AVG裝甲，完全復刻了其虛擬形象衣裝，其中所涵程序能將蕩漾兔的歌聲轉為特殊代碼，以駭入原罪，讓原罪也因她的歌聲陷入暈厥。", attackname = "兔寶寶們豎起耳朵哦！", painter = "/", voiceexcellence = "鷲見友美ジェナ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11047", coordinate = "11047", generalattack = "0", midposition = "0,4.63", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68485_0;68486_25", zjeffect = "68487_0", debut = "68484_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "101_0.4_26_60_2.4_3.1_1.6", delay = "105_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11047001] = {id = 11047001, name = "兔兔轉轉樂", story = "芳醺飄搖，情意蕩漾，霓虹光芒如星辰微顫，蹣跚的音符引你好奇來訪。兔耳少女醉倒近前，神秘轉盤高懸一旁，你不覺間陷入遐思，屬於自己的命定頭獎。", attackname = "會抽中什麼呢？", painter = "/", voiceexcellence = "鷲見友美ジェナ", backgroundpic = "ABOriginal/Role/11047001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11047001", coordinate = "11047001", generalattack = "0", midposition = "0,4.63", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68485_0;68486_25", zjeffect = "68487_0", debut = "68484_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "101_0.4_26_60_2.4_3.1_1.6", delay = "105_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4147000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11047001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11047002] = {id = 11047002, name = "兔進制幻夢空間", story = "小心在深夜發來的神秘連結，那精心偽裝的兔子洞入口。一旦掉入其中，便會被帶到另一個世界，由數位和代碼組成的幻夢空間。一不留神就卡死在無盡的兔子迴圈之中，無法逃脫。", attackname = "兔寶寶們豎起耳朵哦！", painter = "/", voiceexcellence = "鹫见友美ジェナ", backgroundpic = "ABOriginal/Role/11047002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11047002/WatchSpine/Watch_3D_front.prefab", interaction = "11047002", coordinate = "11047002", generalattack = "0", midposition = "0,4.63", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68485_0;68486_25", zjeffect = "68487_0", debut = "68484_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "101_0.4_26_60_2.4_3.1_1.6", delay = "105_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4104700206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11047002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11048] = {id = 11048, name = "盛夏不絕對", story = "莉莉絲的夏日泳裝，作為這次海濱樂園之行被強制要求陪伴在你身邊的駕駛員，莉莉絲一邊露出厭惡的表情，一邊牽起你的手。其實她本人還是很享受的。", attackname = "真是刺眼啊。", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/11048/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11048", coordinate = "11048", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68505_0;68506_40", zjeffect = "68507_0;68508_40", debut = "68504_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "74-actress", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11048001] = {id = 11048001, name = "陽光照耀的永遠夏日", story = "慵懶恣意地展現自己的美好，莉莉絲瞇起了眼睛，感受著海風吹過的溫熱，聆聽著盛夏的喧囂……還有你內心的誇讚聲。她本人為此感到有一點點得意。當然這點小情緒通過通感被你所察覺。", attackname = "呼，要小心海浪。", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/11048001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11048001", coordinate = "11048001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68505_0;68506_40", zjeffect = "68507_0;68508_40", debut = "68504_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "1,2", bgm = "74-actress", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4148000107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11048001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11049] = {id = 11049, name = "無名的怪物", story = "即使身份發生了轉變，阿爾泰婭也沒有更換服裝的打算。她依然穿著她學生時期的服飾，T恤上的文字更是表達了她對於這個世界最真摯的感想。", attackname = "救世主登場！！！", painter = "/", voiceexcellence = "長月あおい", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11049", coordinate = "11049", generalattack = "0", midposition = "0,4.65", topposition = "0,9.2", bottomposition = "0,0", buffplacer = "68547_0", zjeffect = "68548_0", debut = "68546_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.55", attackdistance = 15, bulletvelocity = "0", strike = "10_0.2_7_60_1.7_2.2_0.9,8_0.35_14_60_1.9_2.7_1.1", delay = "20_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11049001] = {id = 11049001, name = "蓄謀已久的突襲", story = "為了實現自己的目標，阿爾泰婭換上了自己辛苦攢錢購買的決勝服裝，並且邀請你在工作結束後來自己的臥室——但不知為何，她提前睡著了。", attackname = "救世主登場！！！", painter = "/", voiceexcellence = "長月あおい", backgroundpic = "ABOriginal/Role/11049001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11049001", coordinate = "11049001", generalattack = "0", midposition = "0,4.65", topposition = "0,9.2", bottomposition = "0,0", buffplacer = "68547_0", zjeffect = "68548_0", debut = "68546_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.55", attackdistance = 15, bulletvelocity = "0", strike = "10_0.2_7_60_1.7_2.2_0.9,8_0.35_14_60_1.9_2.7_1.1", delay = "20_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11049001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11049002] = {id = 11049002, name = "往日幻影", story = "她穿上不曾穿過的服飾，即使模樣一致，你也能明白她並非曾經的那個人。這是一種悼念，是一種懷念，但在這之後，她與你都需向前邁進。", attackname = "救世主登場！！！", painter = "/", voiceexcellence = "長月あおい", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "0", interaction = "11049002", coordinate = "11049002", generalattack = "0", midposition = "0,4.65", topposition = "0,9.2", bottomposition = "0,0", buffplacer = "68547_0", zjeffect = "68548_0", debut = "68546_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.55", attackdistance = 15, bulletvelocity = "0", strike = "10_0.2_7_60_1.7_2.2_0.9,8_0.35_14_60_1.9_2.7_1.1", delay = "20_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4149000206", dragrange = "1,1;1920,1080", isdrag = 1, jumpto = "5,11049002,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11050] = {id = 11050, name = "人之天使", story = "【天堂】的影子遮蓋身體，於光芒中成為【天使】。這最後階梯，是波琳娜早該踏出的一步，因為最極致的危險在若干年前她已經度過。有所不同的是過去的並非本意，而現今的卻有所求。為了拯救，波琳娜以人類之軀化身天使。", attackname = "不要亂動！", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11050", coordinate = "11050", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68572_0", zjeffect = "68573_0", debut = "68571_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "81-Angel", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11050001] = {id = 11050001, name = "冬日遊戲", story = "天使的必要條件是純潔無垢的心靈，即便化身巨人也保有一顆孩童的玩心。身為波琳娜的領航和監護者，在這冬日難得的晴空之下，巨人和人類，天使和凡人正在嬉戲玩鬧。即便會受傷的風險，但你們還是樂在其中。", attackname = "波琳娜抓到你了！", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "ABOriginal/Role/11050001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11050001", coordinate = "11050001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68572_0", zjeffect = "68573_0", debut = "68571_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "1,2", bgm = "81-Angel", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle1,4105000103,100;switch2,idle,4105000109,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11050001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11051] = {id = 11051, name = "小小小朱利乌斯", story = "朱利烏斯專屬的AVG裝甲。身體雖然變小，但頭腦仍靈活，高潔的騎士在惡劣的情況下依舊憑藉幼小的身軀抵御著原罪的入侵，保護大家的安全。因為實在是太擔心隊友們，朱利烏斯決定以“臨時”的身份暫時加入多瑙特別聯合部隊的戰鬥。", attackname = "到我身後！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11051", coordinate = "11051", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68591_0", zjeffect = "68592_0", debut = "68590_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "85-In_love", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11051001] = {id = 11051001, name = "朱利烏斯想不明白", story = "戀愛是逐漸滲透的感情，是那種在無數細微瞬間中，悄悄紮根於心底的溫柔。它可能是兩個人在夜晚安靜地分享一個秘密，可能是無言的理解，也可能是當世界變得冷酷時，唯一能為彼此提供溫暖的力量。所以——“戀愛究竟是什麼呢？”少女迷茫地想著。", attackname = "快點解決！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/11051001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11051001/WatchSpine/Watch_3D_front.prefab", interaction = "11051001", coordinate = "11051001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68591_0", zjeffect = "68592_0", debut = "68590_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "47_0.65_38_60_1.7_2.8_0.9", delay = "47_1", admission = "0", scale = "1,2", bgm = "85-In_love", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4105100108,100;switch2,idle,4105100114,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11051001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11052] = {id = 11052, name = "最後的希望", story = "斯珀丝专属的AVG装甲。穿上长靴，系上披风，拿起全村子最好的宝剑，孤独一人踏上冒险。\n目标“拯救世界”。\n斯珀丝会向世人证明——勇者之剑，是因为勇者，才被称作“勇者之剑”。", attackname = "大變身！", painter = "/", voiceexcellence = "逢来凛", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11052", coordinate = "11052", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68607_0", zjeffect = "68608_0", debut = "68606_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "87-Where_the_Road_Ends", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11052001] = {id = 11052001, name = "短程旅途", story = "拯救世界的冒险并非一蹴而就，适时地扎营休憩是不可或缺的环节。感受着营火的跃动，焰光轻吻在脸颊的温度。吃点烤肉，清点补给，擦拭武器，最后拿出乐器，弹奏一曲心灵的旋律，静待日升月落……", attackname = "勇者超變身！", painter = "/", voiceexcellence = "逢来凛", backgroundpic = "ABOriginal/Role/11052001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11052001", coordinate = "11052001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68607_0", zjeffect = "68608_0", debut = "68606_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "47_1", admission = "0", scale = "1,2", bgm = "87-Where_the_Road_Ends", shoptag = "0", ismorestate = 1, shopanim = "switch,idle2,4105200108,100;switch2,idle,4105200114,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11052001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11052002] = {id = 11052002, name = "舊時代的癖好", story = "“完全無法理解舊時代的人爲什麽會喜歡這種衣服！”出身在人類文明幾近滅絶的勇者斯珀絲，正陷入前所未有的困惑中。", attackname = "兔女郎形態！", painter = "/", voiceexcellence = "逢来凛", backgroundpic = "ABOriginal/Role/11052002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11052002/WatchSpine/Watch_3D_front.prefab", interaction = "11052002", coordinate = "11052002", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68607_0", zjeffect = "68608_0", debut = "68606_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "47_1", admission = "0", scale = "1,2", bgm = "87-Where_the_Road_Ends", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4105200213;switch2,idle,4105200214", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,11052002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11053] = {id = 11053, name = "魔災倖存者", story = "青羽的戰鬥服飾。雖說身上的肌膚被不知名的黑色皮膚所替代，但她仍然保留著穿衣的習慣。", attackname = "別打擾我！", painter = "/", voiceexcellence = "楠木ともり", backgroundpic = "ABOriginal/Role/11053/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11053", coordinate = "11053", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68607_0", zjeffect = "68608_0", debut = "68606_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "47_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11053001] = {id = 11053001, name = "為了“守護”的戰鬥", story = "以頭髮編制接住孩童的網，以光炮擊碎壓向群眾的建築。在擁有了這份力量之後，青羽第一次以它來踐行守護“人”的戰鬥。", attackname = "真煩啊！", painter = "/", voiceexcellence = "楠木ともり", backgroundpic = "ABOriginal/Role/11053001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11053001/WatchSpine/Watch_3D_front.prefab", interaction = "11053001", coordinate = "11053001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68607_0", zjeffect = "68608_0", debut = "68606_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "39_0.3_15_60_2.1_2.7_1.4,14_0.3_15_60_2.1_2.7_1.4,18_0.35_17_60_2.3_2.9_1.7,46_0.4_23_60_2.7_3.4_2", delay = "47_1", admission = "0", scale = "1,2", bgm = "38-Battle-island", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4105300107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11053001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11054] = {id = 11054, name = "天禦鳥命", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "天·禦·鳥·命", painter = "/", voiceexcellence = "內田真禮", backgroundpic = "ABOriginal/Role/11053/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11054", coordinate = "11054", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68635_0", zjeffect = "68636_0", debut = "68634_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.3_15_60_2.1_2.7_1.4,8_0.3_15_60_2.1_2.7_1.4,13_0.35_17_60_2.3_2.9_1.7,15_0.35_17_60_2.3_2.9_1.7", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11054001] = {id = 11054001, name = "夜襲時間", story = "對於擁有空間穿梭能力的出雲天花而言，所有重重阻攔禁止進入的秘密區域都只不是一次能力的發動而已。但顯然她對那些秘密區域都沒什麼興趣。", attackname = "一切都結束了！", painter = "/", voiceexcellence = "內田真禮", backgroundpic = "ABOriginal/Role/11054001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11054001/WatchSpine/Watch_3D_front.prefab", interaction = "11054001", coordinate = "11054001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68635_0", zjeffect = "68636_0", debut = "68634_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "7_0.3_15_60_2.1_2.7_1.4,8_0.3_15_60_2.1_2.7_1.4,13_0.35_17_60_2.3_2.9_1.7,15_0.35_17_60_2.3_2.9_1.7", delay = "0", admission = "0", scale = "1,2", bgm = "78-Romance", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4105400103,100;switch2,idle,4105400109,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11054001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
