[11056] = {id = 11056, name = "王之形態其五", story = "迅游於宇宙的流星，世界的中心高歌冒險之心。逃逸的藍色閃電，其名為斯卡蒂，斯卡蒂的未來形態之一。最擅長的事情是打架。最出名的事情是打架。最討厭的事情是打架。", attackname = "近身者，斬無赦！", painter = "/", voiceexcellence = "髙桥咲贵", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11056", coordinate = "11056", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68657_0", zjeffect = "68658_0", debut = "68656_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11056001] = {id = 11056001, name = "冷酷西瓜殺手", story = "即使蒙住眼睛也百發百中，若要問為什麼？會長早已在修行中掌握了【心眼】，如此對於環境和人的洞察都提高了極限。不過她也因此而困擾了一段時間，甚至到最後把【心眼】和【讀心】一起封印了。", attackname = "西瓜，斬！", painter = "/", voiceexcellence = "髙橋咲貴", backgroundpic = "ABOriginal/Role/11056001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11056001/WatchSpine/Watch_3D_front.prefab", interaction = "11056001", coordinate = "11056001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68657_0", zjeffect = "68658_0", debut = "68656_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "33-Empty_but_not_real", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4105600106", dragrange = "1,1;1920,1080", isdrag = 1, jumpto = "5,11056001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11057] = {id = 11057, name = "王之形態其六", story = "斯卡蔕的萬聖節裝扮。“領航又夢見了吾？哼哼……也許那就是眞實發生的事情也説不定哦……是由最強大的影之國魔女和最強大的眷屬完成的能逆轉時光的大魔法。”", attackname = "崇拜！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11057", coordinate = "11057", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68673_0", zjeffect = "68674_0", debut = "68672_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "37-island", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11057001] = {id = 11057001, name = "不給糖就變成章魚！", story = "“吾的眷屬，你想要偷偷到哪裡去？”，“一個人上廁所很孤單，和吾一起去。”，“那、那個不能吃，那是吾準備的魔、魔材料魚子醬。”，“領航！吾發現線索了，走吧！”在這世紀末，這樣的事情每天都會發生。", attackname = "污染！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/11057001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11057001/WatchSpine/Watch_3D_front.prefab", interaction = "11057001", coordinate = "11057001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68673_0", zjeffect = "68674_0", debut = "68672_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "37-island", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4105700111", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60002,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11058] = {id = 11058, name = "被動型夢想症患者", story = "米夏專屬的AVG裝甲。原本是第一研究室中的試驗型裝備，被赫洛卡帶出並最後交給米夏使用。據說設計師是根據自身平時的穿著進行設計。", attackname = "哇啊啊啊~", painter = "/", voiceexcellence = "空賀花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "11058", coordinate = "11058", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68679_0", zjeffect = "68680_0", debut = "68678_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "101-Tearless", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11058001] = {id = 11058001, name = "封閉式衣櫃療法", story = "衣櫃是處神奇的空間，布料和木頭的氣味可以安撫悸動的心靈。即便還有些許不安，那順著縫隙溜進來的光也能輕鬆撫平。沉浸在領航衣櫃舒心氛圍中的米夏全然忘記了剛才的慌亂，也忘記了自己拜訪領航的目的。", attackname = "不想出去……", painter = "/", voiceexcellence = "空賀花", backgroundpic = "ABOriginal/Role/11058001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11058001/WatchSpine/Watch_3D_front.prefab", interaction = "11058001", coordinate = "11058001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68679_0", zjeffect = "68680_0", debut = "68678_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "101-Tearless", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4105800109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11058001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
