[11061001] = {id = 11061001, name = "溶入夜色的一杯", story = "“我可是堂堂二番組的組長，居然讓我擺出這種姿勢……眞是不可饒恕！”\n生氣時的上運天美羅，依然在堅持著自己身爲魔防隊組長的威嚴。", attackname = "歐拉！", painter = "/", voiceexcellence = "菲魯茲·藍", backgroundpic = "ABOriginal/Role/11061001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11061001", coordinate = "11061001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68690_0", zjeffect = "68691_0", debut = "68689_0", ready = "68692_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "78-Romance", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4106100113;switch2,idle,4106100114", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,11061001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[11062] = {id = 11062, name = "印象轉變大作戰", story = "朱利烏斯參考多方意見後定下的出行打扮。方便活動，透氣性良好，以及最重要的——充滿日常感！完美適配作戰計畫！", attackname = "全壘打！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/11062/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "11062", coordinate = "11062", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68720_0", zjeffect = "68721_0", debut = "68719_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "111_Sunshine_cloud", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[11062001] = {id = 11062001, name = "騎士小姐（暫時休業！）", story = "在突發狀況與偶遇熟人的雙重作用下，朱利烏斯的大腦陷入了短暫的宕機。基於她自己都不明白的衝動，她做出了前所未有的大膽行爲。", attackname = "全壘打！", painter = "/", voiceexcellence = "南槻ひかる", backgroundpic = "ABOriginal/Role/11062001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/11062001/WatchSpine/Watch_3D_front.prefab", interaction = "11062001", coordinate = "11062001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68720_0", zjeffect = "68721_0", debut = "68719_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_1_56_60_1.9_2.7_1.1", delay = "0", admission = "0", scale = "1,2", bgm = "111_Sunshine_cloud", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4106200115;switch2,idle3,4106200116;switch3,idle4,4106200117;switch4,idle,4106200118", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60005,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12000] = {id = 12000, name = "錢可百解", story = "金庫啦專屬的AVG裝甲。由艾吉斯總部為金庫啦定制。雖然看似和其他裝甲相同，實際上使用了昂貴的材料作為基底，造價是普通裝甲的好幾倍。不過對於金庫啦來說，可以用錢解決的問題從來不是問題。", attackname = "火力全開！", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12000", coordinate = "12000", generalattack = "0", midposition = "0.3,3", topposition = "0.69,6.22", bottomposition = "0,0", buffplacer = "68012_0;68013_0;68179_0", zjeffect = "0", debut = "68014_0", ready = "68036_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.45,0.2,0.2", strike = "21_0.4_10_60_1.2_2.4_0.5,10_1_18_60_2.8_1.5_0.4", delay = "21_0.3,10_0.7", admission = "200,120,1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12000001] = {id = 12000001, name = "乐园闲暇时光", story = "哦吼吼~買下領航的一天需要多少錢？請仔細衡量自己的價值吧。因為我決定一口氣買下領航100年的時間。這是最公平的等價交換。就先從今天開始吧。", attackname = "火力全開！", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "ABOriginal/Role/12000001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12000001/WatchSpine/Watch_3D_front.prefab", interaction = "12000001", coordinate = "12000001", generalattack = "0", midposition = "0.3,3", topposition = "0.69,6.22", bottomposition = "0,0", buffplacer = "68012_0;68013_0;68179_0", zjeffect = "0", debut = "68014_0", ready = "68036_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.45,0.2,0.2", strike = "21_0.4_10_60_1.2_2.4_0.5,10_1_18_60_2.8_1.5_0.4", delay = "21_0.3,10_0.7", admission = "200,120,1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12000001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12001] = {id = 12001, name = "吊車尾", story = "靜的AVG裝甲，由克雷蒂婭家設計製造而成，以最少的品質達到了最強的防禦性能。但靜還是經常以裝甲太重為理由推脫任務。", attackname = "該休息了……", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12001", coordinate = "12001", generalattack = "0", midposition = "0,3.4", topposition = "0,6.73", bottomposition = "0,0", buffplacer = "68346_0;68347_30", zjeffect = "0", debut = "68348_0", ready = "68345_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.65,0.4,0.4", strike = "55_0.95_48_60_3_3.4_2.8", delay = "55_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12001001] = {id = 12001001, name = "靜謐的喚星者", story = "遙遠時空的某個世界中，存在著一位大魔法師——靜。她掌握著至高的星空魔法，被其他冒險家們尊稱為“靜謐的喚星者”。因此她得以遊歷於群星之間，尋找那些古老星球的秘密。", attackname = "該休息了……", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "ABOriginal/Role/12001001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12001001/WatchSpine/Watch_3D_front.prefab", interaction = "12001001", coordinate = "12001001", generalattack = "0", midposition = "0,3.4", topposition = "0,6.73", bottomposition = "0,0", buffplacer = "68346_0;68347_30", zjeffect = "0", debut = "68348_0", ready = "68345_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.65,0.4,0.4", strike = "55_0.95_48_60_3_3.4_2.8", delay = "55_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level3,idle,4200100107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12001001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12002] = {id = 12002, name = "侵略如火", story = "不知火的AVG裝甲。具備著優秀狙擊能力的她，配備巨弓後擁有在千里之外輕易狙殺原罪的支援能力。", attackname = "歸途之箭。", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12002", coordinate = "12002", generalattack = "0", midposition = "0.42,3.42", topposition = "0.09,7.3", bottomposition = "0,0", buffplacer = "68044_0;68174_18,68045_0;68175_33,68045_0;68176_48,68048_0", zjeffect = "0", debut = "68041_0", ready = "68042_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.6,0.17,0.17", strike = "28_0.3_14_60_2.2_2.4_0.6,13_0.3_14_60_2_2.8_0.8,13_0.3_15_60_2.5_2.9_1.2", delay = "29_0.3,13_0.3,13_0.4", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12002001] = {id = 12002001, name = "百尺大人", story = "近日在九州的一個寧靜村莊，冒出了一連串關於「百尺大人」的神秘傳聞。然而事實上，所謂「百尺大人」不過是與領航同行、身著潔白洋裝的巨大不知火罷了。", attackname = "歸途之箭。", painter = "/", voiceexcellence = "坂井愛実", backgroundpic = "ABOriginal/Role/12002001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12002001/WatchSpine/Watch_3D_front.prefab", interaction = "12002001", coordinate = "12002001", generalattack = "0", midposition = "0.42,3.42", topposition = "0.09,7.3", bottomposition = "0,0", buffplacer = "68044_0;68174_18,68045_0;68175_33,68045_0;68176_48,68048_0", zjeffect = "0", debut = "68041_0", ready = "68042_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.6,0.17,0.17", strike = "28_0.3_14_60_2.2_2.4_0.6,13_0.3_14_60_2_2.8_0.8,13_0.3_15_60_2.5_2.9_1.2", delay = "29_0.3,13_0.3,13_0.4", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4200200106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12002001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12003] = {id = 12003, name = "鋼鐵洪流", story = "專門為葉芙根尼婭量身定做的重火力型裝備，擁有一般AVG裝甲無法比肩的強大火力。如此強大的火力往往會給城市帶來二次破壞，因此鮮有她登場的機會。", attackname = "全彈發射！Fire！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12003", coordinate = "12003", generalattack = "0", midposition = "0.3,4.15", topposition = "0.3,7.4", bottomposition = "0,0", buffplacer = "68050_0;68051_26,68055_0;68052_36,68055_0;68053_49,68055_0;68054_59,68055_0", zjeffect = "68056_0", debut = "68049_0", ready = "68063_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.7,0.5,0.5", strike = "40_0.2_12_60_1.4_2_0.6,8_0.2_12_60_1.6_2.2_0.4,9_0.2_14_60_2_2.4_0.6,8_0.2_15_60_2.2_2.8_1.2", delay = "40_0.2,8_0.2,9_0.3,8_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12003001] = {id = 12003001, name = "湖畔小憩", story = "在林間晨跑，回神時朝陽已經升起。大汗淋漓的她所需的是一場暢快淋漓的洗浴。巧的是此處正有湖畔——更巧的是你也途經此處，領航。", attackname = "全彈發射！Fire！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "ABOriginal/Role/12003001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12003001/WatchSpine/Watch_3D_front.prefab", interaction = "12003001", coordinate = "12003001", generalattack = "0", midposition = "0.3,4.15", topposition = "0.3,7.4", bottomposition = "0,0", buffplacer = "68050_0;68051_26,68055_0;68052_36,68055_0;68053_49,68055_0;68054_59,68055_0", zjeffect = "68056_0", debut = "68049_0", ready = "68063_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.7,0.5,0.5", strike = "40_0.2_12_60_1.4_2_0.6,8_0.2_12_60_1.6_2.2_0.4,9_0.2_14_60_2_2.4_0.6,8_0.2_15_60_2.2_2.8_1.2", delay = "40_0.2,8_0.2,9_0.3,8_0.3", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4200300106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12004] = {id = 12004, name = "彼岸巫女", story = "花語的專屬AVG裝甲，結合了心經屋的巫女服，以及戰機的噴射動力裝置。為了配合花語的弓術而將上半身服裝改進得更加貼合，以模擬她平時弓道訓練時的感覺。", attackname = "邪穢清除！", painter = "/", voiceexcellence = "中澤ミナ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12004", coordinate = "12004", generalattack = "0", midposition = "0.09,3.58", topposition = "0.25,7.52", bottomposition = "0,0", buffplacer = "68059_0;68060_48,68061_0", zjeffect = "0", debut = "68057_0", ready = "68058_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.4,0.3,0.3", strike = "58_0.6_20_60_1.6_2.6_0.8", delay = "58_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12004001] = {id = 12004001, name = "巧克力的花語", story = "巧克力花的種植步驟。一，去商店購買巧克力花的種子；二，將種子種在碗狀容器中，用沸水隔碗催熟；三，將催熟的種子移植到模具中等待冷卻。最後一個問題，你想知道巧克力花的花語嗎？", attackname = "邪穢清除！", painter = "/", voiceexcellence = "中澤ミナ", backgroundpic = "ABOriginal/Role/12004001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12004001/WatchSpine/Watch_3D_front.prefab", interaction = "12004001", coordinate = "12004001", generalattack = "0", midposition = "0.09,3.58", topposition = "0.25,7.52", bottomposition = "0,0", buffplacer = "68059_0;68060_48,68061_0", zjeffect = "0", debut = "68057_0", ready = "68058_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.4,0.3,0.3", strike = "58_0.6_20_60_1.6_2.6_0.8", delay = "58_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4200400106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12004001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
