[12007] = {id = 12007, name = "八卦承命", story = "華夢專屬的AVG裝備，由九州總部特研科研制。這套AVG的研發重點在於武器，采用了較為激進的輸出曲線以適應華夢的戰鬥習慣。但對於“武癡”而言，最好的武器永遠是自己的拳頭。", attackname = "穩定呼吸——", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12007", coordinate = "12007", generalattack = "0", midposition = "-0.2,3.04", topposition = "-0.4,6.33", bottomposition = "0,0", buffplacer = "68100_0;68101_0", zjeffect = "0", debut = "68099_0", ready = "68102_0;68103_0;68104_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 22, bulletvelocity = "0", strike = "44_0.8_85_60_1.6_2.4_0.6", delay = "44_0.2,2_0.2,2_0.2,2_0.2,2_0.2", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12007001] = {id = 12007001, name = "喵嗚形意拳", story = "不僅在動作上模仿貓，還必須全身心地成為貓，這是記載在秘籍中，修煉形意拳的唯一方法。於是領航的家中暫時性地多了一只名為“華夢”的貓咪。\n“貓砂盆！有必要模仿到這種程度嗎……”", attackname = "喵喵拳！", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "ABOriginal/Role/12007001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12007001", coordinate = "12007001", generalattack = "0", midposition = "-0.2,3.04", topposition = "-0.4,6.33", bottomposition = "0,0", buffplacer = "68100_0;68101_0", zjeffect = "0", debut = "68099_0", ready = "68102_0;68103_0;68104_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 22, bulletvelocity = "0", strike = "44_0.8_85_60_1.6_2.4_0.6", delay = "44_0.2,2_0.2,2_0.2,2_0.2,2_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4200700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12007001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12008] = {id = 12008, name = "狂想海兔", story = "百里默默的專屬AVG裝甲，別看她本人平時軟乎乎的沒什麼壓迫感，但自身的裝備卻是破壞力拉滿的重裝攻堅套裝。巨型機械拳套砸下去可不是鬧着玩的。", attackname = "姐姐們！看到了嗎？", painter = "/", voiceexcellence = "夜道雪", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12008", coordinate = "12008", generalattack = "0", midposition = "0.47,2.51", topposition = "0.9,5.95", bottomposition = "0,0", buffplacer = "68163_0", zjeffect = "68173_0", debut = "68161_0", ready = "68162_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "20_0.4_20_60_1_2_0", delay = "20_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12008001] = {id = 12008001, name = "枕邊執勤", story = "百里默默晃着注射器，歪頭衝領航笑得眉眼彎彎，開心到連制服也穿得沒了嚴肅模樣。哪怕她做好了治療的架勢，卻偏要擺出一副捉弄人的姿態——或許，她正準備靠着自己的驚喜把領航逗得不知所措。", attackname = "姐姐們！看到了嗎？", painter = "/", voiceexcellence = "夜道雪", backgroundpic = "ABOriginal/Role/12008001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12008001/WatchSpine/Watch_3D_front.prefab", interaction = "12008001", coordinate = "12008001", generalattack = "0", midposition = "0.47,2.51", topposition = "0.9,5.95", bottomposition = "0,0", buffplacer = "68163_0", zjeffect = "68173_0", debut = "68161_0", ready = "68162_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 20, bulletvelocity = "0", strike = "20_0.4_20_60_1_2_0", delay = "20_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4200800106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12008001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12009] = {id = 12009, name = "寒霜之拥", story = "玛利亚专属的AVG装甲。由卡佳支部委托“塞伦”公司制作研发制作的特化装备。但除了能提供标准等级的驾驶员防护外，并没有发现有任何特殊之处。", attackname = "請冷靜一下！", painter = "/", voiceexcellence = "田中理恵", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12009", coordinate = "12009", generalattack = "0", midposition = "0.31,3.79", topposition = "0.31,7.45", bottomposition = "0,0", buffplacer = "68150_0;68151_39,68152_0", zjeffect = "68153_0", debut = "68263_0", ready = "68149_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.1,0.3,0.3", strike = "46_0.4_16_60_0.8_3_0.2", delay = "46_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12009001] = {id = 12009001, name = "賽後洗澡時間", story = "比賽已經結束，觀眾的歡呼漸漸遠去，騎士胯下的駿馬也該到休息時間。抹淨窗上的斑點，再沖去輪轂間的污泥，溫熱的引擎似乎還沉浸在沖線奪冠時的激動之中。但在此刻，請放下矜持，享受這短暫的共浴時刻。", attackname = "請冷靜一下！", painter = "/", voiceexcellence = "田中理恵", backgroundpic = "ABOriginal/Role/12009001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12009001/WatchSpine/Watch_3D_front.prefab", interaction = "12009001", coordinate = "12009001", generalattack = "0", midposition = "0.31,3.79", topposition = "0.31,7.45", bottomposition = "0,0", buffplacer = "68150_0;68151_39,68152_0", zjeffect = "68153_0", debut = "68263_0", ready = "68149_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.1,0.3,0.3", strike = "46_0.4_16_60_0.8_3_0.2", delay = "46_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12009001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12010] = {id = 12010, name = "無極之火", story = "冥火專屬的AVG裝甲，巨大的炮筒顯得有些沉重，但一旦進入交戰狀態，冥火便會如圖穿梭於硝煙裏的紫電魅影，用火力撕裂所有阻礙。", attackname = "哦？輪到我了嗎？", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12010", coordinate = "12010", generalattack = "0", midposition = "0.09,3.26", topposition = "0,6.65", bottomposition = "0,0", buffplacer = "68206_0;68207_27", zjeffect = "0", debut = "68204_0", ready = "68205_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "27_2_40_60_0.4_0.8_0.2", delay = "27_0.2,2_0.2,2_0.2,2_0.2,2_0.2", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12010001] = {id = 12010001, name = "窗邊的白衣使者", story = "推開病房的門，便能看見冥火安靜倚坐在窗邊。她的目光直直地望向你，身旁的推車似乎說明她早已將一切準備妥當。她到底準備了怎樣的治療方案，或者說……充滿歡愉的體驗？", attackname = "哦？輪到我了嗎？", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "ABOriginal/Role/12010001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12010001/WatchSpine/Watch_3D_front.prefab", interaction = "12010001", coordinate = "12010001", generalattack = "0", midposition = "0.09,3.26", topposition = "0,6.65", bottomposition = "0,0", buffplacer = "68206_0;68207_27", zjeffect = "0", debut = "68204_0", ready = "68205_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "27_2_40_60_0.4_0.8_0.2", delay = "27_0.2,2_0.2,2_0.2,2_0.2,2_0.2", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4201000110;switch2,idle3,4201000111;switch3,idle,4201000112", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12010001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12011] = {id = 12011, name = "听风行舟", story = "伽藍見專屬的AVG裝甲。極端依賴水環境的AVG裝甲，在陸地上幾乎提供不了戰鬥幫助。在海上的生活經歷使伽藍見在水中的統治力遠超一般駕駛員，再加上水戰特化AVG裝甲，使其在水中幾乎沒有敵手。", attackname = "傾瀉態火力已部署", painter = "/", voiceexcellence = "長縄まりあ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12011", coordinate = "12011", generalattack = "0", midposition = "0.31,3.9", topposition = "0.31,7.69", bottomposition = "0,0", buffplacer = "60012_0;60013_27,60014_0", zjeffect = "60015_0;60016_50", debut = "60011_0", ready = "60010_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.9,0.4,0.4", strike = "45_0.4_8_60_2_1.5_0.5", delay = "46_1", admission = "25,10,0.3,1", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12011001] = {id = 12011001, name = "且聽海風起時", story = "海風帶來了氣味，裹挾著層層包裹的故事來到了伽藍見的身邊。它們是這樣說的：此時的此刻，你的心上人將要來到。於是少女回頭望去，見到了來造訪的你。", attackname = "傾瀉態火力已部署", painter = "/", voiceexcellence = "長縄まりあ", backgroundpic = "ABOriginal/Role/12011001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12011001/WatchSpine/Watch_3D_front.prefab", interaction = "12011001", coordinate = "12011001", generalattack = "0", midposition = "0.31,3.9", topposition = "0.31,7.69", bottomposition = "0,0", buffplacer = "60012_0;60013_27,60014_0", zjeffect = "60015_0;60016_50", debut = "60011_0", ready = "60010_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.9,0.4,0.4", strike = "45_0.4_8_60_2_1.5_0.5", delay = "46_1", admission = "25,10,0.3,1", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4201100108", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12011001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12011002] = {id = 12011002, name = "夏空下的小小海洋", story = "“對不曾去過其他地方的金魚來說，和同類們擠擠攘攘的那個小池子，是否就是海洋呢？”\n水藍色的少女對著手中的袋子沉思著。右瞳倒映著夏空中綻放的煙火，左瞳倒映著你。", attackname = "傾瀉態火力已部署", painter = "/", voiceexcellence = "長縄まりあ", backgroundpic = "ABOriginal/Role/12011002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12011002/WatchSpine/Watch_3D_front.prefab", interaction = "12011002", coordinate = "12011002", generalattack = "0", midposition = "0.31,3.9", topposition = "0.31,7.69", bottomposition = "0,0", buffplacer = "60012_0;60013_27,60014_0", zjeffect = "60015_0;60016_50", debut = "60011_0", ready = "60010_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0.9,0.4,0.4", strike = "45_0.4_8_60_2_1.5_0.5", delay = "46_1", admission = "25,10,0.3,1", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "限时上架", ismorestate = 0, shopanim = "touch1,idle,4201100208", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12011002,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
