[12013] = {id = 12013, name = "白蓮的過客", story = "卡蓮的AVG裝備，是薩哈拉支部所屬學院的制式武裝。即使是制式裝備但對於卡蓮來說也完全夠用了。即使是落後的裝備面對原罪也不能後退，這是實習駕駛員最重要的一課。", attackname = "沒有人會在戰場死去！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12013", coordinate = "12013", generalattack = "0", midposition = "0.2,3.85", topposition = "0,7.68", bottomposition = "0,0", buffplacer = "68249_0;68251_10;68250_13", zjeffect = "68246_0;68247_15", debut = "68245_0", ready = "68248_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "13_0.4_30_60_0.5_2.5_0.5,34_0.4_50_60_3_2.5_1.5", delay = "13_0.3,34_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12013001] = {id = 12013001, name = "“索貝克”再再度來襲！", story = "在蒼穹學院獨有的周年慶典中，卡蓮所在的班級決定表演駕駛員與原罪戰鬥的舞臺劇。而作為班中與原罪戰鬥經驗最豐富的班長卡蓮，以幾乎全票當選了“索貝克”一角。唯一投反對票的人正是卡蓮自己。", attackname = "沒有人會在戰場死去！", painter = "/", voiceexcellence = "貝阿彌沙羅", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_front.prefab", interaction = "12013001", coordinate = "12013001", generalattack = "0", midposition = "0.2,3.85", topposition = "0,7.68", bottomposition = "0,0", buffplacer = "68249_0;68251_10;68250_13", zjeffect = "68246_0;68247_15", debut = "68245_0", ready = "68248_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "13_0.4_30_60_0.5_2.5_0.5,34_0.4_50_60_3_2.5_1.5", delay = "13_0.3,34_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4201300106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "5,12013001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
