[12015] = {id = 12015, name = "多瑙之花", story = "薇絲帕爾專屬的AVG裝甲。由多瑙支部為第一親衛班打造。採用了大量的柔性金屬，抗打擊性能極強的同時也保證了舒適度。這套裝甲也可以說是代表了多瑙新派貴族。", attackname = "今天，我們將書寫傳奇！", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12015", coordinate = "12015", generalattack = "0", midposition = "-0.1,4.05", topposition = "-0.1,7.68", bottomposition = "0,0", buffplacer = "68288_0;68289_65", zjeffect = "68290_0;68291_38", debut = "68287_0", ready = "68325_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "38_0.3_15_60_1.7_2.6_0.8,35_0.8_40_60_1.2_1.6_0.8", delay = "20_0.3,35_0.7", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12015001] = {id = 12015001, name = "蔚藍海灘的紅寶石", story = "多瑙河畔的寶石隨流水漂蕩到海邊，蔚藍色的海面上的紅色浪花，在陽光的照耀下熠熠生輝。", attackname = "今天，我們將書寫傳奇！", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "ABOriginal/Role/12015001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12015001/WatchSpine/Watch_3D_front.prefab", interaction = "12015001", coordinate = "12015001", generalattack = "0", midposition = "-0.1,4.05", topposition = "-0.1,7.68", bottomposition = "0,0", buffplacer = "68288_0;68289_65", zjeffect = "68290_0;68291_38", debut = "68287_0", ready = "68325_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "38_0.3_15_60_1.7_2.6_0.8,35_0.8_40_60_1.2_1.6_0.8", delay = "20_0.3,35_0.7", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4201500106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12015001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12016] = {id = 12016, name = "調音師", story = "薩拉蒂的AVG裝甲。由九州總部研發，外形上參考了薩拉蒂在樂隊中慣用的設備。這樣導致了薩拉蒂經常分不清戰場和演唱會，從而陷入忘我的演奏中。", attackname = "跟上節拍！盡情狂歡吧！", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12016", coordinate = "12016", generalattack = "0", midposition = "0.3,3.9", topposition = "0.1,8.76", bottomposition = "0,0", buffplacer = "68319_0;68320_56", zjeffect = "0", debut = "68318_0", ready = "68317_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "60_0.5_25_60_1_1.4_0.6", delay = "60_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12016001] = {id = 12016001, name = "夢想燃燒", story = "比賽結束，觀眾離場，偌大的賽道上僅剩薩拉蒂與你二人。這是獨屬於你們的閒暇時刻，在奪冠瞬間的興奮褪去之後，疲憊來襲得比以往更加洶湧。但賽車引擎仍未熄火，薩拉蒂的賽車夢也還未燃盡。", attackname = "再度狂歡！", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "ABOriginal/Role/12016001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12016001/WatchSpine/Watch_3D_front.prefab", interaction = "12016001", coordinate = "12016001", generalattack = "0", midposition = "0.3,3.9", topposition = "0.1,8.76", bottomposition = "0,0", buffplacer = "68319_0;68320_56", zjeffect = "0", debut = "68318_0", ready = "68317_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "60_0.5_25_60_1_1.4_0.6", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch2,idle,4201600110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12016001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12017] = {id = 12017, name = "陽光！沙灘！鈴！", story = "鈴的第二套泳裝，她似乎在期待著什麼。\n夏日能量快要消耗殆盡了！本天才要抓緊機會開始前進了！就用這件衣服！靈活地一決勝負吧！", attackname = "一擊必殺！", painter = "/", voiceexcellence = "Machico", backgroundpic = "ABOriginal/Role/12017/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12017", coordinate = "12017", generalattack = "0", midposition = "0,3.67", topposition = "0,7.86", bottomposition = "0,0", buffplacer = "68004_0", zjeffect = "68005_0", debut = "60017_0", ready = "68003_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "60018_0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "13_0.15_12_60_1_1.5_0.5,9_0.15_12_60_1.5_2_0.8,15_0.35_22_60_2.2_3_1.7,17_0.35_24_60_1.8_2.9_1", delay = "13_0.2,9_0.2,15_0.3,17_0.3", admission = "0", scale = "0.5,1.5", bgm = "29-another_summer", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12017001] = {id = 12017001, name = "浪花敘事詩", story = "超天才的泳裝，她似乎在等待著什麼。\n哼哼~最後還是靠著超天才的戰術才能取得勝利！所以一定要等我啊，領航，我會去找你！我可是超天才啊，一定一定會找到辦法的！", attackname = "一擊必殺！", painter = "/", voiceexcellence = "Machico", backgroundpic = "ABOriginal/Role/12017001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12017001/WatchSpine/Watch_3D_front.prefab", interaction = "12017001", coordinate = "12017001", generalattack = "0", midposition = "0,3.67", topposition = "0,7.86", bottomposition = "0,0", buffplacer = "68004_0", zjeffect = "68005_0", debut = "60017_0", ready = "68003_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "60018_0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "13_0.15_12_60_1_1.5_0.5,9_0.15_12_60_1.5_2_0.8,15_0.35_22_60_2.2_3_1.7,17_0.35_24_60_1.8_2.9_1", delay = "13_0.2,9_0.2,15_0.3,17_0.3", admission = "0", scale = "1,2", bgm = "29-another_summer", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12017001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12018] = {id = 12018, name = "巨構Dream", story = "希夏專屬的AVG裝甲，根據其日常的穿著設計而成。整體的設計沒有過多考慮戰鬥的實用性，而是更著重於結構和線條的審美。", attackname = "光橋射線！", painter = "/", voiceexcellence = "河実里夏", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12018", coordinate = "12018", generalattack = "0", midposition = "0,4.63", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68472_0", zjeffect = "68473_0", debut = "68471_0", ready = "68474_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 26, bulletvelocity = "0", strike = "25_1_62_60_2.3_3_1.9", delay = "25_1", admission = "0", scale = "0.5,1.5", bgm = "66-Newbridge", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12018001] = {id = 12018001, name = "睡前蜜語", story = "不要入睡，不要入睡，你是否注意到空氣中的曖昧。想不想瞭解我的一切？我的現在，我的過去、我的夢想，我的摒棄、我的愛好，我的厭惡、我的快樂，我的痛苦、我的執著，我的迷茫……以及我的愛，給你。", attackname = "光橋射線！", painter = "/", voiceexcellence = "河実里夏", backgroundpic = "ABOriginal/Role/12018001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12018001", coordinate = "12018001", generalattack = "0", midposition = "0,4.63", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68472_0", zjeffect = "68473_0", debut = "68471_0", ready = "68474_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 26, bulletvelocity = "0", strike = "25_1_62_60_2.3_3_1.9", delay = "25_1", admission = "0", scale = "1,2", bgm = "66-Newbridge", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12018001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12019] = {id = 12019, name = "荒城的守望者", story = "凱特琳專屬的AVG裝甲，由奧德賽重工負責研發製作。奧德賽重工的開發理念是，在為駕駛員提供足夠安全保障的同時也要展現出獨屬於小隊自身的風采。而凱特琳本身正是奧德賽所希望的小隊形象的實在體現——冷峻且高效。", attackname = "調整呼吸~", painter = "/", voiceexcellence = "鷲見友美ジェナ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12019", coordinate = "12019", generalattack = "0", midposition = "0,4.66", topposition = "0,9.14", bottomposition = "0,0", buffplacer = "68493_0;68494_0", zjeffect = "68495_0", debut = "68492_0", ready = "68496_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "40_0.45_32_60_2.2_3.1_1.7", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12019001] = {id = 12019001, name = "突擊！搜查官", story = "“站住！不許動！”被厲聲喝止後，眼前的搜查官卻將雙手背到身後，示意你將她拷起。原來這是一場身臨其境的教學遊戲，你正在向凱特琳學習搜查官的行事手段。不過看著她逐漸發燙的臉頰，你察覺到這場教學中蘊似乎含了一絲不易發現的曖昧深意。", attackname = "調整呼吸~", painter = "/", voiceexcellence = "鷲見友美ジェナ", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "0", interaction = "12019001", coordinate = "12019001", generalattack = "0", midposition = "0,4.66", topposition = "0,9.14", bottomposition = "0,0", buffplacer = "68493_0;68494_0", zjeffect = "68495_0", debut = "68492_0", ready = "68496_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "40_0.45_32_60_2.2_3.1_1.7", delay = "40_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "leve,idle,4201900106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12019001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12019002] = {id = 12019002, name = "暫熄的轟鳴", story = "以兜風的名義被哄騙而來，說是被哄騙實則也是滿足自己的好奇心。但你仍然感到困惑，在那墨鏡掩蓋的雙眼中，你們這是在休息還是說幽會？抑或只是在等待引擎的再一次轟鳴？", attackname = "调整呼吸~", painter = "/", voiceexcellence = "鹫见友美ジェナ", backgroundpic = "ABOriginal/Role/12019002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12019002/WatchSpine/Watch_3D_front.prefab", interaction = "12019002", coordinate = "12019002", generalattack = "0", midposition = "0,4.66", topposition = "0,9.14", bottomposition = "0,0", buffplacer = "68493_0;68494_0", zjeffect = "68495_0", debut = "68492_0", ready = "68496_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "40_0.45_32_60_2.2_3.1_1.7", delay = "40_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch_1,idle2,4201900209,100;switch_2,idle3,4201900210,100;switch_3,idle,4201900211,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12019002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12020] = {id = 12020, name = "星際冒險家", story = "弗洛維拉專屬的AVG裝甲，使用米狄爾科技製造而成。米狄爾人擅長的精神感應被弗洛維拉運用到了極致，而其中的關鍵就在於這套用特殊合金和米狄爾精神水晶製造的裝備。", attackname = "要發射啦！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12020", coordinate = "12020", generalattack = "0", midposition = "0,4", topposition = "0,7.85", bottomposition = "0,0", buffplacer = "68112_0;68113_75", zjeffect = "68114_0;68115_50", debut = "68111_0", ready = "68116_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "68117_0", "0", "0", qzoom = "0.4", attackdistance = 22, bulletvelocity = "0", strike = "78_0.85_52_60_1.8_2.5_1.2", delay = "80_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12020001] = {id = 12020001, name = "指間的星星", story = "煙花燦爛絢麗，就像宇宙間的星星。不過星星太過遙遠，我們能看到的都是幾十幾百年前的星辰。煙花觸手可及，指間的距離便可欣賞燦爛銀河，只可惜時間短暫。好在我還有很多煙火，足以點亮這漫漫長夜。", attackname = "要發射啦！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "ABOriginal/Role/12020001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12020001/WatchSpine/Watch_3D_front.prefab", interaction = "12020001", coordinate = "12020001", generalattack = "0", midposition = "0,4", topposition = "0,7.85", bottomposition = "0,0", buffplacer = "68112_0;68113_75", zjeffect = "68114_0;68115_50", debut = "68111_0", ready = "68116_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "68117_0", "0", "0", qzoom = "0.4", attackdistance = 22, bulletvelocity = "0", strike = "78_0.85_52_60_1.8_2.5_1.2", delay = "80_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4202000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12020001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12021] = {id = 12021, name = "夫子", story = "韶音的專屬AVG裝甲。由韶音自己提供設計手稿改良製作而成。一開始收到的設計圖，難住了整個工程部的人。沒有人能看明白圖上用九州古文描畫的各種陣圖究竟是什麼意思。", attackname = "後會無期。", painter = "/", voiceexcellence = "永木 さくら", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12021", coordinate = "12021", generalattack = "0", midposition = "0,4.71", topposition = "0,9.36", bottomposition = "0,0", buffplacer = "68448_0;68449_45", zjeffect = "68450_0", debut = "68446_0", ready = "68447_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "48_0.65_38_60_2.1_2.9_1.4", delay = "50_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12021001] = {id = 12021001, name = "墨筆遊龍", story = "飄如遊雲，矯若驚龍。書法中所蘊藏的，不止是文化，還有做人的哲理。所謂字如其人，是從一個人的字跡中即可知其為人和品德。不知能否請賜一幅墨寶，讓小女子仔細品品領航的為人。", attackname = "後會無期。", painter = "/", voiceexcellence = "永木 さくら", backgroundpic = "ABOriginal/Role/12021001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12021001/WatchSpine/Watch_3D_front.prefab", interaction = "12021001", coordinate = "12021001", generalattack = "0", midposition = "0,4.71", topposition = "0,9.36", bottomposition = "0,0", buffplacer = "68448_0;68449_45", zjeffect = "68450_0", debut = "68446_0", ready = "68447_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "48_0.65_38_60_2.1_2.9_1.4", delay = "50_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch3,idle,4202100110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12021001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12021002] = {id = 12021002, name = "鶯時春色", story = "韶音在這場突如其來的小麻煩中顯得有些手忙腳亂，襪子上沾染的涼意讓她微微蜷縮。相比起空氣中的奶香與局促的呼吸交織，此刻她更在意的，是推門而入的領航臉上的笑意。", attackname = "後會無期。", painter = "/", voiceexcellence = "永木 さくら", backgroundpic = "ABOriginal/Role/12021002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12021002/WatchSpine/Watch_3D_front.prefab", interaction = "12021002", coordinate = "12021002", generalattack = "0", midposition = "0,4.71", topposition = "0,9.36", bottomposition = "0,0", buffplacer = "68448_0;68449_45", zjeffect = "68450_0", debut = "68446_0", ready = "68447_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "48_0.65_38_60_2.1_2.9_1.4", delay = "50_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4202100209;switch2,idle,4202100210", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12021002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12022] = {id = 12022, name = "迷途的指針", story = "萊帕尼專屬的AVG裝甲，以引導世人的救濟天使為原型設計，但駕駛員本人卻經常迷失方向，照著導航也能找不到回家的路，這樣的天使真的能引導世人嗎？", attackname = "接下來該往哪兒走？", painter = "/", voiceexcellence = "和氣あず未", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12022", coordinate = "12022", generalattack = "0", midposition = "0,4.65", topposition = "0,7.91", bottomposition = "0,0", buffplacer = "68342_0;60000_46", zjeffect = "68343_0;68344_27", debut = "68340_0", ready = "68341_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_0.6_38_60_2.4_3.1_1.4", delay = "46_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12022001] = {id = 12022001, name = "蜜桃與微風", story = "微風捎來蜜桃味的清香，循風望去，身著體操服的少女正洋溢著青春與活力。她挺起胸膛，得意的目光似是在向我發起邀約，讓我也加入這放課後的運動，用歡笑填滿與她的時光。", attackname = "一起做運動吧！", painter = "/", voiceexcellence = "和氣あず未", backgroundpic = "ABOriginal/Role/12022001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12022001/WatchSpine/Watch_3D_front.prefab", interaction = "12022001", coordinate = "12022001", generalattack = "0", midposition = "0,4.65", topposition = "0,7.91", bottomposition = "0,0", buffplacer = "68342_0;60000_46", zjeffect = "68343_0;68344_27", debut = "68340_0", ready = "68341_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "46_0.6_38_60_2.4_3.1_1.4", delay = "46_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4202200106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
