[12024] = {id = 12024, name = "最初的女主角", story = "暫無", attackname = "有点……生气了……", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/12024/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12024", coordinate = "12024", generalattack = "0", midposition = "0,4.07", topposition = "0,8.1", bottomposition = "0,0", buffplacer = "68510_0", zjeffect = "68511_0", debut = "68509_0", ready = "68512_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "35_0.35_22_60_2.2_3_1.7", delay = "35_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12025] = {id = 12025, name = "平庸者", story = "菲琳的AVG裝甲，是艾吉斯內常見的裝備樣式。沒有任何出眾的特點卻也沒有明顯的短板。換句話説，正因爲普通所以更看重使用者的水平。", attackname = "我……可以的！", painter = "/", voiceexcellence = "根本京里", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12025", coordinate = "12025", generalattack = "0", midposition = "0,4.65", topposition = "0,8.2", bottomposition = "0,0", buffplacer = "68541_0;68542_0", zjeffect = "68543_0;68544_40", debut = "68540_0", ready = "68545_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_0.3_17_60_1.7_2.5_1,12_0.3_14_60_2_2.8_1.7,17_0.35_22_60_2.4_3_1.8", delay = "60_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12025001] = {id = 12025001, name = "兔子？兔子！", story = "菲琳是一只幸福的小兔子，在充滿葡萄味的兔子窩裏，無憂地跳起了快樂的舞蹈。", attackname = "我……可以的！", painter = "/", voiceexcellence = "根本京里", backgroundpic = "ABOriginal/Role/12025001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12025001", coordinate = "12025001", generalattack = "0", midposition = "0,4.65", topposition = "0,8.2", bottomposition = "0,0", buffplacer = "68541_0;68542_0", zjeffect = "68543_0;68544_40", debut = "68540_0", ready = "68545_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "25_0.3_17_60_1.7_2.5_1,12_0.3_14_60_2_2.8_1.7,17_0.35_22_60_2.4_3_1.8", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4202500106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,12025001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12026] = {id = 12026, name = "暴走女僕", story = "駕駛著轟隆隆的摩托，飛馳在無人區的公路上，若是聽到人的呼救，便會從天而降（或是撞破牆壁）登場的戰場閃電——莉法小姐，今天也在廢寢忘食地執行瓦爾基裏的外勤任務。", attackname = "抓緊了！接下來要加速了！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12026", coordinate = "12026", generalattack = "10,18,30,35", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68537_0", zjeffect = "68538_0", debut = "68536_0", ready = "68539_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "8_0.6_42_60_2.2_3_1.5,22_0.45_22_60_2.6_3.4_1.9", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "78-Romance", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12026001] = {id = 12026001, name = "半吊子維修員", story = "不好啦，摩托車壞啦——這樣說著的莉法小姐開始慌慌張張修起了摩托。話雖如此，但只精通女僕工作的莉法並沒有能夠維修摩托的技術能力。最多算半吊子維修員的莉法小姐陷入了前所未有的大危機。", attackname = "抓緊了！接下來要加速了！", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/12026001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12026001", coordinate = "12026001", generalattack = "10,18,30,35", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68537_0", zjeffect = "68538_0", debut = "68536_0", ready = "68539_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "8_0.6_42_60_2.2_3_1.5,22_0.45_22_60_2.6_3.4_1.9", delay = "0", admission = "0", scale = "1,2", bgm = "78-Romance", shoptag = "0", ismorestate = 1, shopanim = "level1,idle3,4202600110,100;level2,idle2,4202600108,100;level3,idle,4202600105,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12026001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12027] = {id = 12027, name = "酣醉聖誕日", story = "只有在耶誕節才會被克裏姆拿出來穿的聖誕老人服裝。這套服裝對克裏姆來說實在不合身，即使過去了這麼多年還是略顯寬大。克裏姆本人倒也並不在意，找來幾段包裝禮物用的帶子就應付了事。至於帶子為什麼被綁在裏面，想必是綁的時候她又喝多了。", attackname = "跟我一起喝點……", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12027", coordinate = "12027", generalattack = "0", midposition = "0,4.65", topposition = "0,8.2", bottomposition = "0,0", buffplacer = "68575_0;68577_45", zjeffect = "68576_0", debut = "68574_0", ready = "68578_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "25_0.3_17_60_1.7_2.5_1,12_0.3_14_60_2_2.8_1.7,17_0.35_22_60_2.4_3_1.8", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12028] = {id = 12028, name = "超級戀愛偵探助手", story = "未來專屬的AVG裝甲。即是偵探，又是偵探助手，變身的道具是帽子，只要戴上帽子就能成為智商很高的偵探，勘破一切虛妄，對所有的犯罪人員降下懲罰，這就是正義的夥伴——超級戀愛偵探助手！", attackname = "發現線索！", painter = "/", voiceexcellence = "本田乃愛", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12028", coordinate = "12028", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68587_0", zjeffect = "68588_0", debut = "68586_0", ready = "68589_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "84-Fight_for_feelings", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12028001] = {id = 12028001, name = "未確認戀愛時", story = "戀愛，未確認的戀愛，未來以小孩子的視角叫囂著想要當你的新娘子。“恐怕她現在還不知道這到底意味著什麼。”你這麼想著為她打開了房門。“有其他女人的味道！”沒想到她立刻就進到房間裡調查起究竟是誰在當偷腥的貓。", attackname = "案件順利解決！", painter = "/", voiceexcellence = "本田乃愛", backgroundpic = "ABOriginal/Role/12028001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12028001/WatchSpine/Watch_3D_front.prefab", interaction = "12028001", coordinate = "12028001", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68587_0", zjeffect = "68588_0", debut = "68586_0", ready = "68589_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "84-Fight_for_feelings", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4202800108,100;switch2,idle,4202800114,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12028001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12029] = {id = 12029, name = "未來系魔法少女", story = "芙露露专属的AVG装甲。街边的长椅上蹲坐着一只安静的小猫。它时而专注地舔舐前爪，时而梳理被风吹乱的毛发，时而仰首快速扫视四方。\n那如炬的目光，似是在等候一个人，一个二十年前便走丢的人。", attackname = "还不打“GG”吗？", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12029", coordinate = "12029", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68610_0;68611_50;68612_0", zjeffect = "68613_0;68615_0", debut = "68609_0", ready = "68614_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "88-Sunshine_Through_Debris", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12029001] = {id = 12029001, name = "與貓咪的嬉鬧時間", story = "“喵喵喵喵！——”快乐的小猫。\n嬉嬉闹闹，上蹿下跳，无忧无虑，没有烦恼，玩到尽兴，玩到累倒。你就是这世界上，最最最快乐的小猫。\n你一定要成为这世界上，最最最快乐的小猫。", attackname = "喵喵喵喵喵——", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "ABOriginal/Role/12029001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12029001/WatchSpine/Watch_3D_front.prefab", interaction = "12029001", coordinate = "12029001", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68610_0;68611_50;68612_0", zjeffect = "68613_0;68615_0", debut = "68609_0", ready = "68614_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "88-Sunshine_Through_Debris", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4202900108,100;switch2,idle,4202900114,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12029001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12030] = {id = 12030, name = "青雲之志", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "還沒結束！", painter = "/", voiceexcellence = "宮本侑芽", backgroundpic = "ABOriginal/Role/12030/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12030", coordinate = "12030", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68623_0;68633_30", zjeffect = "68624_0", debut = "68622_0", ready = "68625_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12030001] = {id = 12030001, name = "夜的晚安儀式", story = "異世界穿越者會在異世界遇到自己喜歡吃的食物嗎？異世界也會有拉麵嗎？會是怎麼樣的？還是說那是名為“拉麵”的，實際上卻完全不同的料理？決定了，今天晚上就吃拉麵！", attackname = "我來幫忙！", painter = "/", voiceexcellence = "宮本侑芽", backgroundpic = "ABOriginal/Role/12030001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12030001/WatchSpine/Watch_3D_front.prefab", interaction = "12030001", coordinate = "12030001", generalattack = "0", midposition = "0,4.8", topposition = "0,9.5", bottomposition = "0,0", buffplacer = "68623_0;68633_30", zjeffect = "68624_0", debut = "68622_0", ready = "68625_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "86-Unconfirmed_feelings", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4203000103;switch2,idle,4203000109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12030001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12031] = {id = 12031, name = "暗黑系魔法少女", story = "“瑪雅事件”發生後，由史蔕芬妮與第一硏究室遠程聯手合作硏制而成的對高等原罪·暴食特制AVG裝甲，能較為有效地抵攩暴食的病毒。\n外觀上由於史蔕芬妮與亞爾薇特兩位博士未提供任何方案，因此采納了某位紅頭發博士的惡趣味設計。", attackname = "四分五裂！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12031", coordinate = "12031", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68667_0", zjeffect = "68668_0;68671_0", debut = "68666_0", ready = "68669_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12031001] = {id = 12031001, name = "居家型危險分子", story = "値得千秋慶幸的是，史蔕芬妮博士的人性幷沒有完全喪失，至少還保畱了1%的程度，這使得她在任務結束後能獲得短暫的假期，與她想陪伴的人待在一起\n“現在就是你好好報答千秋大人的時候了！”躺在你懷裏的千秋如此説道。", attackname = "贏了！", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "ABOriginal/Role/12031001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12031001/WatchSpine/Watch_3D_front.prefab", interaction = "12031001", coordinate = "12031001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68667_0", zjeffect = "68668_0;68671_0", debut = "68666_0", ready = "68669_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4203100106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,12031001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12032] = {id = 12032, name = "閃焰的膽小鬼", story = "占位", attackname = "你的存在對我來説是威脅……", painter = "/", voiceexcellence = "鳴瀬麻美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12032", coordinate = "12032", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68682_0", zjeffect = "68683_0", debut = "68681_0", ready = "68684_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12033] = {id = 12033, name = "業餘選手", story = "格洛麗亞爲了參加駕駛員網球訓練賽而準備的服裝。一開始苦惱於購買哪一款樣式，當得知可以邀請領航作爲訓練對象後，她便親手設計了這款服裝。", attackname = "看招！", painter = "/", voiceexcellence = "稲垣好", backgroundpic = "ABOriginal/Role/12033/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12033", coordinate = "12033", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68686_0", zjeffect = "68687_0", debut = "68685_0", ready = "68688_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "105_leisure_time", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12033001] = {id = 12033001, name = "並非意外的受傷", story = "在激烈的運動中受傷並不是罕見的事情，即使是職業選手也不能避免這類意外——但要注意的是，在身爲業餘網球選手（自稱）前，格洛麗亞還是一名身經百戰的駕駛員，所以，相當可疑，相當刻意。", attackname = "嘿呀！", painter = "/", voiceexcellence = "稲垣好", backgroundpic = "ABOriginal/Role/12033001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12033001/WatchSpine/Watch_3D_front.prefab", interaction = "12033001", coordinate = "12033001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68686_0", zjeffect = "68687_0", debut = "68685_0", ready = "68688_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "105_leisure_time", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4203300107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60003,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12034] = {id = 12034, name = "綻放的晴空", story = "艾吉斯工程師們爲葉芙根尼婭打造的另一套AVG裝甲。不講道理的加速度和輕量化設計讓它看上去簡直像某種實驗裝備，但最關鍵的使用者本人看上去非常滿意。", attackname = "死從天降！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "12034", coordinate = "12034", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68690_0", zjeffect = "68691_0", debut = "68689_0", ready = "68692_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "108_Warm_Fire", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12034001] = {id = 12034001, name = "酒意正酣之時", story = "利用酒精來度過冬季確實是相當一部分卡佳人的生活習慣。但直到她打著招呼把你拉進懷裏的那刻，你才意識到，自己確實很少見到葉芙根尼婭喝醉的樣子。", attackname = "冬季清掃開始！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "ABOriginal/Role/12034001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12034001/WatchSpine/Watch_3D_front.prefab", interaction = "12034001", coordinate = "12034001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68690_0", zjeffect = "68691_0", debut = "68689_0", ready = "68692_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "108_Warm_Fire", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4203400109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12034001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12035] = {id = 12035, name = "宵暗舞蹈團", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "飛起來吧！", painter = "/", voiceexcellence = "和泉風花", backgroundpic = "ABOriginal/Role/10042/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12035", coordinate = "12035", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68713_0", zjeffect = "68714_0", debut = "68712_0", ready = "68715_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12035001] = {id = 12035001, name = "享受派對的狂歡者", story = "“旣然來到了和平的異世界，如果不舉辦一場盛大的兔女郎派對，那簡直就是對靑春的褻瀆！”\n蝦夷夜雲的想法總是很好理解。", attackname = "飛起來吧！", painter = "/", voiceexcellence = "和泉風花", backgroundpic = "ABOriginal/Role/12035001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12035001/WatchSpine/Watch_3D_front.prefab", interaction = "12035001", coordinate = "12035001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68690_0", zjeffect = "68691_0", debut = "68689_0", ready = "68692_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 30, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "65-V_for_Valentine", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4203500113;switch2,idle,4203500114", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,12035001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[12036] = {id = 12036, name = "婚禮未然時", story = "一切準備就緒，只待那神聖時刻的到來。喜悅之感於心中泛起漣漪。儘管明白這一切並非真實，但當那白色的身影出現在眼前的瞬間，內心依然止不住地顫躍。", attackname = "我反对！", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/12036/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "12036", coordinate = "12036", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68726_0", zjeffect = "68727_0", debut = "68725_0", ready = "68728_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "112_Beloved", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[12036001] = {id = 12036001, name = "於夢中約定的誓言", story = "在僅有兩人的樂園中，莉莉絲體驗到了難能可貴的寧靜。她的心靈獲得了前所未有的舒緩，每一次呼吸都洋溢著笑容。仿佛在夢境裏，你正與她許下相伴一生的誓言。", attackname = "我反对！", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "ABOriginal/Role/12036001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/12036001/WatchSpine/Watch_3D_front.prefab", interaction = "12036001", coordinate = "12036001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.21", bottomposition = "0,0", buffplacer = "68726_0", zjeffect = "68727_0", debut = "68725_0", ready = "68728_0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "112_Beloved", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4203600115;switch2,idle3,4203600116;switch3,idle4,4203600117;switch4,idle,4203600118", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60006,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13000] = {id = 13000, name = "安樂椅上的女孩", story = "歐朵啦專屬的AVG裝甲。由歐朵啦自己親手設計，各方面都考慮到了使用者的實際需求，完全量身定做，除了歐朵啦之外沒有第二個人在用上這套裝甲後會感到舒適。", attackname = "呼~啊~睡醒啦！", painter = "/", voiceexcellence = "小倉唯", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13000", coordinate = "13000", generalattack = "0", midposition = "0,3.4", topposition = "0,6.15", bottomposition = "0,0", buffplacer = "68010_0;68011_25", zjeffect = "0", debut = "68007_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.5,0.3,0.3", strike = "0", delay = "0", admission = "170,10,1.75,1", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13000001] = {id = 13000001, name = "房間內的約會時間", story = "到了約定的時間，歐朵啦卻遲遲沒有到來……在一番尋找之後發現她在家裡的沙發上睡著了。“我們今天……在房間裡約會吧……做什麼都可以……”她帶著困意說出了恐怖的話。但你知道這一切都是她懶得出門的藉口。", attackname = "呼~啊~睡醒啦！", painter = "/", voiceexcellence = "小倉唯", backgroundpic = "ABOriginal/Role/13000001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13000001", coordinate = "13000001", generalattack = "0", midposition = "0,3.4", topposition = "0,6.15", bottomposition = "0,0", buffplacer = "68010_0;68011_25", zjeffect = "0", debut = "68007_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.5,0.3,0.3", strike = "0", delay = "0", admission = "170,10,1.75,1", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4300000108,100;switch2,idle,4300000109,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13000001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13001] = {id = 13001, name = "搖籃的惡魔", story = "為弗蘭卡·芬奇專門設計的AVG裝甲，已經蘇醒的紅色太陽，還在等待著升起的那一刻。", attackname = "請放心交給我！", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13001", coordinate = "13001", generalattack = "0", midposition = "0.74,3.36", topposition = "1.13,6.72", bottomposition = "0,0", buffplacer = "68018_0", zjeffect = "0", debut = "68019_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "22_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13001001] = {id = 13001001, name = "若道歉有用……", story = "由於弗蘭卡多次損壞重要駕駛員檔案，妨礙領航瞭解其他駕駛員。現決定將對弗蘭卡進行處罰，處罰權將交由領航親自執行。領航，請盡情地宣洩您的欲……不滿吧。", attackname = "請放心交給我！", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/13001001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13001001/WatchSpine/Watch_3D_front.prefab", interaction = "13001001", coordinate = "13001001", generalattack = "0", midposition = "0.74,3.36", topposition = "1.13,6.72", bottomposition = "0,0", buffplacer = "68018_0", zjeffect = "0", debut = "68019_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "22_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch_s1,idle2,4300100106;touch2,idle2,4300100109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13001001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13001002] = {id = 13001002, name = "碩果與幼狼", story = "弗蘭卡的童話幻想，一隻自由自在的狼。\n她生活在森林中，從小天真爛漫，喜歡一切艷麗之物，她戴著紅頭巾，採摘紅蘋果、紅蘑菇與樹莓，而偶爾，也會採摘些森林中不太常見的“果實”。", attackname = "嗷嗚~嗷嗚~！", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/13001002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13001002/WatchSpine/Watch_3D_front.prefab", interaction = "13001002", coordinate = "13001002", generalattack = "0", midposition = "0.74,3.36", topposition = "1.13,6.72", bottomposition = "0,0", buffplacer = "68018_0", zjeffect = "0", debut = "68019_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "22_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4300100208", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13001002,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13002] = {id = 13002, name = "王才之鞭", story = "蒂娜的AVG裝甲，結構上參考了瑪雅以往的戰機，材料輕薄，使其可以靈活地穿梭於戰場，為其他駕駛員提供及时的支援。", attackname = "是該調教一下了！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13002", coordinate = "13002", generalattack = "0", midposition = "0.31,3.74", topposition = "0.15,7.41", bottomposition = "0,0", buffplacer = "68062_0;60000_15;60000_23", zjeffect = "0", debut = "68261_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "14_0.2_12_60_0.3_0.7_0.1,8_0.2_15_60_0.4_0.9_0.3", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13002001] = {id = 13002001, name = "嚴格的天花板", story = "作為教練，蒂娜對車手的要求極高。訓練期間，蒂娜會以巨大化的形態監視整個賽場，任何的失誤都逃不過她的眼睛，任何的失誤都逃不過她的說教。", attackname = "打起精神！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "ABOriginal/Role/13002001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13002001/WatchSpine/Watch_3D_front.prefab", interaction = "13002001", coordinate = "13002001", generalattack = "0", midposition = "0.31,3.74", topposition = "0.15,7.41", bottomposition = "0,0", buffplacer = "68062_0;60000_15;60000_23", zjeffect = "0", debut = "68261_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "14_0.2_12_60_0.3_0.7_0.1,8_0.2_15_60_0.4_0.9_0.3", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4300200106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13002001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13002002] = {id = 13002002, name = "受祝福的熊", story = "“只要穿上就能和中意的人組成家庭的神奇裝扮”\n休假中的蒂娜將信將疑地看著面前的這些裝飾。\n穿還是會穿穿看的，但她想不明白為什麽是熊。", attackname = "是該調教一下了！", painter = "/", voiceexcellence = "吉成由貴", backgroundpic = "ABOriginal/Role/13002002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13002002/WatchSpine/Watch_3D_front.prefab", interaction = "13002002", coordinate = "13002002", generalattack = "0", midposition = "0.31,3.74", topposition = "0.15,7.41", bottomposition = "0,0", buffplacer = "68062_0;60000_15;60000_23", zjeffect = "0", debut = "68261_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "14_0.2_12_60_0.3_0.7_0.1,8_0.2_15_60_0.4_0.9_0.3", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch,idle,4300200206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "5,13002002,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13003] = {id = 13003, name = "迷糊火槍手", story = "克里姆·科·塔諾夫的AVG裝甲，後置箱內儲存著遠超常規戰鬥所需的液體彈藥，主要便於克里姆在作戰時偷喝。", attackname = "我來了！我的摯友。", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13003", coordinate = "13003", generalattack = "0", midposition = "0.2,3.47", topposition = "0.3,7.03", bottomposition = "0,0", buffplacer = "68065_0;68067_6", zjeffect = "0", debut = "68064_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "0", admission = "200,120,1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13003001] = {id = 13003001, name = "芳紅露滴", story = "克里姆的神秘形象，似乎只在醺醉時分可見。受邀品嘗克里姆所釀美酒，半醉半醒時，朦朧中卻見她身著異裝、神情微妙。直至翌日清晨醉意方醒，昨夜那如夢似幻的體驗已如朝露消逝。", attackname = "我來了！我的摯友。", painter = "/", voiceexcellence = "森嶋優花", backgroundpic = "ABOriginal/Role/13003001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13003001/WatchSpine/Watch_3D_front.prefab", interaction = "13003001", coordinate = "13003001", generalattack = "0", midposition = "0.2,3.47", topposition = "0.3,7.03", bottomposition = "0,0", buffplacer = "68065_0;68067_6", zjeffect = "0", debut = "68064_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "0", admission = "200,120,1,9", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4300300106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13004] = {id = 13004, name = "六合自在", story = "彩華專屬的AVG裝甲，由九州總部研製。對於“點穴”能力有特殊加成。雖然說是巨大化的身體，但是還保留有“穴位”這一神奇器官，真是太好了。", attackname = "學醫無法拯救人們。", painter = "/", voiceexcellence = "逢来りん", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13004", coordinate = "13004", generalattack = "0", midposition = "0.2,3.58", topposition = "0,7.19", bottomposition = "0,0", buffplacer = "68084_0;68085_0;68086_0;68087_0;68088_0;68089_0;68090_0", zjeffect = "0", debut = "68083_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 7, bulletvelocity = "0", strike = "28_0.5_23_60_1.8_1.1_0.4", delay = "28_0.1,5_0.3,5_0.3,5_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13004001] = {id = 13004001, name = "尷尬邂逅", story = "漫步在落葉小道，從未期待過的偶然邂逅。\n“是誰？“”你是……”……\n“你在這幹嘛？”“你怎麼找到這的？”……\n“這個葫蘆是？”“唔……你猜?”……", attackname = "學醫無法拯救人們。", painter = "/", voiceexcellence = "逢来りん", backgroundpic = "ABOriginal/Role/13004001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13004001/WatchSpine/Watch_3D_front.prefab", interaction = "13004001", coordinate = "13004001", generalattack = "0", midposition = "0.2,3.58", topposition = "0,7.19", bottomposition = "0,0", buffplacer = "68084_0;68085_0;68086_0;68087_0;68088_0;68089_0;68090_0", zjeffect = "0", debut = "68083_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 7, bulletvelocity = "0", strike = "28_0.5_23_60_1.8_1.1_0.4", delay = "28_0.1,5_0.3,5_0.3,5_0.3", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch2,idle,4300400106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13005] = {id = 13005, name = "斷死扶生", story = "熱尼亞專屬的AVG裝甲，由卡佳軍方參與研製，採用輕金屬作為原料製作而成，便於長距離奔襲，也可以將更多的載重量用於能量儲備上。", attackname = "我会完成我的天职……", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13005", coordinate = "13005", generalattack = "0", midposition = "0,4.28", topposition = "0.63,7.8", bottomposition = "0,0", buffplacer = "68119_0;68120_35", zjeffect = "68121_0", debut = "68118_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "38_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13005001] = {id = 13005001, name = "風搖波蕩", story = "獨坐在靠海的咖啡廳，點上一杯醇香的紅茶。海風輕拂，帶來大海獨有的鹹腥氣，有些冷，但比不過冰雪的刺骨。一切都是如此美好，除了頭頂的遮陽帽需要煩心，不然風一吹就不知會飛到何人手中。", attackname = "我会完成我的天职……", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "ABOriginal/Role/13005001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13005001/WatchSpine/Watch_3D_front.prefab", interaction = "13005001", coordinate = "13005001", generalattack = "0", midposition = "0,4.28", topposition = "0.63,7.8", bottomposition = "0,0", buffplacer = "68119_0;68120_35", zjeffect = "68121_0", debut = "68118_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "38_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4300500107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13005001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13005002] = {id = 13005002, name = "專人問診時間", story = "似乎是預料到了某人的到來，熱尼亞安靜落坐在椅子上。護士服與消毒水的味道將氛圍襯得格外正式，她卻偏偏慵懶地翹着腿，儘管指尖輕握着一支注射器。但那故作嚴肅的神情下，仍藏着諸多頗富趣味性的心思。", attackname = "我會完成我的天職……", painter = "/", voiceexcellence = "加隈亜衣", backgroundpic = "ABOriginal/Role/13005002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13005002/WatchSpine/Watch_3D_front.prefab", interaction = "13005002", coordinate = "13005002", generalattack = "0", midposition = "0,4.28", topposition = "0.63,7.8", bottomposition = "0,0", buffplacer = "68119_0;68120_35", zjeffect = "68121_0", debut = "68118_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "38_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4300500210;switch2,idle3,4300500211;switch3,idle,4300500212", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13005002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13006] = {id = 13006, name = "不敬神禮", story = "瑩草的專屬AVG裝甲，結合了心經屋的巫女服，以及戰機的噴射動力裝置。衣服的前襟比正常尺寸要大上不少。", attackname = "醫護人員就位！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13006", coordinate = "13006", generalattack = "0", midposition = "0.15,3.6", topposition = "0.15,7.3", bottomposition = "0,0", buffplacer = "68220_0;68221_43,68222_0", zjeffect = "0", debut = "68219_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "60_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13006001] = {id = 13006001, name = "沉甸甸的寵幸", story = "應邀去山間踏青，未曾想前來迎接的是巨大化的瑩草。即使百般不願也抵抗不了被關在倉鼠籠裏的命運。既然如此，便暫時忘掉身份，忘掉工作，專心扮演一只深陷瑩草寵倖之中的倉鼠吧。", attackname = "醫護人員就位！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/13006001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13006001/WatchSpine/Watch_3D_front.prefab", interaction = "13006001", coordinate = "13006001", generalattack = "0", midposition = "0.15,3.6", topposition = "0.15,7.3", bottomposition = "0,0", buffplacer = "68220_0;68221_43,68222_0", zjeffect = "0", debut = "68219_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4300600106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13006001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13006002] = {id = 13006002, name = "錦歲如意", story = "锦绣年华，旗袍金线，春光明媚，万事如意。只是不知这暖人身心的春意究竟是即将春回大地的前兆，还是那旗袍贴身而裁，勾勒出的玲珑身段的诱惑。她从流光中缓步而来，旗袍曳地，眉眼含春，霞飞双颊。", attackname = "醫護人員就位！", painter = "/", voiceexcellence = "武藤志織", backgroundpic = "ABOriginal/Role/13006002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13006002/WatchSpine/Watch_3D_front.prefab", interaction = "13006002", coordinate = "13006002", generalattack = "0", midposition = "0.15,3.6", topposition = "0.15,7.3", bottomposition = "0,0", buffplacer = "68220_0;68221_43,68222_0", zjeffect = "0", debut = "68219_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.2,0.4,0.4", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch12,idle2,4300600206,100;switch23,idle3,4300600212,100;switch31,idle,4300600218,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13006002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13007] = {id = 13007, name = "人類模仿者", story = "暫無", attackname = "T型机投放成功。", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13007", coordinate = "13007", generalattack = "0", midposition = "0,3.96", topposition = "0,7.41", bottomposition = "0,0", buffplacer = "68123_0", zjeffect = "68124_0", debut = "68122_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0.8,0.3,0.3", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "21-Battle-Warehouse3_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13008] = {id = 13008, name = "星辰騎士", story = "伊莎貝拉專屬的AVG裝甲，宿命的純白色甲胄。高舉救世的旗幟，以此行過的路途便是命運的旅程。伊莎貝拉的甲胄是龍騎士中最特殊的，但是希望龍騎士們永遠沒有見到這道最後保險的一天。", attackname = "此即天命！", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13008", coordinate = "13008", generalattack = "0", midposition = "0.1,4.1", topposition = "0.1,8.1", bottomposition = "0,0", buffplacer = "68126_0;68127_40", zjeffect = "68128_0;68129_80", debut = "68125_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.4,0.4,0.4", strike = "0", delay = "0", admission = "200,10,1.9,1", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13008001] = {id = 13008001, name = "海濱的聖淑女", story = "沒來由的行動，緊接著付諸於行動，被命運所牽引著的少女在這裡遇到的是她的命定之人。如果把這說成是宿命的相遇，是照亮星空的契機，那麼也就能解釋心中這一份悸動了。", attackname = "此即天命！", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "ABOriginal/Role/13008001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13008001", coordinate = "13008001", generalattack = "0", midposition = "0.1,4.1", topposition = "0.1,8.1", bottomposition = "0,0", buffplacer = "68126_0;68127_40", zjeffect = "68128_0;68129_80", debut = "68125_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.4,0.4,0.4", strike = "0", delay = "0", admission = "200,10,1.9,1", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4300800106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13008002] = {id = 13008002, name = "靜默的二十五分鍾", story = "摩天輪轉一圈的時間是二十五分鍾，與世隔絶的二十五分鍾，只屬於兩个人的二十五分鍾。如此寶貴的二十五分鍾，當然不能就這樣靜靜地等待它流逝。\n然而在星空的見證下，你看著伊莎貝拉卻始終無動於衷。", attackname = "此即天命！", painter = "/", voiceexcellence = "大木咲絵子", backgroundpic = "ABOriginal/Role/13008002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13008002/WatchSpine/Watch_3D_front.prefab", interaction = "13008002", coordinate = "13008002", generalattack = "0", midposition = "0.1,4.1", topposition = "0.1,8.1", bottomposition = "0,0", buffplacer = "68126_0;68127_40", zjeffect = "68128_0;68129_80", debut = "68125_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "1.4,0.4,0.4", strike = "0", delay = "0", admission = "200,10,1.9,1", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4300800206", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13008002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13009] = {id = 13009, name = "異星公主", story = "艾伊瓦蒂專屬的AVG裝甲，結合米狄爾科技的艾吉斯最新造物。內嵌的特殊能量回路以及仿製米狄爾增幅水晶，可以對使用者的精神力形成最大程度的增幅。", attackname = "我們的心早已互相牽連。", painter = "/", voiceexcellence = "古賀葵", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13009", coordinate = "13009", generalattack = "0", midposition = "0.23,4.1", topposition = "0.36,8.57", bottomposition = "0,0", buffplacer = "68322_0", zjeffect = "68324_0", debut = "68321_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13009001] = {id = 13009001, name = "星際秘航", story = "寰宇間的神奇之物，維度之上被抹去的隱秘空間，碳基生命不可踏足的死區……這些列在待辦清單上的目標是艾伊瓦蒂一生的遺憾。幸好她能與你在電子遊戲中體驗這些。只是……為什麼領航的形象是只觸手怪？", attackname = "我們的心早已互相牽連。", painter = "/", voiceexcellence = "古賀葵", backgroundpic = "ABOriginal/Role/13009001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13009001/WatchSpine/Watch_3D_front.prefab", interaction = "13009001", coordinate = "13009001", generalattack = "0", midposition = "0.23,4.1", topposition = "0.36,8.57", bottomposition = "0,0", buffplacer = "68322_0", zjeffect = "68324_0", debut = "68321_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch2,idle,4300900109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13009001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13010] = {id = 13010, name = "絨面醫師", story = "渠的專屬AVG裝甲。埃塔星人過強的身體素質，使得她們幾乎不需要什麼動力裝甲就能獲得與原罪戰鬥的力量。因此渠盡可能將幻化核心的能源分配在能支援隊友戰鬥的裝備上。", attackname = "今天，我們將書寫傳奇！", painter = "/", voiceexcellence = "白砂沙帆", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13010", coordinate = "13010", generalattack = "0", midposition = "0,3.42", topposition = "0,7.67", bottomposition = "0,0", buffplacer = "68305_0;68306_27;68306_55", zjeffect = "68307_24;68308_24", debut = "68304_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "63_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13010001] = {id = 13010001, name = "狐狸的美夢", story = "就像每個人都曾有過的童年夢想，有的人想當科學家，有的人想當藝術家，而渠的心願是成為護士。某種意義上她的美夢成真了，而你能陪著她將這份美夢繼續下去嗎？", attackname = "今天，我們將書寫傳奇！", painter = "/", voiceexcellence = "白砂沙帆", backgroundpic = "ABOriginal/Role/13010001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13010001/WatchSpine/Watch_3D_front.prefab", interaction = "13010001", coordinate = "13010001", generalattack = "0", midposition = "0,3.42", topposition = "0,7.67", bottomposition = "0,0", buffplacer = "68305_0;68306_27;68306_55", zjeffect = "68307_24;68308_24", debut = "68304_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "63_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4301000106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "5,13010001,tz_qd_0_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13011] = {id = 13011, name = "神聖Trick", story = "梅莉雅專屬的AVG裝甲，根據其日常穿著設計而成。與其本身相比特別寬大的長袍或許能提供一定的防護，但是對於機動性的負面影響要遠遠大於防護的提升。", attackname = "聖杯之水喲~！", painter = "/", voiceexcellence = "佐倉薫", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13011", coordinate = "13011", generalattack = "0", midposition = "0,4.73", topposition = "0,9.36", bottomposition = "0,0", buffplacer = "68464_0;68465_60", zjeffect = "68466_0;68467_54", debut = "68463_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "67-Puenred_WestEnd", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13011001] = {id = 13011001, name = "於井底綻放之花", story = "乾涸的井底即使用聖水澆灌也只能攪弄出惡臭的淤泥。但有時淤泥之下也埋藏著花的種子，污穢、黑暗、欲望……便是它最豐盛的養料。待到春雨的滴落，根莖撥開淤泥，種子便生長成潔淨、純美的花。", attackname = "聖杯之水喲~！", painter = "/", voiceexcellence = "佐倉薫", backgroundpic = "ABOriginal/Role/13011001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13011001", coordinate = "13011001", generalattack = "0", midposition = "0,4.73", topposition = "0,9.36", bottomposition = "0,0", buffplacer = "68464_0;68465_60", zjeffect = "68466_0;68467_54", debut = "68463_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 17, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "67-Puenred_WestEnd", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,13011001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13012] = {id = 13012, name = "夏日序列魔女", story = "漢克", attackname = "序列部署完成。", painter = "/", voiceexcellence = "遠野ひかる", backgroundpic = "ABOriginal/Role/13012/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13012", coordinate = "13012", generalattack = "0", midposition = "0.2,4.71", topposition = "0,8.36", bottomposition = "0,0", buffplacer = "68131_0;68132_61", zjeffect = "68133_0;68134_34", debut = "68130_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "0", delay = "61_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13013] = {id = 13013, name = "空氣系魔法少女", story = "芙露露的專屬AVG裝甲，由一名沉迷魔法少女幻想的科學家研製。貓貓有了翅膀，這樣她就能去追尋自己想要的東西。", attackname = "喵！？", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13013", coordinate = "13013", generalattack = "0", midposition = "0.15,3.6", topposition = "0.15,7.3", bottomposition = "0,0", buffplacer = "68214_0;68215_60", zjeffect = "0", debut = "68213_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13013001] = {id = 13013001, name = "貓的報恩", story = "“貓的報恩”——過去曾經似乎有這樣的民間故事。懵懂的芙露露在隊長的慫恿下換上了這身衣服，而作為領航的你是不是應該對此說點什麼？", attackname = "喵！？", painter = "/", voiceexcellence = "伏見はる香", backgroundpic = "ABOriginal/Role/13013001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13013001/WatchSpine/Watch_3D_front.prefab", interaction = "13013001", coordinate = "13013001", generalattack = "0", midposition = "0.15,3.6", topposition = "0.15,7.3", bottomposition = "0,0", buffplacer = "68214_0;68215_60", zjeffect = "0", debut = "68213_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 11, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4301300106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13013001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13014] = {id = 13014, name = "流雪尋冰", story = "莫莫卡專屬的AVG裝甲，由卡佳支部定制。通體的白色非常契合莫莫卡本身的膚色。或許在雪地中能提供一些隱秘性。", attackname = "雪花的轨迹……", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13014", coordinate = "13014", generalattack = "0", midposition = "0,3.42", topposition = "0,7.67", bottomposition = "0,0", buffplacer = "68384_0;68385_55", zjeffect = "68386_0;68387_40", debut = "68383_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "63_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13014001] = {id = 13014001, name = "海濱融雪", story = "熱，為什麼海邊這麼熱。我需要水……不，我需要冰塊。沒有冰塊，只能用水……防曬霜沒有用，好黏，更熱了。海水，海水可以降溫……但是我不會游泳……只是泡腳的話，應該也可以……", attackname = "雪花的轨迹……", painter = "/", voiceexcellence = "知念明希保", backgroundpic = "ABOriginal/Role/13014001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13014001/WatchSpine/Watch_3D_front.prefab", interaction = "13014001", coordinate = "13014001", generalattack = "0", midposition = "0,3.42", topposition = "0,7.67", bottomposition = "0,0", buffplacer = "68384_0;68385_55", zjeffect = "68386_0;68387_40", debut = "68383_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "63_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4301400106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13014001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13015] = {id = 13015, name = "超級假面人1號", story = "暫無", attackname = "看槍看槍！", painter = "/", voiceexcellence = "大津愛理", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13015", coordinate = "13015", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68479_0;68480_50", zjeffect = "68481_0;68482_40", debut = "68478_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 24, bulletvelocity = "0", strike = "0", delay = "50_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13016] = {id = 13016, name = "億千萬的幸福", story = "多洛莉絲專屬的AVG裝甲，因為原本偶像造型的裝甲需要定期調試和升級，所以在裝備維護期間，紅博士為多洛莉絲量身定製了另外一套裝甲，本來預計是兔女郎的造型，在多洛莉絲的一再堅持下換成了現在的樣子。", attackname = "交給我吧！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/13016/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13016", coordinate = "13016", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68583_0;68585_50", zjeffect = "68584_0", debut = "68582_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "83-Black_Secret", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13016001] = {id = 13016001, name = "好想對你說", story = "多洛莉絲在窗前靜靜地凝視遠方，眼裏閃爍著如晨曦般柔和的光芒。或許是在某個陽光明媚的午後，或許是在繁星點點的夜晚，直到你出現在她的身邊，然後——她的世界變得溫柔和絢爛。好想要對你說出這份心情。", attackname = "讓我來保護大家！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/13016001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13016001/WatchSpine/Watch_3D_front.prefab", interaction = "13016001", coordinate = "13016001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68583_0;68585_50", zjeffect = "68584_0", debut = "68582_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "83-Black_Secret", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4301600103,100;switch2,idle3,4301600104,100;switch3,idle4,4301600105,100;switch4,idle,4301600106,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60000,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13017] = {id = 13017, name = "敗北女主角No.99", story = "九十九環專屬的AVG裝甲。即使會失敗九十九次，但在第一百次成功拯救大家的話那就等於贏下了所有。名為九十九環的少女與你擁有著相同的決意。“我要前往一個所有人都面帶笑容的完美未來！", attackname = "女主角~開始行動咯！", painter = "/", voiceexcellence = "松平美波穂", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13017", coordinate = "13017", generalattack = "0", midposition = "0,4.37", topposition = "0,8.24", bottomposition = "0,0", buffplacer = "68408_0;68409_55", zjeffect = "68410_0;68411_55", debut = "68406_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13017001] = {id = 13017001, name = "絕對戀愛怪盜", story = "第一，絕對不放棄每一位心懷熾烈感情的少女。第二，絕對不放過任何一位搶跑的卑女。第三，絕對戀愛的公平正義。我正是從不同時間線重疊而來的感情。絕對戀愛怪盜，九十九環。", attackname = "女主角~開始行動咯！", painter = "/", voiceexcellence = "松平美波穂", backgroundpic = "ABOriginal/Role/12013001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13017001", coordinate = "13017001", generalattack = "0", midposition = "0,4.37", topposition = "0,8.24", bottomposition = "0,0", buffplacer = "68408_0;68409_55", zjeffect = "68410_0;68411_55", debut = "68406_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level,idle,4301700106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13017002] = {id = 13017002, name = "預言中的第一夜", story = "在女主角宇宙能抓到領航的幾率很低，但機會全靠自己創造，即使失敗了兩次敗北女主角也不會放棄。【你所認為的偶遇是我歷經波折找到的必定！】", attackname = "晚上睡得怎麼樣？", painter = "/", voiceexcellence = "松平美波穂", backgroundpic = "ABOriginal/Role/13017002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13017002/WatchSpine/Watch_3D_front.prefab", interaction = "13017002", coordinate = "13017002", generalattack = "0", midposition = "0,4.37", topposition = "0,8.24", bottomposition = "0,0", buffplacer = "68408_0;68409_55", zjeffect = "68410_0;68411_55", debut = "68406_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "54-Samsara", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4301700212", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13017002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13018] = {id = 13018, name = "寂靜電波", story = "漢克", attackname = "噓~且聽龍吟……", painter = "/", voiceexcellence = "鳴瀬麻美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13018", coordinate = "13018", generalattack = "0", midposition = "0.27,3.96", topposition = "0.27,8.17", bottomposition = "0,0", buffplacer = "68209_0;68210_55", zjeffect = "68211_0;68212_55", debut = "68208_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "45_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13019] = {id = 13019, name = "天醫", story = "朝霧專屬的AVG裝甲，參考了九州古風服裝的特點。為了穿著的舒適度使用了大部分的柔性織物，但防禦的性能其實並沒有落後其他裝備。", attackname = "世界之癌，準備割治。", painter = "/", voiceexcellence = "鳴瀬麻美", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13019", coordinate = "13019", generalattack = "0", midposition = "0.04,5.16", topposition = "0,9.3", bottomposition = "0,0", buffplacer = "68327_0;68328_35", zjeffect = "68329_0", debut = "68326_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13019001] = {id = 13019001, name = "海水浴療法", story = "身體浸入海水，波瀾起伏的海水拍打著皮膚，感受血液的加速。疲勞和壓力仿佛隨著浪水的漲落退了潮，這就是海水浴療法的益處。至於其注意事項，將由朝霧醫生來講解。", attackname = "世界之癌，準備割治。", painter = "/", voiceexcellence = "鳴瀬麻美", backgroundpic = "ABOriginal/Role/13019001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13019001/WatchSpine/Watch_3D_front.prefab", interaction = "13019001", coordinate = "13019001", generalattack = "0", midposition = "0.04,5.16", topposition = "0,9.97", bottomposition = "0,0", buffplacer = "68327_0;68328_35", zjeffect = "68329_0", debut = "68326_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4301900106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13019001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13020] = {id = 13020, name = "第七賢", story = "梅貝爾·伊司的AVG裝甲，簡約的白色長裙，可以更好地體現梅貝爾自身的存在，不過環繞著她的巨大裝甲卻更加搶眼。", attackname = "開課了~", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13020", coordinate = "13020", generalattack = "0", midposition = "0,4.01", topposition = "0,8.12", bottomposition = "0,0", buffplacer = "68332_0;68333_55", zjeffect = "68334_0;68335_75", debut = "68331_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13020001] = {id = 13020001, name = "假日導論", story = "獲得了領航的許可後，梅貝爾以巨大的身姿來到海上避暑。不同於以往，她幻化出了清涼的泳衣和一個巨大的泳圈。據她所說這樣可以更好地思考文化和哲學。", attackname = "開課了~", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "ABOriginal/Role/13020001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13020001", coordinate = "13020001", generalattack = "0", midposition = "0,4.01", topposition = "0,8.12", bottomposition = "0,0", buffplacer = "68332_0;68333_55", zjeffect = "68334_0;68335_75", debut = "68331_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "level1,idle,4302000106", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13020001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13020002] = {id = 13020002, name = "上課睡覺時間", story = "課堂是最舒適的床鋪，經文般的朗誦，筆尖劃動的窸窣，即便是老師都不自知地墜入夢鄉。待到一覺醒來，學生早已散去，空空當當的教室中，梅貝爾看著你依舊睡眼朦朧，似乎在回味一個好夢。", attackname = "開課了~", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "ABOriginal/Role/13020002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13020002", coordinate = "13020002", generalattack = "0", midposition = "0,4.01", topposition = "0,8.12", bottomposition = "0,0", buffplacer = "68332_0;68333_55", zjeffect = "68334_0;68335_75", debut = "68331_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "60_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4302000209", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13020002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13021] = {id = 13021, name = "稚氣占卜師", story = "星井專屬的AVG裝甲，以傳統的巫女服為藍本設計，同時結合了心經屋相關的元素。在其背後碩大的裝甲襯托下，星井仿佛是人界和神界之間的守門人，抑或是神界在人界的代表者。", attackname = "於命途之河中消隱……", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13021", coordinate = "13021", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68350_0", zjeffect = "68352_0;68353_70", debut = "68349_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13021001] = {id = 13021001, name = "玲瓏雅姿", story = "古典服裝彰顯玲瓏身段，傳統風格迸發出新潮美學。真正應該欣賞的不是葉也不是花，而是那支撐葉與花的莖。那優柔曲軟、堅韌拔挺的莖，人體之美盡在其中。", attackname = "汝等的消逝已然註定。", painter = "/", voiceexcellence = "せきしほ", backgroundpic = "ABOriginal/Role/13021001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13021001/WatchSpine/Watch_3D_front.prefab", interaction = "13021001", coordinate = "13021001", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68350_0", zjeffect = "68352_0;68353_70", debut = "68349_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "touch1,idle,4302100106", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13022] = {id = 13022, name = "懲罪的審訊官", story = "莫妮卡專屬的AVG裝甲。由奧德賽重工出資研發而成。有著不俗的防禦性能，可以適應多種戰鬥環境足以應付各種突發狀況。外觀設計上參照奧德賽重工內安保部門的制服設計，貼合奧德賽重工集團的風格。", attackname = "才剛開始呢……", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13022", coordinate = "13022", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68559_0", zjeffect = "68560_0;68561_7", debut = "68558_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13022001] = {id = 13022001, name = "終點線的閃耀時刻", story = "掌聲如雷滾動，鏡頭閃動不息，就連陽光都不自覺地聚焦於此。這是只有冠軍才能擁有的閃耀時刻，莫妮卡顯然已經沉醉其中，不可自拔。即便賽場上已經沒有其他觀眾，她也依舊保持著微笑，似乎在等待著你的獎勵。", attackname = "才剛開始呢……", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "ABOriginal/Role/13022001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13022001/WatchSpine/Watch_3D_front.prefab", interaction = "13022001", coordinate = "13022001", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68559_0", zjeffect = "68560_0;68561_7", debut = "68558_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4302200110,100;switch2,idle3,4302200111,100;switch3,idle,4302200112,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13022001,tz_sc_zbsd_01", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13022002] = {id = 13022002, name = "用餐前的問候", story = "莫妮卡為等候某人的光臨而整裝待發，空氣中也帶著一絲曖昧的儀式感。她始終未開口，但閃爍的目光早已越過了職業的紅線——她準備向來者發出了一份私密邀請。", attackname = "才剛開始呢……", painter = "/", voiceexcellence = "赤堀実華琉", backgroundpic = "ABOriginal/Role/13022002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13022002", coordinate = "13022002", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68559_0", zjeffect = "68560_0;68561_7", debut = "68558_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4302200210;switch2,idle3,4302200211;switch3,idle,4302200212", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13022002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13023] = {id = 13023, name = "心纏戀絲", story = "暫無", attackname = "才剛開始呢……", painter = "/", voiceexcellence = "堀越せな", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13023", coordinate = "13023", generalattack = "0", midposition = "0.24,4.5", topposition = "0.24,8.1", bottomposition = "0,0", buffplacer = "68594_0", zjeffect = "68595_0;68596_7", debut = "68593_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 13, bulletvelocity = "0", strike = "0", delay = "40_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13024] = {id = 13024, name = "一定能找到", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "看見了！", painter = "/", voiceexcellence = "立花日菜", backgroundpic = "ABOriginal/Role/13024/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13024", coordinate = "13024", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68627_0", zjeffect = "68628_0;68629_0", debut = "68626_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13024001] = {id = 13024001, name = "幼稚園天使降臨", story = "大川村寧，即使在風雨中也會抬頭望向天空的女孩子。即使跌倒了，也會為了守護心中珍貴的東西重新站起來的天使，降臨了幼稚園。", attackname = "弱點在那裡！", painter = "/", voiceexcellence = "立花日菜", backgroundpic = "ABOriginal/Role/13024001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13024001/WatchSpine/Watch_3D_front.prefab", interaction = "13024001", coordinate = "13024001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68627_0", zjeffect = "68628_0;68629_0", debut = "68626_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "65-V_for_Valentine", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4302400103;switch2,idle,4302400109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,13024001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13025] = {id = 13025, name = "被“封印”的恶魔", story = "拘謹的她，有小心思的她，不願意落後的她，這些都是構成“弗蘭卡”的一部分，既是真實的她，也是不完整的她，她希望你能接納她們。", attackname = "我是惡魔嗎？", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/13025/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13025", coordinate = "13025", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68641_0;68642_21", zjeffect = "68643_0;68644_17", debut = "68640_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "36-Clarity", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13025001] = {id = 13025001, name = "惡魔新娘修行中", story = "“繼續當好孩子的話，就會失去不願意失去的，絕對不能失去的，一定要牢牢抓在手裡的機會”——這樣的預感出現在了弗蘭卡的心中，於是，惡魔誕生了。", attackname = "我是惡魔嗎？", painter = "/", voiceexcellence = "逢来りん/松永あかね", backgroundpic = "ABOriginal/Role/13025001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13025001/WatchSpine/Watch_3D_front.prefab", interaction = "13025001", coordinate = "13025001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68641_0;68642_21", zjeffect = "68643_0;68644_17", debut = "68640_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "36-Clarity", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4302500108", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60001,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13026] = {id = 13026, name = "大家的媽媽哦~", story = "夏天正是轉換心情好好玩樂的時候……只不過不知火的變化是不是太大了？她似乎對自己的熱情高漲沒有任何自覺，徹徹底底地變成了寵愛和關心大家的媽媽角色……不，不如說更進一步，這完全就是溺愛了。", attackname = "要小心哦~", painter = "/", voiceexcellence = "坂井爱実", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13026", coordinate = "13026", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68653_0;68654_0", zjeffect = "68655_0", debut = "68652_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13026001] = {id = 13026001, name = "和媽媽一起享受吧~", story = "為什麼要以“媽媽”自稱？難道說……這是一種情趣？算了……既然是來放鬆的……那就稍微迎合一下不知火的趣味吧，暫時對不知火這異常的表現視而不見吧。但是先錄影一下保存這段少見的景象吧。", attackname = "媽媽會保護你們的！", painter = "/", voiceexcellence = "坂井爱実", backgroundpic = "ABOriginal/Role/13026001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13026001/WatchSpine/Watch_3D_front.prefab", interaction = "13026001", coordinate = "13026001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68653_0;68654_0", zjeffect = "68655_0", debut = "68652_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "96-What_will_the_future_be_like", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4302600109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,13026001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13027] = {id = 13027, name = "暮色薔薇", story = "習慣了法爾奈斯在蒼穹學院時的打扮，常常會讓人忘記她名義上是身份顯赫的千金大小姐——盡管她並不認爲這樣的噱頭會讓自己的價値更高，但這並不影響她舉手投足間都帶著如貴族一樣的氣質。\n當然，她並不是貴族，而是帶刺的薔薇。", attackname = "戲劇開始了。", painter = "/", voiceexcellence = "长月あおい", backgroundpic = "ABOriginal/Role/13027/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "13027", coordinate = "13027", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68703_0", zjeffect = "68704_0", debut = "68702_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13027001] = {id = 13027001, name = "無法入睡的場合", story = "疲憊時想要入睡是人之常情，但在約會時入睡是她無法接受的事——那寶貴的時間應該爭分奪秒的珍惜，而不是浪費在睡眠上。\n因此，她不打算讓領航入睡。", attackname = "戲劇開始了。", painter = "/", voiceexcellence = "长月あおい", backgroundpic = "ABOriginal/Role/13027001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13027001/WatchSpine/Watch_3D_front.prefab", interaction = "13027001", coordinate = "13027001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68703_0", zjeffect = "68704_0", debut = "68702_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4302700107", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "2,60004,tz_hd_0_510", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[13028] = {id = 13028, name = "甜蜜售賣員", story = "巧可專屬的AVG裝甲，由九州總部的研發部門設計。性能方面不用說，外觀設計也很符合巧可可愛的氣質。部分設計費用由“甜心巧可屋”與“嗷嗚小賣部”聯合贊助。", attackname = "糖果大甩賣", painter = "/", voiceexcellence = "菅野美咲", backgroundpic = "0", type = 0, foregroundpic = "0", interaction = "13028", coordinate = "13028", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68723_0", zjeffect = "68724_0", debut = "68722_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[13028001] = {id = 13028001, name = "最甜蜜的誓約", story = "午後的光斑在奶白色裙擺上跳躍。巧可遞出花束，假裝不去在意那枚未完成的誓約。“提拉米蘇先生，送給你。”裙擺輕蕩，揉捏那落在腳踝上的琥珀色的光——仿佛比世間所有諾言都要香甜。", attackname = "糖果大甩賣", painter = "/", voiceexcellence = "菅野美咲", backgroundpic = "ABOriginal/Role/13028001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/13028001/WatchSpine/Watch_3D_front.prefab", interaction = "13028001", coordinate = "13028001", generalattack = "0", midposition = "0,4.97", topposition = "0,9.89", bottomposition = "0,0", buffplacer = "68723_0", zjeffect = "68724_0", debut = "68722_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "0", delay = "0", admission = "0", scale = "1,2", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4302800103,100;switch2,idle3,4302800105,100;switch3,idle4,4302800107,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,13028001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14000] = {id = 14000, name = "三億分之一的偶然", story = "星爍的AVG裝甲，以星變OS達到目前人類的極限。以星變OS完成幻化的星爍，是人類在漫長的種族存續之戰中個體偉力的里程碑，星爍一人便足以實施對准罪級的斬首行動。", attackname = "沉淪吧。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "ABOriginal/Role/14000/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14000", coordinate = "14000", generalattack = "0", midposition = "0,4.62", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68429_0", zjeffect = "68430_0", debut = "68428_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "34_0.4,31_0.6", admission = "0", scale = "0.5,1.5", bgm = "43-antinova", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14000001] = {id = 14000001, name = "我們也曾並肩前行", story = "如果過去的錯過不能再被尋到，那麼請讓時間倒流吧。即使想要綻放在你的身邊，卻總因為錯過花期而與你擦身而過。我能用好運一次又一次救下你，卻不能與你再相見。", attackname = "沉淪吧。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "ABOriginal/Role/14000001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14000001/WatchSpine/Watch_3D_front.prefab", interaction = "14000001", coordinate = "14000001", generalattack = "0", midposition = "0,4.62", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68432_0", zjeffect = "68433_0", debut = "68431_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "34_0.4,31_0.6", admission = "0", scale = "1,2", bgm = "43-antinova", shoptag = "0", ismorestate = 0, shopanim = "touch_s1,idle2,4400000110;touch5,idle2,4400000112", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14000001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14000002] = {id = 14000002, name = "懲罰時間？獎勵時間？", story = "因為幹了某事而被史蒂芬妮博士懲罰的星爍?亦或者是因為完成了某件重要任務而被史蒂芬妮博士獎勵的星爍？總之，星爍很自然地把鎖鏈交到了你的手裡，對她而言接下來是獎勵時間還是懲罰時間，由你決定。", attackname = "沉淪吧。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "ABOriginal/Role/14000002/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14000002/WatchSpine/Watch_3D_front.prefab", interaction = "14000002", coordinate = "14000002", generalattack = "0", midposition = "0,4.62", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68432_0", zjeffect = "68433_0", debut = "68431_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "34_0.4,31_0.6", admission = "0", scale = "1,2", bgm = "43-antinova", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4400000203;switch2,idle,4400000209", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14000002,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14000003] = {id = 14000003, name = "晚星的低語", story = "夜風吹得星爍的裙襬沙沙作響。聽到有人走近的腳步，她的後背一下子繃得緊緊的。平時總是擺着輕鬆笑容的星爍，現在卻緊張得只能側臉悄悄地看着身後……但不管怎樣，這個有些侷促卻又無比誠實的背影，或許早已向領航坦白了她心裏全部的喜歡，不是嗎？", attackname = "沉淪吧。", painter = "/", voiceexcellence = "山本亜衣", backgroundpic = "ABOriginal/Role/14000003/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14000003/WatchSpine/Watch_3D_front.prefab", interaction = "14000003", coordinate = "14000003", generalattack = "0", midposition = "0,4.62", topposition = "0,9.17", bottomposition = "0,0", buffplacer = "68432_0", zjeffect = "68433_0", debut = "68431_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 16, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "34_0.4,31_0.6", admission = "0", scale = "1,2", bgm = "43-antinova", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4400000313;switch2,idle,4400000314", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14000003,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14001] = {id = 14001, name = "恆淨之劍", story = "珂斯嘉德专属的AVG装甲，以教会骑士的铠甲为原型参考设计而成。这套装甲对珂斯嘉德来说有着特殊的象征意义，使得她战斗的时候充满了决心。", attackname = "教會之劍，出鞘！", painter = "/", voiceexcellence = "羊宮妃那", backgroundpic = "ABOriginal/Role/14001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14001", coordinate = "14001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.35", bottomposition = "0,0", buffplacer = "68476_0", zjeffect = "68477_0", debut = "68475_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "10_0.1_7_60_1.4_2_0.6,10_0.15_11_60_1.7_2.4_1,12_0.35_26_60_2.5_3.4_1.9", delay = "35_1", admission = "0", scale = "0.5,1.5", bgm = "69-Cernunnos", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14001001] = {id = 14001001, name = "惡役女的末路", story = "你知道嗎，痛苦於我而言並不是懲罰，這本就是我應該承受的罪責。如果肉體的疼痛可以洗滌心靈的污垢，那便請您的鞭子永遠不要停歇。但請您時刻自省己身，不要沉沒在懲戒的歡愉之中，不然我就要多背負一條罪責。", attackname = "教會之劍，出鞘！", painter = "/", voiceexcellence = "羊宮妃那", backgroundpic = "ABOriginal/Role/14001001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14001001/WatchSpine/Watch_3D_front.prefab", interaction = "14001001", coordinate = "14001001", generalattack = "0", midposition = "0,4.69", topposition = "0,9.35", bottomposition = "0,0", buffplacer = "68469_0", zjeffect = "68470_0", debut = "68468_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "10_0.1_7_60_1.4_2_0.6,10_0.15_11_60_1.7_2.4_1,12_0.35_26_60_2.5_3.4_1.9", delay = "35_1", admission = "0", scale = "1,2", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 0, shopanim = "touch_s1,idle2,4400100109;touch2,idle2,4400100110", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14001001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14002] = {id = 14002, name = "星之騎士", story = "奧菲莉亞的隊長米菈慫恿奧菲莉亞買的衣服，她最初的目的是想看見奧菲莉亞害羞的窘態，沒想到奧菲莉亞會穿著這件衣服和你一起去私人海濱樂園度假。", attackname = "我、我出發了！", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "ABOriginal/Role/14002/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14002", coordinate = "14002", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68515_0;68516_19;68517_33", zjeffect = "68518_0", debut = "68513_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "24-Distantbluesea_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14002001] = {id = 14002001, name = "仲夏！決勝服！", story = "穿過泳裝之後的奧菲莉亞，不知道為什麼又購買了幾件大膽的衣服，難道說她已經開始漸漸意識到了自己的優勢了？", attackname = "哇啊啊，衣服還、還沒換好！", painter = "/", voiceexcellence = "間宮菜南子", backgroundpic = "ABOriginal/Role/14002001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14002001", coordinate = "14002001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68520_0;68521_19;68522_33", zjeffect = "68523_0", debut = "68513_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 0, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "72-desertion_of_summer", shoptag = "0", ismorestate = 1, shopanim = "touch_s1,idle21,4400200109;touch_s2,idle31,4400200110;touch_s301,idle32,4400200125", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14002001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14003] = {id = 14003, name = "寂滅者", story = "伊莉雅珍愛的一套服裝，經過一年的省吃儉用才從市場上淘換到冬季服裝。雖然價格便宜，卻是100%純棉布料，經過卡佳本地老奶奶的手工編制。要是攀附上品牌，放在大城市中售賣，怎麼著也能躋身奢侈品的行列。", attackname = "復仇之火將在你們身上燃燒！", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "ABOriginal/Role/14003/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14003", coordinate = "14003", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68563_0", zjeffect = "68564_0", debut = "68562_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "80-GoodNight", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14003001] = {id = 14003001, name = "夜色的獻禮", story = "夜幕落下，在無人的寂靜角落，一位堅毅的復仇者眼神中卻盛滿了遲疑。她擔憂眼前的輕羅曼紗能否引起領航的注意。畢竟這是她那經復仇之火炙烤過的大腦唯一能想到的報答方式，一次在夜色掩護中的無私獻禮。", attackname = "在夜色中毁灭吧。", painter = "/", voiceexcellence = "彩月ちさと", backgroundpic = "ABOriginal/Role/14003001/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14003001", coordinate = "14003001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68566_0", zjeffect = "68567_0", debut = "68565_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 18, bulletvelocity = "0", strike = "34_0.4_29_60_2.1_2.9_1.4,31_0.35_21_60_2.4_3.1_1", delay = "33_1", admission = "0", scale = "1,2", bgm = "80-GoodNight", shoptag = "0", ismorestate = 1, shopanim = "sw12,idle2,4400300103,100;sw23,idle3,4400300107,100;sw31,idle,4400300111,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14003001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14004] = {id = 14004, name = "旅途的终末", story = "查丽莎专属的AVG装甲。二十年的时间，少女早已不记得什么是急躁，什么是任性。自穿上这身装备的一刻起，她便做好了扛起旗帜的准备。\n“我会带他们走下去，直到世界的尽头，直到旅途的终点。”", attackname = "咆哮吧！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/14004/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14004", coordinate = "14004", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68601_0", zjeffect = "68602_0", debut = "68600_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 25, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "90-Two_Decades_of_Love", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14004001] = {id = 14004001, name = "揭匣後的瘋狂", story = "月白如霜的夜晚，寒风吹不灭的炽热情感。如猎物般被压在身下的你，是否做好了准备？迎接那面具被揭穿后的彻底疯狂。她已经迫不及待想要吸吮，那深藏在血液中美味爱意。", attackname = "熄滅吧！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "ABOriginal/Role/14004001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14004001/WatchSpine/Watch_3D_front.prefab", interaction = "14004001", coordinate = "14004001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68604_0", zjeffect = "68605_0", debut = "68603_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 25, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "90-Two_Decades_of_Love", shoptag = "0", ismorestate = 1, shopanim = "switch12,idle2,4400400106,100;switch23,idle3,4400400112,100;switch31,idle,4400400118,100", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14004001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14004002] = {id = 14004002, name = "新切斯顿管理员", story = "“上月的原罪目击报告增多了……”“东部街道的供电还没有稳定下来吗？”“城防的预算不能再增加了！”“至少食物供给暂时不用愁。”“寻猫启事？谁把这张混进来了？”……果然，管理一座城市从来不是一件简单的事情。", attackname = "咆哮吧！", painter = "/", voiceexcellence = "山田奈都美", backgroundpic = "0", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14004002", coordinate = "14004002", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68601_0", zjeffect = "68602_0", debut = "68600_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 25, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "90-Two_Decades_of_Love", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "1,0,tz_sc_114003_300", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14005] = {id = 14005, name = "無窮之鎖", story = "魔防隊的戰鬥服飾。這身來自家鄉的服飾時時刻刻在提醒著她們的責任和榮耀。", attackname = "現在是——！", painter = "/", voiceexcellence = "鬼頭明裡", backgroundpic = "ABOriginal/Role/14005/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14005", coordinate = "14005", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68620_0", zjeffect = "68621_0", debut = "68619_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14005001] = {id = 14005001, name = "緩解壓力！？", story = "也許正是原罪入侵帶來的緊迫感，駕駛員們才會抓住每一次能慶祝勝利的機會來釋放壓力。在這裡你可以釋放你的喜怒哀樂，把勝利的希望擴散吧。羽前京香——作為這次的大功臣被邀請參與了這一場盛宴。", attackname = "屈服的時間——！", painter = "/", voiceexcellence = "鬼頭明裡", backgroundpic = "ABOriginal/Role/14005001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14005001/WatchSpine/Watch_3D_front.prefab", interaction = "14005001", coordinate = "14005001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68620_0", zjeffect = "68621_0", debut = "68619_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "27-Coffee_House", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4400500103;switch2,idle,4400500109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,14005001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14006] = {id = 14006, name = "“人”之繼承者", story = "說了多少次，我是最完美的“人”，既然是“人”，那麼也就是會有脆弱的時候，也會有需要學習的地方，也會有進步空間，當然也會有創造奇跡的可能性，這樣的我無疑是最強的，對吧？", attackname = "成為人的感覺也不錯。", painter = "/", voiceexcellence = "青戸浩香", backgroundpic = "ABOriginal/Role/14006/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "0", interaction = "14006", coordinate = "14006", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68650_0", zjeffect = "68651_0", debut = "68649_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "2-zhujiemian_MP3", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14006001] = {id = 14006001, name = "夏夜的嫣紅", story = "人類的消遣活動，姑且還算不錯，比我關機等待時間流逝要有樂趣不少。不過我和其他人可不一樣，我只幹最有效率的事情，就比如現在大家正在休息，而我露出肌膚在提升你對我的好感度，我太有效率了。", attackname = "成為人的感覺也不錯。", painter = "/", voiceexcellence = "青戸浩香", backgroundpic = "ABOriginal/Role/14006001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14006001/WatchSpine/Watch_3D_front.prefab", interaction = "14006001", coordinate = "14006001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68650_0", zjeffect = "68651_0", debut = "68649_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "97-Daily_life_of_the_planet", shoptag = "0", ismorestate = 1, shopanim = "level1,idle,4400600112", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14006001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
[14007] = {id = 14007, name = "重燃的火花", story = "伊斯卡拉的AVG裝甲。在能支撐武器系統運轉的前提下盡量保證了防護性，同時還畱下了根據戰況進行自定義的空間。", attackname = "功率提昇，統合式武裝啓動。", painter = "/", voiceexcellence = "二橋奈生", backgroundpic = "ABOriginal/Role/14007/WatchSpine/Watch_3D_bg.prefab", type = 0, foregroundpic = "ABOriginal/Altas/Dynamic/Uiskin/zt10000/Img/kong", interaction = "14007", coordinate = "14007", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68694_0", zjeffect = "68695_0", debut = "68693_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "0.5,1.5", bgm = "77-Only_you", shoptag = "0", ismorestate = 0, shopanim = "0", dragrange = "1920,1080;1920,1080", isdrag = 1, jumpto = "0", switch = 0, "0", "0", "0", "0", "0", "0", "0"},
[14007001] = {id = 14007001, name = "尋常測試與伴生意外", story = "基於第一印象，以及喝醉後被她從酒吧裏攆出去的經驗，硏究員們時常會驚訝於伊斯卡拉那仿佛能接受任何要求的適應力與好脾氣。\n當然，她一如旣往地不擅長處理沒寫在測試須知上的意外。", attackname = "測試用安全限制，解除。", painter = "/", voiceexcellence = "二橋奈生", backgroundpic = "ABOriginal/Role/14007001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14007001/WatchSpine/Watch_3D_front.prefab", interaction = "14007001", coordinate = "14007001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68694_0", zjeffect = "68695_0", debut = "68693_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 15, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "77-Only_you", shoptag = "0", ismorestate = 1, shopanim = "touch1,idle,4400700109", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "3,14007001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
