[14008001] = {id = 14008001, name = "君臨的女王", story = "站在食物鏈頂端的猛獸強行塞進象徵著弱小獵物的服飾裏，這本該是極度不合理的逾越之舉。\n但對於魔防隊的絶對女王來説，不管什麽樣的服裝，都無法改變她身爲統治者的本質。", attackname = "很痛吧？", painter = "/", voiceexcellence = "花澤香菜", backgroundpic = "ABOriginal/Role/14008001/WatchSpine/Watch_3D_bg.prefab", type = 1, foregroundpic = "ABOriginal/Role/14008001/WatchSpine/Watch_3D_front.prefab", interaction = "14008001", coordinate = "14008001", generalattack = "0", midposition = "0,4.53", topposition = "0,9.86", bottomposition = "0,0", buffplacer = "68706_0", zjeffect = "68707_0", debut = "68705_0", ready = "0", death = "0", vertigo = "0", hit = "0", pd_1 = "0", pd_2 = "0", hc_1 = "0", hc_2 = "0", "0", "0", qzoom = "0.4", attackdistance = 10, bulletvelocity = "0", strike = "33_0.4_28_60_2.3_3_1.6", delay = "33_1", admission = "0", scale = "1,2", bgm = "85-In_love", shoptag = "0", ismorestate = 1, shopanim = "switch1,idle2,4400800113;switch2,idle,4400800114", dragrange = "1,1;1920,1080", isdrag = 0, jumpto = "4,14008001,tz_sc_zbsd_01", switch = 1, "0", "0", "0", "0", "0", "0", "0"},
